#[cfg(any(feature = "v8-host", test))]
static NEXT_PAINT_IMAGE_REQUEST_ID: AtomicU64 = AtomicU64::new(1_u64 << 60);
// Upper 32 bits identify a worker incarnation; lower 32 bits identify its
// documents. Neither allocator may wrap into an already-issued identity.
#[cfg(unix)]
fn allocate_worker_generation(counter: &AtomicU64) -> Result<u64, RuntimeError> {
    counter
        .fetch_update(Ordering::AcqRel, Ordering::Acquire, |next| {
            (next > 0 && next <= u64::from(u32::MAX)).then(|| next + 1)
        })
        .map(|generation| generation << 32)
        .map_err(|_| RuntimeError::IdentityExhausted {
            namespace: "worker incarnation".into(),
        })
}

fn advance_document_generation(last_issued: u64, base: u64) -> Result<u64, RuntimeError> {
    last_issued
        .checked_add(1)
        .filter(|next| *next > base && (*next >> 32) == (base >> 32))
        .ok_or_else(|| RuntimeError::IdentityExhausted {
            namespace: "document generation".into(),
        })
}

