// Opt-in native test diagnostics. Records never select execution, invoke author
// code, poll resources, or carry authority. Weak sessions end with their guard.
#[cfg(all(test, feature = "v8-host"))]
pub(crate) mod loading_stage_diagnostics {
    use std::sync::{Arc, Mutex, OnceLock, Weak};
    use std::time::{Duration, Instant};
    #[derive(Clone, Debug, PartialEq, Eq)]
    enum Key {
        Wait(u64, u32, u64, u64),
        Script(String),
    }
    #[derive(Clone, Debug)]
    pub(crate) struct Event {
        pub at: Duration,
        pub phase: &'static str,
        pub detail: String,
    }
    #[derive(Clone, Debug, Default)]
    pub(crate) struct Snapshot {
        pub events: Vec<Event>,
        pub phases: std::collections::BTreeSet<&'static str>,
        pub dropped: usize,
    }
    struct Session {
        key: Key,
        started: Instant,
        snapshot: Snapshot,
    }
    static SESSIONS: OnceLock<Mutex<Vec<Weak<Mutex<Session>>>>> = OnceLock::new();
    pub(crate) struct Guard(Arc<Mutex<Session>>);
    impl Guard {
        fn new(key: Key) -> Self {
            let session = Arc::new(Mutex::new(Session {
                key,
                started: Instant::now(),
                snapshot: Snapshot::default(),
            }));
            let mut sessions = SESSIONS
                .get_or_init(Default::default)
                .lock()
                .unwrap_or_else(|e| e.into_inner());
            sessions.retain(|entry| entry.strong_count() != 0);
            assert!(sessions.len() < 16, "loading diagnostic session capacity");
            sessions.push(Arc::downgrade(&session));
            Self(session)
        }
        pub(crate) fn script(base: &str) -> Self {
            assert!(base.len() <= 4096, "diagnostic fixture URL bound");
            Self::new(Key::Script(base.into()))
        }
        pub(crate) fn wait(
            page: u64,
            scope: &crate::host::webdriver_script::AutomationRealmSnapshot,
        ) -> Self {
            Self::new(Key::Wait(
                page,
                scope.realm.0,
                scope.document_generation,
                scope.stream_epoch,
            ))
        }
        pub(crate) fn snapshot(&self) -> Snapshot {
            self.0
                .lock()
                .unwrap_or_else(|e| e.into_inner())
                .snapshot
                .clone()
        }
    }
    fn record(key: &Key, phase: &'static str, detail: impl FnOnce() -> String) {
        let Some(registry) = SESSIONS.get() else {
            return;
        };
        let sessions = {
            let mut entries = registry.lock().unwrap_or_else(|e| e.into_inner());
            entries.retain(|entry| entry.strong_count() != 0);
            entries.iter().filter_map(Weak::upgrade).collect::<Vec<_>>()
        };
        let mut detail = Some(detail);
        let mut rendered = None;
        for session in sessions {
            let mut session = session.lock().unwrap_or_else(|e| e.into_inner());
            if session.key != *key {
                continue;
            }
            if session.snapshot.phases.len() < 32 {
                session.snapshot.phases.insert(phase);
            }
            if session.snapshot.events.len() >= 256 {
                session.snapshot.events.remove(0);
                session.snapshot.dropped = session.snapshot.dropped.saturating_add(1);
            }
            let at = session.started.elapsed();
            let text = rendered
                .get_or_insert_with(|| {
                    let mut text = detail.take().unwrap()();
                    if text.len() > 1024 {
                        let mut end = 1024;
                        while !text.is_char_boundary(end) {
                            end -= 1
                        }
                        text.truncate(end);
                    }
                    text
                })
                .clone();
            session.snapshot.events.push(Event {
                at,
                phase,
                detail: text,
            });
        }
    }
    pub(crate) fn script(base: Option<&str>, phase: &'static str, detail: impl FnOnce() -> String) {
        if let Some(base) = base.filter(|base| base.len() <= 4096)
            && SESSIONS.get().is_some()
        {
            record(&Key::Script(base.into()), phase, detail)
        }
    }
    pub(super) fn wait(
        page: &super::PageState,
        phase: &'static str,
        detail: impl FnOnce() -> String,
    ) {
        if let Some(scope) = page.frame_scope.as_ref() {
            record(
                &Key::Wait(
                    page.page_id.0,
                    scope.realm.0,
                    scope.document_generation,
                    scope.stream_epoch,
                ),
                phase,
                detail,
            )
        }
    }
    #[test]
    fn loading_diagnostics_are_bounded_isolated_and_end_with_guard() {
        script(Some(&"x".repeat(4097)), "oversized-key", || {
            panic!("oversized key must not render")
        });
        let first = Guard::script("https://diagnostic.test/first");
        let other = Guard::script("https://diagnostic.test/other");
        std::thread::spawn(|| {
            script(
                Some("https://diagnostic.test/first"),
                "cross-thread",
                || "ready".into(),
            )
        })
        .join()
        .unwrap();
        assert_eq!(first.snapshot().events[0].phase, "cross-thread");
        assert_eq!(first.snapshot().events[0].detail, "ready");
        for _ in 0..300 {
            script(Some("https://diagnostic.test/first"), "bounded", || {
                "🧭".repeat(300)
            });
        }
        let result = first.snapshot();
        assert_eq!(result.events.len(), 256);
        assert_eq!(result.dropped, 45);
        assert!(result.phases.contains("cross-thread"));
        assert!(result.phases.contains("bounded"));
        assert!(
            result
                .events
                .windows(2)
                .all(|events| events[0].at <= events[1].at)
        );
        assert!(result.events.iter().all(|event| event.detail.len() <= 1024));
        assert!(other.snapshot().events.is_empty());
        drop(first);
        script(Some("https://diagnostic.test/first"), "late", || {
            panic!("dropped diagnostics must not render")
        });
        let fresh = Guard::script("https://diagnostic.test/first");
        assert!(fresh.snapshot().events.is_empty());
        let selected = Guard::new(Key::Wait(904, 1, 5, 0));
        let sibling = Guard::new(Key::Wait(904, 2, 5, 0));
        let replacement = Guard::new(Key::Wait(904, 1, 6, 0));
        record(&Key::Wait(904, 1, 5, 0), "wait-decision", || "false".into());
        assert_eq!(selected.snapshot().events.len(), 1);
        assert!(sibling.snapshot().events.is_empty());
        assert!(replacement.snapshot().events.is_empty());
        assert!(
            std::panic::catch_unwind(|| {
                let _guard = Guard::script("https://diagnostic.test/unwind");
                panic!("fixture unwind")
            })
            .is_err()
        );
        script(Some("https://diagnostic.test/unwind"), "late", || {
            panic!("unwound diagnostics must not render")
        });
    }
}

