#[derive(Default)]
struct CspReportingState {
    pending: usize,
    deliveries: BTreeMap<String, VecDeque<Instant>>,
}

/// Jobs retain only the cancellation token, never the context owner itself.
#[derive(Default)]
struct CspReportLifetime(Arc<std::sync::atomic::AtomicBool>);
impl Drop for CspReportLifetime {
    fn drop(&mut self) {
        self.0.store(true, Ordering::Release);
    }
}

struct CspReportPermit(Arc<Mutex<CspReportingState>>);
impl Drop for CspReportPermit {
    fn drop(&mut self) {
        let mut state = self
            .0
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        state.pending = state.pending.saturating_sub(1);
    }
}
#[cfg(test)]
thread_local! {static FAIL_CSP_REPORT_SUBMIT:std::cell::Cell<bool>=const{std::cell::Cell::new(false)};}
fn submit_csp_report(job: impl FnOnce() + Send + 'static) -> Result<(), String> {
    #[cfg(test)]
    if FAIL_CSP_REPORT_SUBMIT.with(|failure| failure.replace(false)) {
        return Err("injected report executor admission".into());
    }
    crate::resource_io_executor::submit(job)
}
fn next_csp_report_identity(counter: &AtomicU64) -> Option<u64> {
    counter
        .fetch_update(Ordering::AcqRel, Ordering::Acquire, |id| id.checked_add(1))
        .ok()
}

