/// Demand-driven bridge from the parent-owned network operation into the live
/// html5ever parser. Polling requests data only when the parser needs more input,
/// coupling response demand to parser progress; once html5ever publishes a
/// blocking boundary, JavaScript runs against the same `DomRuntime` before the
/// retained source suffix is consumed.
#[cfg(feature = "v8-host")]
struct NavigationBodyChunks {
    timing: Option<oryn_js::navigation_timing::NavigationTiming>,
    replay: crate::html_encoding_replay::HtmlEncodingReplay,
    operation: crate::network::NetworkOperation,
    decoder: oryn_net::IncrementalTextDecoder,
    encoding: Arc<Mutex<Option<&'static str>>>,
    capture: Arc<Mutex<NavigationBodyCapture>>,
    deadline: Option<Instant>,
    navigation: Option<crate::navigation_control::NavigationEmitter>,
    finished: bool,
    demand_pending: bool,
}

#[cfg(feature = "v8-host")]
impl crate::host::DocumentInput for NavigationBodyChunks {
    fn navigation_timing(&self) -> Option<oryn_js::navigation_timing::NavigationTiming> {
        self.timing.clone()
    }
    fn encoding_confidence(&self) -> oryn_net::HtmlEncodingConfidence {
        self.decoder.html_encoding_confidence()
    }
    fn commit_encoding(&mut self) {
        self.replay.commit(&mut self.decoder)
    }
    fn encoding_restart_needed(&self, label: &str) -> bool {
        self.decoder.html_encoding_restart_needed(label)
    }
    fn restart_encoding(&mut self, label: &str) -> Result<Option<String>, crate::host::HostError> {
        let replay = self.replay.restart(&mut self.decoder, label);
        *self.encoding.lock().expect("navigation encoding") = self.decoder.encoding_name();
        if let Some(text) = &replay {
            self.capture.lock().expect("navigation capture").source = text.clone();
        }
        Ok(replay)
    }
    fn poll_next(&mut self) -> std::task::Poll<Option<Result<String, crate::host::HostError>>> {
        self.poll_available()
    }
}
#[cfg(feature = "v8-host")]
impl NavigationBodyChunks {
    fn finish_input(&mut self) {
        self.finished = true;
        // Closing, rather than merely marking finished, notifies the native
        // broker lease immediately even if the parser retains this adapter.
        // That lease owns cancellation/retry; this path performs no IPC.
        self.operation.events.close();
        self.operation.demand.take();
    }

    fn poll_available(
        &mut self,
    ) -> std::task::Poll<Option<Result<String, crate::host::HostError>>> {
        use std::task::Poll;
        if self.finished {
            return Poll::Ready(None);
        }
        // Bound decoder-only progress so one task cannot monopolize input.
        for _ in 0..32 {
            if self
                .navigation
                .as_ref()
                .is_some_and(|navigation| navigation.checkpoint().is_err())
            {
                self.finish_input();
                return Poll::Ready(Some(Err(crate::host::HostError::LimitExceeded {
                    resource: "controlled navigation stopped".into(),
                })));
            }
            if self
                .deadline
                .is_some_and(|deadline| Instant::now() >= deadline)
            {
                self.finish_input();
                return Poll::Ready(Some(Err(crate::host::HostError::LimitExceeded {
                    resource: "navigation wall time".into(),
                })));
            }
            if !self.demand_pending {
                self.operation.request_body_chunk();
                self.demand_pending = true;
            }
            let event = match self.operation.try_event() {
                Ok(event) => {
                    self.demand_pending = false;
                    Some(event)
                }
                Err(tokio::sync::mpsc::error::TryRecvError::Disconnected) => None,
                Err(tokio::sync::mpsc::error::TryRecvError::Empty) => return Poll::Pending,
            };
            match event {
                Some(crate::network::NetworkEvent::Chunk { request_id, bytes })
                    if request_id == self.operation.request_id =>
                {
                    let decoded = match self.replay.push(&mut self.decoder, &bytes) {
                        Ok(text) => text,
                        Err(error) => {
                            self.finish_input();
                            return Poll::Ready(Some(Err(error)));
                        }
                    };
                    *self.encoding.lock().expect("navigation encoding") =
                        self.decoder.encoding_name();
                    let mut capture = self.capture.lock().expect("navigation capture");
                    capture.bytes = capture.bytes.saturating_add(bytes.len());
                    capture.source.push_str(&decoded);
                    drop(capture);
                    if !decoded.is_empty() {
                        return Poll::Ready(Some(Ok(decoded)));
                    }
                }
                Some(crate::network::NetworkEvent::Complete {
                    encoded_body_size,
                    request_id,
                }) if request_id == self.operation.request_id => {
                    self.finish_input();
                    let tail = self.replay.finish(&mut self.decoder);
                    *self.encoding.lock().expect("navigation encoding") =
                        self.decoder.encoding_name();
                    let mut capture = self.capture.lock().expect("navigation capture");
                    capture.source.push_str(&tail);
                    capture.completed = true;
                    if let Some(timing) = &self.timing {
                        timing.finish_encoded(
                            Instant::now(),
                            capture.bytes as u64,
                            encoded_body_size,
                        );
                    }
                    drop(capture);
                    return Poll::Ready((!tail.is_empty()).then_some(Ok(tail)));
                }
                Some(crate::network::NetworkEvent::Failed { request_id, error })
                    if request_id == self.operation.request_id =>
                {
                    self.finish_input();
                    return Poll::Ready(Some(Err(crate::host::HostError::Execution(format!(
                        "navigation body failed: {error}"
                    )))));
                }
                Some(crate::network::NetworkEvent::Headers { request_id, .. })
                    if request_id == self.operation.request_id =>
                {
                    self.finish_input();
                    return Poll::Ready(Some(Err(crate::host::HostError::Execution(
                        "network operation emitted duplicate response headers".into(),
                    ))));
                }
                Some(_) => {
                    self.finish_input();
                    return Poll::Ready(Some(Err(crate::host::HostError::Execution(
                        "navigation operation received a stale or unmatched completion".into(),
                    ))));
                }
                None => {
                    self.finish_input();
                    return Poll::Ready(Some(Err(crate::host::HostError::Execution(
                        "network operation ended before response completion".into(),
                    ))));
                }
            }
        }
        Poll::Pending
    }
}

// Dropping the original operation receiver delegates cancellation to its
// native IdentityBroker/service-stream custody. No destructor performs IPC.

#[cfg(all(test, feature = "v8-host"))]
mod navigation_input_tests {
    use super::*;
    use crate::{
        host::DocumentInput,
        network::{NetworkEvent, NetworkOperation},
    };
    use std::task::Poll;
    #[test]
    fn terminal_navigation_input_releases_receiver_while_adapter_is_retained() {
        for malformed in [false, true] {
            let (sender, events) = tokio::sync::mpsc::channel(4);
            let (demand, mut requests) = tokio::sync::mpsc::channel(4);
            let mut input = NavigationBodyChunks {
                timing: None,
                replay: Default::default(),
                operation: NetworkOperation {
                    body_demand_pending: Default::default(),
                    prefetched: Default::default(),
                    request_id: 7,
                    events,
                    demand: Some(demand),
                },
                decoder: oryn_net::IncrementalTextDecoder::new(
                    Some("text/html"),
                    oryn_net::TextResourceKind::Html,
                ),
                capture: Default::default(),
                encoding: Default::default(),
                deadline: (!malformed).then(Instant::now),
                navigation: None,
                finished: false,
                demand_pending: false,
            };
            if malformed {
                sender
                    .try_send(NetworkEvent::Chunk {
                        request_id: 8,
                        bytes: vec![1].into(),
                    })
                    .unwrap();
            }
            assert!(matches!(input.poll_next(), Poll::Ready(Some(Err(_)))));
            assert!(
                sender.is_closed(),
                "terminal input must release producer without dropping adapter"
            );
            assert!(input.operation.demand.is_none());
            if malformed {
                assert!(requests.try_recv().is_ok());
            }
            assert!(matches!(
                requests.try_recv(),
                Err(tokio::sync::mpsc::error::TryRecvError::Disconnected)
            ));
            assert!(matches!(input.poll_next(), Poll::Ready(None)));
            assert!(!input.capture.lock().unwrap().completed);
        }
    }

    #[test]
    fn expired_navigation_input_retains_native_cancel_retry_until_acknowledged() {
        #[derive(Default)]
        struct TransportState {
            sender: Option<tokio::sync::mpsc::Sender<NetworkEvent>>,
            started: Option<u64>,
            attempts: Vec<u64>,
        }
        struct HeldTransport(Arc<Mutex<TransportState>>);
        impl NetworkBroker for HeldTransport {
            fn send(
                &self,
                _: NetworkRequest,
            ) -> Result<NetworkResponse, crate::network::NetworkError> {
                unreachable!("operation transport only")
            }
            fn start_operation(
                &self,
                request: NetworkRequest,
            ) -> Result<NetworkOperation, crate::network::NetworkError> {
                let (sender, events) = tokio::sync::mpsc::channel(4);
                let mut state = self.0.lock().unwrap();
                state.sender = Some(sender);
                state.started = Some(request.request_id);
                Ok(NetworkOperation {
                    body_demand_pending: Default::default(),
                    prefetched: Default::default(),
                    request_id: request.request_id,
                    events,
                    demand: None,
                })
            }
            fn cancel_operation(&self, id: u64) -> Result<(), crate::network::NetworkError> {
                let mut state = self.0.lock().unwrap();
                state.attempts.push(id);
                if state.attempts.len() == 1 {
                    return Err(crate::network::NetworkError::Transport(
                        "retry cancellation".into(),
                    ));
                }
                state.sender.take();
                Ok(())
            }
        }
        let state = Arc::new(Mutex::new(TransportState::default()));
        let broker = SharedNetworkBroker::new(HeldTransport(state.clone()));
        let operation = broker
            .start_operation(NetworkRequest {
                request_id: 7,
                method: "GET".into(),
                url: "https://example.test/".into(),
                headers: Vec::new(),
                body: Vec::new(),
                credentials: false,
                security: Default::default(),
                resolved_addrs: Vec::new(),
            })
            .unwrap();
        let mut input = NavigationBodyChunks {
            timing: None,
            replay: Default::default(),
            operation,
            decoder: oryn_net::IncrementalTextDecoder::new(
                Some("text/html"),
                oryn_net::TextResourceKind::Html,
            ),
            capture: Default::default(),
            encoding: Default::default(),
            deadline: Some(Instant::now()),
            navigation: None,
            finished: false,
            demand_pending: false,
        };
        assert!(matches!(input.poll_next(), Poll::Ready(Some(Err(_)))));
        broker
            .drain_owned_operations(Duration::from_secs(2))
            .unwrap();
        let state = state.lock().unwrap();
        assert_eq!(state.attempts, vec![state.started.unwrap(); 2]);
        assert!(state.sender.is_none());
        // The terminal parser adapter is deliberately still alive here.
        assert!(matches!(input.poll_next(), Poll::Ready(None)));
    }
    #[test]
    fn pending_navigation_input_does_not_repeat_demand_and_preserves_partial_decode() {
        let (sender, events) = tokio::sync::mpsc::channel(4);
        let (demand, mut requests) = tokio::sync::mpsc::channel(4);
        let capture = Arc::new(Mutex::new(NavigationBodyCapture::default()));
        let mut input = NavigationBodyChunks {
            timing: None,
            replay: Default::default(),
            operation: NetworkOperation {
                body_demand_pending: Default::default(),
                prefetched: Default::default(),
                request_id: 7,
                events,
                demand: Some(demand),
            },
            decoder: oryn_net::IncrementalTextDecoder::new(
                Some("text/html;charset=utf-8"),
                oryn_net::TextResourceKind::Html,
            ),
            capture: capture.clone(),
            encoding: Default::default(),
            deadline: None,
            navigation: None,
            finished: false,
            demand_pending: false,
        };
        assert!(matches!(input.poll_next(), Poll::Pending));
        assert!(requests.try_recv().is_ok());
        assert!(matches!(input.poll_next(), Poll::Pending));
        assert!(requests.try_recv().is_err());
        sender
            .try_send(NetworkEvent::Chunk {
                request_id: 7,
                bytes: b"<p>first</p>".to_vec().into(),
            })
            .unwrap();
        let first = input.poll_next();
        assert!(matches!(first, Poll::Pending | Poll::Ready(Some(Ok(_)))));
        assert_eq!(capture.lock().unwrap().bytes, 12);
        sender
            .try_send(NetworkEvent::Complete {
                encoded_body_size: None,
                request_id: 7,
            })
            .unwrap();
        assert!(matches!(
            input.poll_next(),
            Poll::Ready(None) | Poll::Ready(Some(Ok(_)))
        ));
        assert!(capture.lock().unwrap().completed);
        assert_eq!(capture.lock().unwrap().source, "<p>first</p>");
        assert!(matches!(input.poll_next(), Poll::Ready(None)));
    }
}

use oryn_js::origin::Origin as SecurityOrigin;

fn native_storage_partition(context_id: u64, origin: &SecurityOrigin) -> String {
    let site = Url::parse(&origin.serialize())
        .ok()
        .and_then(|url| crate::cookies::SchemefulSite::from_url(&url));
    match site {
        Some(site) => serde_json::json!([context_id, "site", site.scheme, site.registrable_domain])
            .to_string(),
        None => serde_json::json!([context_id, "origin", origin.security_token_key()]).to_string(),
    }
}

