/// Exact parent authorization custody. Dropping an older operation cannot
/// revoke a replacement operation's grant for the same page.
#[cfg(unix)]
pub(crate) struct NavigationChainGrant {
    context: std::sync::Weak<BrowserContextInner>,
    page_id: PageId,
    identity: Arc<()>,
}
#[cfg(unix)]
impl std::fmt::Debug for NavigationChainGrant {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("NavigationChainGrant")
            .field("page_id", &self.page_id)
            .finish_non_exhaustive()
    }
}
#[cfg(unix)]
impl Drop for NavigationChainGrant {
    fn drop(&mut self) {
        if let Some(context) = self.context.upgrade() {
            let mut grants = context
                .navigation_grants
                .lock()
                .unwrap_or_else(|error| error.into_inner());
            if grants
                .get(&self.page_id)
                .is_some_and(|identity| Arc::ptr_eq(identity, &self.identity))
            {
                grants.remove(&self.page_id);
            }
        }
    }
}

