#[cfg(unix)]
struct WorkerPool {
    lifecycle: WorkerLifecycle,
    idle: Mutex<Vec<crate::worker_client::WorkerClient>>,
    live: AtomicUsize,
}

#[cfg(unix)]
impl std::fmt::Debug for WorkerPool {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("WorkerPool")
            .field("lifecycle", &self.lifecycle)
            .field("live", &self.live.load(Ordering::Acquire))
            .finish_non_exhaustive()
    }
}

#[cfg(unix)]
impl WorkerPool {
    fn new(lifecycle: WorkerLifecycle) -> Self {
        Self {
            lifecycle,
            idle: Mutex::new(Vec::new()),
            live: AtomicUsize::new(0),
        }
    }

    fn checkout(
        &self,
        config: &BrowserConfig,
        context: &ContextOptions,
        page_id: PageId,
        opener_page_id: Option<PageId>,
        context_owner: BrowserContext,
    ) -> Result<crate::worker_client::WorkerClient, RuntimeError> {
        let mut idle = self
            .idle
            .lock()
            .map_err(|_| RuntimeError::WorkerCrashed("worker pool lock poisoned".into()))?;
        if let Some(mut client) = idle.pop() {
            drop(idle);
            if let Err(error) =
                client.rebind(config, context, page_id, opener_page_id, context_owner)
            {
                self.live.fetch_sub(1, Ordering::AcqRel);
                return Err(error);
            }
            return Ok(client);
        }
        let capacity = match self.lifecycle {
            WorkerLifecycle::IsolatedPrewarmed { capacity }
            | WorkerLifecycle::Recycled { capacity, .. } => capacity,
            WorkerLifecycle::IsolatedOnDemand => usize::MAX,
        };
        self.live
            .fetch_update(Ordering::AcqRel, Ordering::Acquire, |live| {
                (live < capacity).then_some(live + 1)
            })
            .map_err(|_| RuntimeError::WorkerLimitExceeded {
                resource: "worker pool capacity".into(),
            })?;
        // Keep the empty-idle check and reservation atomic with prepare().
        // Otherwise prepare can fill the pool between them and checkout can
        // report exhaustion while a prepared worker is actually available.
        drop(idle);
        match crate::worker_client::WorkerClient::spawn(
            config,
            context,
            page_id,
            opener_page_id,
            context_owner,
        ) {
            Ok(client) => Ok(client),
            Err(error) => {
                self.live.fetch_sub(1, Ordering::AcqRel);
                Err(error)
            }
        }
    }

    fn prepare(&self, config: &BrowserConfig) -> Result<(), RuntimeError> {
        let capacity = match self.lifecycle {
            WorkerLifecycle::IsolatedPrewarmed { capacity }
            | WorkerLifecycle::Recycled { capacity, .. } => capacity,
            WorkerLifecycle::IsolatedOnDemand => return Ok(()),
        };
        // Publish prepared workers atomically with respect to checkout. A
        // reserved-but-not-yet-ready worker must not cause false exhaustion.
        let mut idle = self
            .idle
            .lock()
            .map_err(|_| RuntimeError::WorkerCrashed("worker pool lock poisoned".into()))?;
        while self.live.load(Ordering::Acquire) < capacity {
            if self
                .live
                .fetch_update(Ordering::AcqRel, Ordering::Acquire, |live| {
                    (live < capacity).then_some(live + 1)
                })
                .is_err()
            {
                break;
            }
            let owner = Browser::in_process_with_config(BrowserConfig {
                worker_lifecycle: WorkerLifecycle::IsolatedOnDemand,
                ..config.clone()
            })
            .new_context();
            let mut worker = match crate::worker_client::WorkerClient::spawn(
                config,
                &ContextOptions::default(),
                PageId::LEGACY,
                None,
                owner,
            ) {
                Ok(worker) => worker,
                Err(error) => {
                    self.live.fetch_sub(1, Ordering::AcqRel);
                    return Err(error);
                }
            };
            if let Err(error) = worker.reset() {
                self.live.fetch_sub(1, Ordering::AcqRel);
                return Err(error);
            }
            worker.mark_prepared();
            idle.push(worker);
        }
        Ok(())
    }

    fn recycle(&self, client: crate::worker_client::WorkerClient) {
        let max_leases = match self.lifecycle {
            WorkerLifecycle::Recycled { max_leases, .. } => max_leases,
            _ => 0,
        };
        if client.leases() >= max_leases {
            self.live.fetch_sub(1, Ordering::AcqRel);
            return;
        }
        if let Ok(mut idle) = self.idle.lock() {
            idle.push(client);
        } else {
            self.live.fetch_sub(1, Ordering::AcqRel);
        }
    }

    fn discard(&self, client: crate::worker_client::WorkerClient) {
        drop(client);
        self.live.fetch_sub(1, Ordering::AcqRel);
    }
}

#[derive(Debug)]
struct PageRecord {
    hidden_prerender: bool,
    prerender_source: Option<PageId>,
    created_by_web_content: bool,
    is_closing: bool,
    #[cfg(unix)]
    history_projection: Option<script_close_history_projection::Projection>,
    #[cfg(unix)]
    history_projection_wake: Arc<script_close_history_projection::WaitSignal>,
    physical_close_complete: bool,
    physical_close: Arc<tokio::sync::Mutex<()>>,
    script_close: Option<Arc<crate::script_close_custody::Job>>,
    #[cfg(unix)]
    queued_navigations: Arc<crate::queued_navigation::Custody>,
    target_name: String,
    sandbox_navigator: Option<(PageId, oryn_js::message_wire::WindowTarget)>,
    drag_feedback: oryn_js::drag_image::Controller,
    pending_drag_feedback: Vec<oryn_js::drag_image::Feedback>,
    navigation: Arc<crate::navigation_control::NavigationControl>,
    prompts: Arc<oryn_js::prompts::PromptController>,
    handle: PageHandle,
    descriptor: PageDescriptor,
}

impl PageRecord {
    fn is_live(&self) -> bool {
        !matches!(
            self.descriptor.status,
            PageStatus::Closed | PageStatus::Crashed
        )
    }

    fn update_document(&mut self, page: &PageInfo, revision: Revision) {
        // The parent owns browsing-context identity and opener relationships.
        // A renderer observation can update document data, never placement or
        // authority by replacing the entire PageInfo supplied at registration.
        if self.descriptor.page.document_generation != page.document_generation {
            self.drag_feedback.clear();
            self.pending_drag_feedback.clear();
        }
        self.descriptor.page.url = page.url.clone();
        self.descriptor.page.title = page.title.clone();
        self.descriptor.page.document_generation = page.document_generation;
        self.descriptor.revision = revision;
    }
}

#[derive(Debug)]
struct ContextGroup {
    #[cfg(unix)]
    direct_actor_routes: Mutex<
        BTreeMap<
            PageId,
            (
                crate::worker_route::WorkerRoute,
                crate::worker_route::WorkerRoute,
            ),
        >,
    >,
    opener_targets: Mutex<BTreeMap<PageId, oryn_js::message_wire::WindowTarget>>,
    popup_cookie_sites: Mutex<BTreeMap<PageId, (PageId, String)>>,
    browsing_groups: Mutex<crate::browsing_groups::BrowsingGroups>,
    shared_memory: Arc<Mutex<crate::shared_memory::SharedMemoryRegistry>>,
    pages: Mutex<BTreeMap<PageId, PageRecord>>,
    messages: Mutex<oryn_js::message_wire::MessageHub>,
    active: Mutex<Option<PageId>>,
    events: Mutex<Vec<PageLifecycleEvent>>,
    notify: Notify,
}

impl ContextGroup {
    fn new() -> Self {
        let shared_memory = Arc::new(Mutex::new(
            crate::shared_memory::SharedMemoryRegistry::default(),
        ));
        let mut messages = oryn_js::message_wire::MessageHub::default();
        #[cfg(unix)]
        messages.set_shared_message_backend(Arc::new(crate::shared_memory::SharedMessageBackend(
            shared_memory.clone(),
        )));
        Self {
            #[cfg(unix)]
            direct_actor_routes: Mutex::new(BTreeMap::new()),
            browsing_groups: Mutex::new(crate::browsing_groups::BrowsingGroups::default()),
            opener_targets: Mutex::new(BTreeMap::new()),
            popup_cookie_sites: Mutex::new(BTreeMap::new()),
            shared_memory,
            pages: Mutex::new(BTreeMap::new()),
            messages: Mutex::new(messages),
            active: Mutex::new(None),
            events: Mutex::new(Vec::new()),
            notify: Notify::new(),
        }
    }

    fn register(&self, params: PageRegistrationInputs<'_>) -> Result<(), RuntimeError> {
        let PageRegistrationInputs {
            handle,
            opener_page_id,
            activate,
            attention_required,
            document_generation,
            native_origin,
            creator,
            target_name,
            sandbox_navigator,
            hidden_prerender,
        } = params;

        let page_id = PageId(handle.id);
        if activate {
            *self.active.lock().expect("active page lock") = Some(page_id);
        }
        let descriptor = PageDescriptor {
            page: PageInfo {
                page_id,
                opener_page_id,
                url: "about:blank".into(),
                title: String::new(),
                document_generation,
            },
            active: activate,
            status: if attention_required {
                PageStatus::AttentionRequired
            } else {
                PageStatus::Open
            },
            revision: Revision(0),
        };
        let mut pages = self.pages.lock().expect("page group lock");
        if let Some((opener, creator, expected_origin)) = creator {
            if !pages.get(&opener).is_some_and(|record| record.is_live()) {
                return Err(RuntimeError::PageNotFound(opener));
            }
            let oryn_js::worker_wire::Creator::Window {
                target,
                document_generation,
                stream_epoch,
            } = creator
            else {
                return Err(RuntimeError::ProtocolViolation(
                    "popup requires native Window".into(),
                ));
            };
            let hub = self.messages.lock().map_err(|_| {
                RuntimeError::ContextService("popup authority lock poisoned".into())
            })?;
            let frame_origin = match target {
                oryn_js::message_wire::WindowTarget::Root => {
                    hub.root_document_authority(opener.0, *document_generation, *stream_epoch)
                        .map_err(RuntimeError::ContextService)?;
                    None
                }
                oryn_js::message_wire::WindowTarget::Frame(frame) => Some(
                    hub.frame_document_authority(
                        opener.0,
                        frame,
                        *document_generation,
                        *stream_epoch,
                    )
                    .map_err(RuntimeError::ContextService)?
                    .1,
                ),
            };
            drop(hub);
            let origin = match frame_origin {
                Some(origin) => origin,
                None => {
                    self.browsing_groups
                        .lock()
                        .map_err(|_| {
                            RuntimeError::ContextService("popup group lock poisoned".into())
                        })?
                        .snapshot(opener)
                        .ok_or(RuntimeError::PageNotFound(opener))?
                        .origin
                }
            };
            if origin != expected_origin {
                return Err(RuntimeError::ProtocolViolation(
                    "popup creator origin changed during admission".into(),
                ));
            }
        }
        self.browsing_groups
            .lock()
            .expect("browsing group lock")
            .register(page_id, opener_page_id, native_origin)
            .map_err(RuntimeError::ContextService)?;
        if activate {
            for record in pages.values_mut() {
                record.descriptor.active = false;
            }
        }
        pages.insert(
            page_id,
            PageRecord {
                prerender_source: if hidden_prerender {
                    creator.as_ref().map(|(page, _, _)| *page)
                } else {
                    None
                },
                hidden_prerender,
                created_by_web_content: creator.is_some(),
                is_closing: false,
                #[cfg(unix)]
                history_projection: None,
                #[cfg(unix)]
                history_projection_wake: Default::default(),
                physical_close_complete: false,
                physical_close: Default::default(),
                script_close: None,
                #[cfg(unix)]
                queued_navigations: Default::default(),
                target_name,
                sandbox_navigator,
                drag_feedback: Default::default(),
                pending_drag_feedback: Vec::new(),
                navigation: Arc::new(crate::navigation_control::NavigationControl::default()),
                prompts: Arc::new(oryn_js::prompts::PromptController::new()),
                handle: handle.detached_clone(),
                descriptor: descriptor.clone(),
            },
        );
        drop(pages);
        if !hidden_prerender {
            self.push_event(PageLifecycleEvent::Opened { page: descriptor });
        }
        Ok(())
    }

    fn push_event(&self, event: PageLifecycleEvent) {
        self.events.lock().expect("page event lock").push(event);
        self.notify.notify_waiters();
    }

    fn descriptors(&self) -> Vec<PageDescriptor> {
        self.pages
            .lock()
            .expect("page group lock")
            .values()
            .filter(|record| !record.hidden_prerender)
            .map(|record| record.descriptor.clone())
            .collect()
    }

    fn handle(&self, page_id: PageId) -> Option<PageHandle> {
        self.pages
            .lock()
            .expect("page group lock")
            .get(&page_id)
            .filter(|record| {
                !matches!(
                    record.descriptor.status,
                    PageStatus::Closed | PageStatus::Crashed
                )
            })
            .map(|record| record.handle.retained_clone())
    }

    fn activate(&self, page_id: PageId) -> Result<PageHandle, RuntimeError> {
        let mut pages = self.pages.lock().expect("page group lock");
        let handle = pages
            .get(&page_id)
            .filter(|record| {
                !record.hidden_prerender
                    && !matches!(
                        record.descriptor.status,
                        PageStatus::Closed | PageStatus::Crashed
                    )
            })
            .map(|record| record.handle.retained_clone())
            .ok_or(RuntimeError::PageNotFound(page_id))?;
        for record in pages.values_mut() {
            record.descriptor.active = record.descriptor.page.page_id == page_id;
            if record.descriptor.active && record.descriptor.status == PageStatus::AttentionRequired
            {
                record.descriptor.status = PageStatus::Open;
            }
        }
        *self.active.lock().expect("active page lock") = Some(page_id);
        drop(pages);
        self.push_event(PageLifecycleEvent::Activated { page_id });
        Ok(handle)
    }

    fn update_observation(&self, observation: &Observation) {
        let mut pages = self.pages.lock().expect("page group lock");
        let Some(record) = pages.get_mut(&observation.page.page_id) else {
            return;
        };
        if !record.is_live() {
            return;
        }
        record.update_document(&observation.page, observation.revision);
    }

    fn update_navigation(&self, navigation: &NavigationResult) {
        let mut pages = self.pages.lock().expect("page group lock");
        let Some(record) = pages.get_mut(&navigation.page_id) else {
            return;
        };
        if !record.is_live() {
            return;
        }
        record.descriptor.page.url = navigation.final_url.clone();
        record.descriptor.page.title = navigation.title.clone();
        record.descriptor.page.document_generation = navigation.document_generation;
        record.descriptor.revision = navigation.revision;
        if record.hidden_prerender {
            return;
        }
        // Publish while the state transition is serialized with close/crash.
        self.push_event(PageLifecycleEvent::Navigated {
            page_id: navigation.page_id,
            url: navigation.final_url.clone(),
            document_generation: navigation.document_generation,
        });
    }

    fn update_loaded(&self, page: PageInfo, revision: Revision) {
        let mut pages = self.pages.lock().expect("page group lock");
        let Some(record) = pages.get_mut(&page.page_id) else {
            return;
        };
        if !record.is_live() {
            return;
        }
        record.update_document(&page, revision);
        if record.hidden_prerender {
            return;
        }
        self.push_event(PageLifecycleEvent::Navigated {
            page_id: page.page_id,
            url: page.url,
            document_generation: page.document_generation,
        });
    }

    fn update_revision(&self, page_id: PageId, revision: Revision) {
        let mut pages = self.pages.lock().expect("page group lock");
        if let Some(record) = pages.get_mut(&page_id)
            && record.is_live()
        {
            record.descriptor.revision = revision;
        }
    }

    fn close(&self, page_id: PageId) -> bool {
        self.close_if(page_id, |_| Ok(()))
            .expect("unconditional page close")
    }
    fn close_if(
        &self,
        page_id: PageId,
        admit: impl FnOnce(&PageRecord) -> Result<(), RuntimeError>,
    ) -> Result<bool, RuntimeError> {
        let mut pages = self.pages.lock().expect("page group lock");
        let Some(record) = pages.get_mut(&page_id) else {
            return Ok(false);
        };
        admit(record)?;
        if record.descriptor.status == PageStatus::Closed {
            return Ok(false);
        }
        self.messages
            .lock()
            .unwrap_or_else(|error| error.into_inner())
            .retire_page(page_id.0);
        record.prompts.retire();
        #[cfg(unix)]
        record.queued_navigations.retire();
        let _ = record.navigation.retire();
        record.drag_feedback.clear();
        record.pending_drag_feedback.clear();
        record.descriptor.status = PageStatus::Closed;
        record.descriptor.active = false;
        let hidden = record.hidden_prerender;
        let should_replace_active = self
            .active
            .lock()
            .expect("active page lock")
            .is_some_and(|active| active == page_id);
        if should_replace_active {
            let replacement = pages
                .values_mut()
                .find(|record| {
                    !record.hidden_prerender && record.descriptor.status == PageStatus::Open
                })
                .map(|record| {
                    record.descriptor.active = true;
                    record.descriptor.page.page_id
                });
            *self.active.lock().expect("active page lock") = replacement;
        }
        drop(pages);
        if !hidden {
            self.push_event(PageLifecycleEvent::Closed { page_id });
        }
        Ok(true)
    }

    fn crash(&self, page_id: PageId, detail: String) {
        let mut pages = self.pages.lock().expect("page group lock");
        let Some(record) = pages.get_mut(&page_id) else {
            return;
        };
        if matches!(
            record.descriptor.status,
            PageStatus::Closed | PageStatus::Crashed
        ) {
            return;
        }
        self.messages
            .lock()
            .unwrap_or_else(|error| error.into_inner())
            .retire_page(page_id.0);
        record.prompts.retire();
        #[cfg(unix)]
        record.queued_navigations.retire();
        let _ = record.navigation.retire();
        record.drag_feedback.clear();
        record.pending_drag_feedback.clear();
        record.descriptor.status = PageStatus::Crashed;
        record.descriptor.active = false;
        let hidden = record.hidden_prerender;
        record.descriptor.page.document_generation =
            record.descriptor.page.document_generation.saturating_add(1);
        let mut active = self.active.lock().expect("active page lock");
        if *active == Some(page_id) {
            *active = pages
                .values_mut()
                .find(|record| {
                    !record.hidden_prerender && record.descriptor.status == PageStatus::Open
                })
                .map(|record| {
                    record.descriptor.active = true;
                    record.descriptor.page.page_id
                });
        }
        drop(active);
        drop(pages);
        if !hidden {
            self.push_event(PageLifecycleEvent::Crashed { page_id, detail });
        }
    }

    #[cfg(unix)]
    fn worker_started(&self, page_id: PageId, document_generation: u64) {
        let active_page = *self.active.lock().expect("active page lock");
        let mut pages = self.pages.lock().expect("page group lock");
        let Some(record) = pages.get_mut(&page_id) else {
            return;
        };
        // A delayed startup completion cannot resurrect a page whose close
        // already retired its authority. Crashed pages may restart explicitly.
        if record.descriptor.status == PageStatus::Closed {
            return;
        }
        let replaced = record.descriptor.status == PageStatus::Crashed && !record.hidden_prerender;
        record.descriptor.status = PageStatus::Open;
        record.descriptor.active = active_page == Some(page_id);
        record.descriptor.page.url = "about:blank".into();
        record.descriptor.page.title.clear();
        record.descriptor.page.document_generation = document_generation;
        record.descriptor.revision = Revision(0);
        drop(pages);
        if replaced {
            self.push_event(PageLifecycleEvent::Navigated {
                page_id,
                url: "about:blank".into(),
                document_generation,
            });
        }
    }

    fn matching_page(&self, predicate: &PagePredicate) -> Option<PageHandle> {
        self.pages
            .lock()
            .expect("page group lock")
            .values()
            .find(|record| {
                !record.hidden_prerender
                    && !matches!(
                        record.descriptor.status,
                        PageStatus::Closed | PageStatus::Crashed
                    )
                    && page_matches(&record.descriptor, predicate)
            })
            .map(|record| record.handle.retained_clone())
    }
}

fn page_matches(page: &PageDescriptor, predicate: &PagePredicate) -> bool {
    match predicate {
        PagePredicate::Any => true,
        PagePredicate::Id { page_id } => page.page.page_id == *page_id,
        PagePredicate::Origin { origin } => Url::parse(&page.page.url)
            .ok()
            .map(|url| url.origin().ascii_serialization())
            .is_some_and(|value| value == *origin),
        PagePredicate::UrlContains { value } => page.page.url.contains(value),
        PagePredicate::TitleContains { value } => page.page.title.contains(value),
        PagePredicate::Opener { page_id } => page.page.opener_page_id == Some(*page_id),
    }
}

#[cfg(unix)]
struct PendingWorkerRequest<'a>(&'a AtomicUsize);

#[cfg(unix)]
impl Drop for PendingWorkerRequest<'_> {
    fn drop(&mut self) {
        self.0.fetch_sub(1, Ordering::Release);
    }
}

#[cfg(unix)]
impl std::fmt::Debug for WorkerPage {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.debug_struct("WorkerPage").finish_non_exhaustive()
    }
}

#[cfg(unix)]
#[derive(Debug, PartialEq, Eq)]
enum WorkerCloseOutcome {
    Closed,
    ReapedAfterRssLimit,
    ReapedAfterProcessExit,
}

#[cfg(unix)]
impl WorkerPage {
    fn execution_retired(&self) -> bool {
        self.retired.load(Ordering::Acquire)
            || self
                .context
                .upgrade()
                .is_none_or(|context| context.workers_retired.load(Ordering::Acquire))
    }

    fn interrupt_inflight(&self) -> bool {
        if self.pending.load(Ordering::Acquire) == 0 {
            return false;
        }
        let process_id = self.process_id.load(Ordering::Acquire);
        if process_id == 0 {
            return false;
        }
        // Production page workers are disposable security boundaries. Killing
        // a busy worker is the only operation permitted to bypass its serial
        // page command channel; replacement starts with a blank generation.
        unsafe { libc::kill(process_id.cast_signed(), libc::SIGKILL) == 0 }
    }

    fn enter_queue(&self) -> Result<PendingWorkerRequest<'_>, RuntimeError> {
        if self.execution_retired() {
            return Err(RuntimeError::Closed);
        }
        let capacity = self.config.worker_queue_capacity.clamp(1, 32);
        self.pending
            .fetch_update(Ordering::AcqRel, Ordering::Acquire, |pending| {
                (pending < capacity).then_some(pending + 1)
            })
            .map_err(|_| RuntimeError::WorkerLimitExceeded {
                resource: "command queue".into(),
            })?;
        Ok(PendingWorkerRequest(&self.pending))
    }

    fn request(
        &self,
        request: crate::worker::WorkerRequest,
    ) -> Result<crate::worker::WorkerResponse, RuntimeError> {
        let _pending = self.enter_queue()?;
        let mut client = self
            .client
            .lock()
            .map_err(|_| RuntimeError::WorkerCrashed("worker client lock poisoned".into()))?;
        if self.execution_retired() {
            return Err(RuntimeError::Closed);
        }
        if client.is_none() {
            if self.related_admission.is_some() {
                return Err(RuntimeError::Closed);
            }
            let mut config = self.config.clone();
            config.document_generation_base = allocate_worker_generation(&NEXT_WORKER_GENERATION)?;
            let context_owner = self
                .context
                .upgrade()
                .map(|inner| BrowserContext { inner })
                .ok_or(RuntimeError::Closed)?;
            let spawned = if matches!(
                config.worker_lifecycle,
                WorkerLifecycle::IsolatedPrewarmed { .. } | WorkerLifecycle::Recycled { .. }
            ) {
                self.worker_pool.checkout(
                    &config,
                    &self.options,
                    self.page_id,
                    self.opener_page_id,
                    context_owner,
                )?
            } else {
                crate::worker_client::WorkerClient::spawn(
                    &config,
                    &self.options,
                    self.page_id,
                    self.opener_page_id,
                    context_owner,
                )?
            };
            self.process_id
                .store(spawned.process_id(), Ordering::Release);
            *self
                .exit_evidence
                .lock()
                .unwrap_or_else(|error| error.into_inner()) = None;
            *self.attachment.lock().map_err(|_| {
                RuntimeError::WorkerCrashed("worker attachment lock poisoned".into())
            })? = Some(Arc::new(spawned.attachment()));
            *client = Some(spawned);
            if let Some(context) = self.context.upgrade() {
                context
                    .group
                    .worker_started(self.page_id, config.document_generation_base);
            }
        }
        // Retirement may race a launch whose PID was not yet available to
        // interrupt_inflight. Do not send a page command after that launch.
        if self.execution_retired() {
            if let Some(active) = client.take() {
                if matches!(
                    self.config.worker_lifecycle,
                    WorkerLifecycle::IsolatedPrewarmed { .. } | WorkerLifecycle::Recycled { .. }
                ) {
                    self.worker_pool.discard(active);
                } else {
                    drop(active);
                }
            }
            self.process_id.store(0, Ordering::Release);
            return Err(RuntimeError::Closed);
        }
        let result = client
            .as_mut()
            .expect("worker initialized")
            .request(request);
        if matches!(
            result,
            Err(RuntimeError::WorkerCrashed(_)
                | RuntimeError::WorkerLimitExceeded { .. }
                | RuntimeError::ProtocolViolation(_))
        ) {
            let pooled = matches!(
                self.config.worker_lifecycle,
                WorkerLifecycle::IsolatedPrewarmed { .. } | WorkerLifecycle::Recycled { .. }
            );
            if let Some(failed) = client.as_ref()
                && let Ok(evidence) = failed.checked_exit_evidence()
            {
                *self
                    .exit_evidence
                    .lock()
                    .unwrap_or_else(|error| error.into_inner()) = Some(evidence);
            }
            match (client.take(), pooled) {
                (Some(failed), true) => self.worker_pool.discard(failed),
                (Some(failed), false) => drop(failed),
                (None, _) => {}
            }
            self.process_id.store(0, Ordering::Release);
        }
        result
    }

    fn retire(&self) {
        self.retired.store(true, Ordering::Release);
        self.interrupt_inflight();
        let mut client = self
            .client
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if let Some(active) = client.take() {
            if matches!(
                self.config.worker_lifecycle,
                WorkerLifecycle::IsolatedPrewarmed { .. } | WorkerLifecycle::Recycled { .. }
            ) {
                self.worker_pool.discard(active);
            } else {
                drop(active);
            }
        }
        self.process_id.store(0, Ordering::Release);
    }

    fn checked_close_result(
        &self,
        active: &mut crate::worker_client::WorkerClient,
        response: Result<crate::worker::WorkerResponse, RuntimeError>,
    ) -> Result<WorkerCloseOutcome, RuntimeError> {
        match response {
            Ok(crate::worker::WorkerResponse::Closed) => {
                self.close_failure
                    .lock()
                    .unwrap_or_else(|error| error.into_inner())
                    .take();
                Ok(WorkerCloseOutcome::Closed)
            }
            Ok(response) => {
                let error = unexpected_worker_response(response);
                *self
                    .close_failure
                    .lock()
                    .unwrap_or_else(|error| error.into_inner()) = Some(error.clone());
                Err(error)
            }
            Err(error) if matches!(error.root_cause(), RuntimeError::ProtocolViolation(_)) => {
                *self
                    .close_failure
                    .lock()
                    .unwrap_or_else(|error| error.into_inner()) = Some(error.clone());
                Err(error)
            }
            Err(error)
                if matches!(error.root_cause(), RuntimeError::WorkerCrashed(_))
                    || matches!(error.root_cause(), RuntimeError::WorkerLimitExceeded { resource } if resource == "RSS") =>
            {
                // This is a physical-retirement result, never an invented IPC
                // acknowledgement. Preserve the policy failure while requiring
                // the exact child and every retained broker scope to be settled.
                if let Some(previous) = self
                    .close_failure
                    .lock()
                    .unwrap_or_else(|error| error.into_inner())
                    .clone()
                    && matches!(previous.root_cause(), RuntimeError::ProtocolViolation(_))
                {
                    return Err(previous);
                }
                *self
                    .close_failure
                    .lock()
                    .unwrap_or_else(|error| error.into_inner()) = Some(error.clone());
                let detail = error.to_string();
                if let Some(context) = self.context.upgrade() {
                    context.group.crash(self.page_id, detail.clone());
                }
                let mut evidence = active.checked_terminal_cleanup().map_err(|cleanup| {
                    RuntimeError::ContextService(format!(
                        "worker retirement after {detail} is incomplete: {cleanup}"
                    ))
                })?;
                evidence["operational_error"] = serde_json::Value::String(detail);
                let (outcome, kind) = match error.root_cause() {
                    RuntimeError::WorkerLimitExceeded { .. } => (
                        WorkerCloseOutcome::ReapedAfterRssLimit,
                        "reaped_after_rss_limit",
                    ),
                    _ => (
                        WorkerCloseOutcome::ReapedAfterProcessExit,
                        "reaped_after_process_exit",
                    ),
                };
                evidence["retirement_kind"] = serde_json::json!(kind);
                *self.exit_evidence.lock().map_err(|_| {
                    RuntimeError::WorkerCrashed("exit evidence lock poisoned".into())
                })? = Some(evidence);
                Ok(outcome)
            }
            Err(error) => Err(error),
        }
    }

    fn cancel_pending_for_close(
        active: &mut crate::worker_client::WorkerClient,
        retirement: &mut Option<RuntimeError>,
    ) -> Result<bool, RuntimeError> {
        if retirement.is_some() {
            return Ok(false);
        }
        match active.cancel_pending_initialization() {
            Ok(cancelled) => Ok(cancelled),
            Err(cancellation) => match active.observed_process_exit() {
                Ok(Some(status)) => {
                    // The child exited after the first observation. Preserve
                    // this cancellation failure as part of the terminal cause;
                    // the caller must still complete checked physical cleanup.
                    *retirement = Some(RuntimeError::WorkerCrashed(format!(
                        "worker exited with {status}; pending environment cancellation failed: {cancellation}"
                    )));
                    Ok(false)
                }
                Ok(None) => Err(cancellation),
                Err(observation) => Err(RuntimeError::ContextService(format!(
                    "{cancellation}; observing worker exit failed: {observation}"
                ))),
            },
        }
    }

    fn remember_protocol_close_failure(&self, error: &RuntimeError) {
        if matches!(error.root_cause(), RuntimeError::ProtocolViolation(_)) {
            *self
                .close_failure
                .lock()
                .unwrap_or_else(|error| error.into_inner()) = Some(error.clone());
        }
    }

    fn close(&self) -> Result<WorkerCloseOutcome, RuntimeError> {
        self.retired.store(true, Ordering::Release);
        let mut client = self
            .client
            .lock()
            .map_err(|_| RuntimeError::WorkerCrashed("worker client lock poisoned".into()))?;
        let prior_close_failure = self
            .close_failure
            .lock()
            .unwrap_or_else(|error| error.into_inner())
            .clone();
        let Some(mut active) = client.take() else {
            if let Some(error) = prior_close_failure
                && matches!(error.root_cause(), RuntimeError::ProtocolViolation(_))
            {
                self.remember_protocol_close_failure(&error);
                return Err(error);
            }
            return Ok(WorkerCloseOutcome::Closed);
        };
        let mut process_retirement = prior_close_failure
            .clone()
            .filter(|error| !matches!(error.root_cause(), RuntimeError::ProtocolViolation(_)));
        if process_retirement.is_none() {
            // Process-wide revocation can remove a reserved child's grant.
            // Only an observed exit of this exact owned Child permits taking
            // physical cleanup instead of the live environment protocol.
            match active.observed_process_exit() {
                Ok(Some(status)) => {
                    if let Some(error) = &prior_close_failure {
                        // Process death cannot turn a rejected protocol reply
                        // into a successful close on the next attempt.
                        *client = Some(active);
                        return Err(error.clone());
                    }
                    process_retirement = Some(RuntimeError::WorkerCrashed(format!(
                        "worker exited with {status}"
                    )));
                }
                Ok(None) => {}
                Err(error) => {
                    *client = Some(active);
                    self.remember_protocol_close_failure(&error);
                    return Err(error);
                }
            }
        }
        match Self::cancel_pending_for_close(&mut active, &mut process_retirement) {
            Ok(true) => {
                if let Some(error) = &prior_close_failure {
                    *client = Some(active);
                    return Err(error.clone());
                }
                self.process_id.store(0, Ordering::Release);
                self.attachment
                    .lock()
                    .unwrap_or_else(|error| error.into_inner())
                    .take();
                return Ok(WorkerCloseOutcome::Closed);
            }
            Ok(false) => {}
            Err(error) => {
                *client = Some(active);
                self.remember_protocol_close_failure(&error);
                return Err(error);
            }
        }
        if active.has_sibling_environments() || self.related_admission.is_some() {
            let response = process_retirement
                .clone()
                .map_or_else(|| active.request(crate::worker::WorkerRequest::Close), Err);
            let outcome = match self.checked_close_result(&mut active, response) {
                Ok(outcome) => outcome,
                Err(error) => {
                    // Keep exact custody for failed acknowledgement or cleanup.
                    *client = Some(active);
                    self.remember_protocol_close_failure(&error);
                    return Err(error);
                }
            };
            self.process_id.store(0, Ordering::Release);
            self.attachment
                .lock()
                .unwrap_or_else(|error| error.into_inner())
                .take();
            // Related children never own their parent's pool slot.
            if self.related_admission.is_none()
                && matches!(
                    self.config.worker_lifecycle,
                    WorkerLifecycle::Recycled { .. } | WorkerLifecycle::IsolatedPrewarmed { .. }
                )
            {
                self.worker_pool.live.fetch_sub(1, Ordering::AcqRel);
            }
            drop(active);
            return Ok(outcome);
        }
        if process_retirement.is_none()
            && matches!(
                self.config.worker_lifecycle,
                WorkerLifecycle::Recycled { .. }
            )
        {
            // Reset continues to require its own encoded identity-bearing ACK.
            if let Err(error) = active.reset() {
                *client = Some(active);
                self.remember_protocol_close_failure(&error);
                return Err(error);
            }
            self.process_id.store(0, Ordering::Release);
            self.attachment
                .lock()
                .unwrap_or_else(|error| error.into_inner())
                .take();
            self.close_failure
                .lock()
                .unwrap_or_else(|error| error.into_inner())
                .take();
            self.worker_pool.recycle(active);
            return Ok(WorkerCloseOutcome::Closed);
        }
        let response = process_retirement
            .clone()
            .map_or_else(|| active.request(crate::worker::WorkerRequest::Close), Err);
        let outcome = match self.checked_close_result(&mut active, response) {
            Ok(outcome) => outcome,
            Err(error) => {
                // A response deadline can already reap the isolated child.
                // Clear stale custody only after checking reap and route drain;
                // preserve the deadline error rather than inventing a Close ACK.
                if matches!(error.root_cause(), RuntimeError::WorkerLimitExceeded { resource } if resource.contains("wall time"))
                    && let Ok(mut evidence) = active.checked_terminal_cleanup()
                {
                    evidence["operational_error"] = serde_json::json!(error.to_string());
                    *self.exit_evidence.lock().unwrap_or_else(|error| error.into_inner()) = Some(evidence);
                    self.process_id.store(0, Ordering::Release);
                    self.attachment.lock().unwrap_or_else(|error| error.into_inner()).take();
                    drop(active);
                    return Err(error);
                }
                *client = Some(active);
                self.remember_protocol_close_failure(&error);
                return Err(error);
            }
        };
        self.process_id.store(0, Ordering::Release);
        self.attachment
            .lock()
            .unwrap_or_else(|error| error.into_inner())
            .take();
        if matches!(
            self.config.worker_lifecycle,
            WorkerLifecycle::IsolatedPrewarmed { .. } | WorkerLifecycle::Recycled { .. }
        ) {
            self.worker_pool.discard(active);
            if outcome == WorkerCloseOutcome::Closed
                && let Err(error) = self.worker_pool.prepare(&self.config)
            {
                self.remember_protocol_close_failure(&error);
                return Err(error);
            }
        }
        Ok(outcome)
    }
}

