#[cfg(all(test, feature = "v8-host"))]
fn repair44_diagnostic_prefix(value: &str) -> &str {
    let mut end = value.len().min(256);
    while !value.is_char_boundary(end) {
        end -= 1;
    }
    &value[..end]
}

#[cfg(test)]
fn repair44_bounded_diagnostic(args: std::fmt::Arguments<'_>) -> String {
    use std::fmt::Write;
    struct Buffer(String);
    impl std::fmt::Write for Buffer {
        fn write_str(&mut self, value: &str) -> std::fmt::Result {
            let remaining = 1008usize.saturating_sub(self.0.len());
            let mut end = value.len().min(remaining);
            while !value.is_char_boundary(end) {
                end -= 1;
            }
            self.0.push_str(&value[..end]);
            if end < value.len() {
                Err(std::fmt::Error)
            } else {
                Ok(())
            }
        }
    }
    let mut buffer = Buffer(String::with_capacity(1024));
    if buffer.write_fmt(args).is_err() {
        buffer.0.push_str(" [truncated]");
    }
    buffer.0
}

