    #[cfg(unix)]
    pub(crate) fn cookie_header_for_creator(
        &self,
        page: PageId,
        creator: &oryn_js::worker_wire::Creator,
        url: &Url,
        method: &str,
        kind: crate::cookies::CookieRequestKind,
    ) -> Result<Option<String>, RuntimeError> {
        let oryn_js::worker_wire::Creator::Window {
            target,
            document_generation,
            stream_epoch,
        } = creator
        else {
            return Err(RuntimeError::ProtocolViolation(
                "cookie initiator must be a Window".into(),
            ));
        };
        let (owner, _, origin) =
            self.window_worker_creator(page, target, *document_generation, *stream_epoch)?;
        let policy =
            self.window_worker_policy(page, target, *document_generation, *stream_epoch)?;
        let mut ancestors = self.window_ancestor_urls(&owner)?;
        ancestors.push(if origin.opaque {
            "about:blank".into()
        } else {
            policy.url.clone()
        });
        let security = crate::cookies::CookieRequestContext {
            kind,
            initiator_url: (!origin.opaque).then_some(policy.url),
            top_level_url: Some(self.page_url(page)?),
            ancestor_urls: ancestors,
            ..Default::default()
        };
        let result = self
            .inner
            .parent_cookies
            .as_ref()
            .and_then(|cookies| cookies.header_for_method(url, method, &security).0);
        self.window_worker_creator(page, target, *document_generation, *stream_epoch)?;
        Ok(result)
    }

    pub fn webdriver_cookies(
        &self,
        page: PageId,
        snapshot: &crate::host::webdriver_script::AutomationRealmSnapshot,
        delete: bool,
    ) -> Result<Vec<serde_json::Value>, RuntimeError> {
        #[cfg(unix)]
        {
            let target = Self::webdriver_snapshot_target(snapshot)?;
            let (owner, _, origin) = self.window_worker_creator(
                page,
                &target,
                snapshot.document_generation,
                snapshot.document_authority_epoch,
            )?;
            let ancestors = self.window_ancestor_urls(&owner)?;
            #[cfg(test)]
            webdriver_cookie_admission_fault(self, page);
            self.with_window_worker_creator(
                page,
                &target,
                snapshot.document_generation,
                snapshot.document_authority_epoch,
                true,
                |(_, _, current), selected_url, top_url| {
                    if current != origin {
                        return Err(RuntimeError::Closed);
                    }
                    if current.opaque {
                        return Ok(Vec::new());
                    }
                    let selected_url = selected_url.ok_or_else(|| {
                        RuntimeError::ContextService("cookie document URL missing".into())
                    })?;
                    let url = Url::parse(&selected_url)
                        .map_err(|error| RuntimeError::ContextService(error.to_string()))?;
                    let mut ancestors = ancestors;
                    ancestors.push(selected_url.clone());
                    let security = crate::cookies::CookieRequestContext {
                        dns_timing: None,
                        initiator_url: Some(selected_url),
                        top_level_url: top_url,
                        ancestor_urls: ancestors,
                        ..Default::default()
                    };
                    self.inner
                        .parent_cookies
                        .as_ref()
                        .map(|store| {
                            store
                                .webdriver_cookies_with_context(&url, &security, delete)
                                .map_err(|error| RuntimeError::ContextService(error.to_string()))
                        })
                        .unwrap_or_else(|| Ok(Vec::new()))
                },
            )
        }
        #[cfg(not(unix))]
        {
            let _ = (page, snapshot, delete);
            Err(RuntimeError::EvaluationUnavailable)
        }
    }

    #[cfg(unix)]
    pub(crate) fn document_cookie_for_creator(
        &self,
        page: PageId,
        creator: &oryn_js::worker_wire::Creator,
        value: Option<String>,
    ) -> Result<String, RuntimeError> {
        let oryn_js::worker_wire::Creator::Window {
            target,
            document_generation,
            stream_epoch,
        } = creator
        else {
            return Err(RuntimeError::ProtocolViolation(
                "document cookie requires Window authority".into(),
            ));
        };
        let (owner, _, origin) =
            self.window_worker_creator(page, target, *document_generation, *stream_epoch)?;
        if origin.opaque {
            return Err(RuntimeError::ContextService(
                "SecurityError: opaque document cannot access cookies".into(),
            ));
        }
        let (_, _, policy) = self
            .native_worker_authority(&owner)
            .map_err(|error| RuntimeError::ContextService(error.to_string()))?;
        let url = Url::parse(&policy.url)
            .map_err(|error| RuntimeError::ContextService(error.to_string()))?;
        let mut ancestors = self.window_ancestor_urls(&owner)?;
        ancestors.push(policy.url.clone());
        let cookie_context = crate::cookies::CookieRequestContext {
            dns_timing: None,
            initiator_url: Some(policy.url),
            top_level_url: Some(self.page_url(page)?),
            ancestor_urls: ancestors,
            ..Default::default()
        };
        self.with_window_worker_creator(
            page,
            target,
            *document_generation,
            *stream_epoch,
            true,
            |(_, _, current), selected, top| {
                if current != origin {
                    return Err(RuntimeError::Closed);
                }
                let mut context = cookie_context;
                context.top_level_url = top;
                if let Some(selected) = selected {
                    context.initiator_url = Some(selected);
                }
                if let Some(value) = value {
                    self.inner
                        .parent_cookies
                        .as_ref()
                        .ok_or_else(|| {
                            RuntimeError::ContextService("cookie store is unavailable".into())
                        })?
                        .store_document_cookie_with_context(&url, &context, value)
                        .map_err(|error| RuntimeError::ContextService(error.to_string()))?;
                    Ok(String::new())
                } else {
                    Ok(self
                        .inner
                        .parent_cookies
                        .as_ref()
                        .and_then(|cookies| cookies.document_header_with_context(&url, &context))
                        .unwrap_or_default())
                }
            },
        )
    }

    #[cfg(unix)]
    #[cfg(test)]
    pub(crate) fn document_cookie(&self, page_id: PageId) -> Result<String, RuntimeError> {
        if self.is_opaque_origin(page_id)? {
            return Err(RuntimeError::ContextService(
                "SecurityError: sandboxed opaque origins cannot access document.cookie".into(),
            ));
        }
        let url = Url::parse(&self.page_url(page_id)?)
            .map_err(|error| RuntimeError::ContextService(error.to_string()))?;
        Ok(self
            .inner
            .parent_cookies
            .as_ref()
            .and_then(|cookies| cookies.document_header(&url))
            .unwrap_or_default())
    }

