#[cfg(feature = "v8-host")]
#[derive(Debug, Clone, Copy)]
enum PaintImageTarget {
    Page(usize),
    ForeignObject { object: usize, node: usize },
}

#[cfg(feature = "v8-host")]
impl PaintImageTarget {
    fn assign(self, snapshot: &mut PaintSnapshot, image: usize) {
        let node = match self {
            Self::Page(index) => snapshot.nodes.get_mut(index),
            Self::ForeignObject { object, node } => snapshot
                .svg_foreign_objects
                .get_mut(object)
                .and_then(|object| object.nodes.get_mut(node)),
        };
        if let Some(node) = node {
            node.image_resource = Some(image);
        }
    }
}

