#[cfg(feature = "v8-host")]
enum NavigationReply {
    JointEvents(
        crate::navigation_control::NavigationEmitter,
        Option<oneshot::Sender<Result<(), RuntimeError>>>,
    ),
    Execution(oryn_js::navigation::NavigationExecutionObserver, u64),
    // An action keeps its admission reply; this separate terminal receipt fences
    // subsequent document commands and preserves the original execution observer.
    ActionNavigation {
        completion: oneshot::Sender<Result<NavigationResult, RuntimeError>>,
        previous: Option<Box<NavigationReply>>,
    },
    Controlled(oneshot::Sender<Result<(), RuntimeError>>),
    Navigation(oneshot::Sender<Result<NavigationResult, RuntimeError>>),
    Html(oneshot::Sender<Result<(Revision, PageInfo), RuntimeError>>),
}
#[cfg(feature = "v8-host")]
impl NavigationReply {
    fn is_closed(&self) -> bool {
        match self {
            Self::JointEvents(emitter, _) => emitter.cached_stop().is_some(),
            Self::Execution(..) => false,
            Self::ActionNavigation {
                completion,
                previous,
            } => completion.is_closed() || previous.as_ref().is_some_and(|reply| reply.is_closed()),
            Self::Controlled(reply) => reply.is_closed(),
            Self::Navigation(reply) => reply.is_closed(),
            Self::Html(reply) => reply.is_closed(),
        }
    }
    fn complete(self, state: &mut PageState, result: Result<NavigationResult, RuntimeError>) {
        match self {
            Self::JointEvents(emitter, reply) => {
                use crate::navigation_control::NavigationEvent;
                let publication = match &result {
                    Ok(result) => emitter
                        .publish(NavigationEvent::Committed {
                            document_generation: result.document_generation,
                            url: result.final_url.clone(),
                        })
                        .and_then(|_| {
                            emitter.publish(NavigationEvent::Interactive {
                                document_generation: result.document_generation,
                            })
                        })
                        .and_then(|_| {
                            emitter.publish(NavigationEvent::Complete {
                                document_generation: result.document_generation,
                            })
                        }),
                    Err(error) => {
                        emitter.publish(NavigationEvent::Stopped(error.navigation_stop()))
                    }
                };
                if state
                    .active_navigation
                    .as_ref()
                    .is_some_and(|active| active.same_job(&emitter))
                {
                    state.active_navigation = None;
                    state.navigation_committed = false;
                }
                if let Some(reply) = reply {
                    let result = result.map(|_| ()).and_then(|_| {
                        publication.map_err(|error| RuntimeError::Network(error.to_string()))
                    });
                    let _ = reply.send(result);
                }
            }
            Self::Execution(observer, source_generation) => observer.complete(match result {
                Ok(result) if result.document_generation == source_generation => {
                    oryn_js::navigation::NavigationExecutionOutcome::Completed
                }
                Ok(result) => oryn_js::navigation::NavigationExecutionOutcome::Committed {
                    document_generation: result.document_generation,
                },
                Err(RuntimeError::NavigationCancelled) => {
                    oryn_js::navigation::NavigationExecutionOutcome::Canceled
                }
                Err(error) => oryn_js::navigation::NavigationExecutionOutcome::Failed {
                    message: error.to_string(),
                },
            }),
            Self::ActionNavigation {
                completion,
                previous,
            } => {
                // Deliver the existing navigation observer exactly once, retaining
                // the typed failure for the action fence rather than reissuing input.
                if let Some(previous) = previous {
                    previous.complete(state, result.clone());
                }
                let _ = completion.send(result);
            }
            Self::Controlled(reply) => {
                let _ = reply.send(result.map(|_| ()));
            }
            Self::Navigation(reply) => {
                let _ = reply.send(result);
            }
            Self::Html(reply) => {
                let result = result.map(|_| {
                    (
                        Revision(state.revision),
                        state.observation(ProjectionProfile::Compact).page,
                    )
                });
                let _ = reply.send(result);
            }
        }
    }
}

#[cfg(feature = "v8-host")]
struct JointNavigationPublication {
    terminal: bool,
    result: Result<NavigationResult, RuntimeError>,
    phase: u8,
    acknowledgement: Option<crate::navigation_control::PendingNavigationAck>,
}
#[cfg(feature = "v8-host")]
impl JointNavigationPublication {
    fn poll(
        &mut self,
        emitter: &crate::navigation_control::NavigationEmitter,
    ) -> std::task::Poll<Result<(), RuntimeError>> {
        use crate::navigation_control::NavigationEvent;
        loop {
            if let Some(ack) = &self.acknowledgement {
                match ack.poll() {
                    std::task::Poll::Pending => return std::task::Poll::Pending,
                    std::task::Poll::Ready(Err(error)) => {
                        return std::task::Poll::Ready(Err(RuntimeError::Network(
                            error.to_string(),
                        )));
                    }
                    std::task::Poll::Ready(Ok(())) => {
                        self.acknowledgement = None;
                        self.phase += 1;
                    }
                }
            }
            if !self.terminal && self.phase >= 2 {
                return std::task::Poll::Ready(Ok(()));
            }
            let event = match &self.result {
                Ok(result) => match self.phase {
                    0 => NavigationEvent::Committed {
                        document_generation: result.document_generation,
                        url: result.final_url.clone(),
                    },
                    1 => NavigationEvent::Interactive {
                        document_generation: result.document_generation,
                    },
                    2 => NavigationEvent::Complete {
                        document_generation: result.document_generation,
                    },
                    _ => return std::task::Poll::Ready(Ok(())),
                },
                Err(error) => {
                    if self.phase == 0 {
                        NavigationEvent::Stopped(error.navigation_stop())
                    } else {
                        return std::task::Poll::Ready(Ok(()));
                    }
                }
            };
            match emitter.publish_pending(event) {
                Ok(ack) => self.acknowledgement = Some(ack),
                Err(error) => {
                    return std::task::Poll::Ready(Err(RuntimeError::Network(error.to_string())));
                }
            }
        }
    }
}

