    #[test]
    fn context_websocket_endpoint_uses_immutable_fixture_route_and_policy() {
        let routes = crate::network::EndpointRoutes::new([(
            "wss".into(),
            "web-platform.test".into(),
            8889,
            "10.0.0.2".parse().unwrap(),
        )])
        .unwrap();
        let browser = super::Browser::new()
            .with_fixture_network(Vec::new(), routes)
            .unwrap();
        let mut options = super::ContextOptions::loopback_test();
        options.network_policy.allow_private_networks = true;
        let allowed = browser.new_audited_context_with_isolated_auxiliaries(options);
        let url = url::Url::parse("wss://web-platform.test:8889/socket").unwrap();
        assert_eq!(
            allowed.resolve_network_endpoint(&url).unwrap(),
            vec!["10.0.0.2:8889".parse::<std::net::SocketAddr>().unwrap()]
        );
        assert!(
            allowed
                .resolve_network_endpoint(
                    &url::Url::parse("wss://nonexistent.web-platform.test:8889/").unwrap()
                )
                .is_err()
        );
        let denied = browser.new_context();
        assert!(denied.resolve_network_endpoint(&url).is_err());
        assert!(allowed.fixture_ca_pem().is_some());
        assert!(
            super::Browser::new()
                .new_context()
                .fixture_ca_pem()
                .is_none()
        );
    }

