    #[cfg(feature = "v8-host")]
    #[test]
    fn native_layout_input_borrows_shared_arena_but_owns_document_projection() {
        use crate::dom::NodeKind;
        let mut parsed = crate::html::parse(
            "<main id=parent>parent</main><section id=child><base href='https://child.test/assets/'><style>section{color:red}</style><span>before</span></section>",
        );
        let child = parsed
            .dom
            .iter()
            .find_map(|(id, node)| {
                (node.attributes.get_null("id").map(String::as_str) == Some("child")).then_some(id)
            })
            .unwrap();
        let child_document = parsed.dom.insert(NodeKind::Document);
        parsed.dom.append_child(child_document, child).unwrap();
        let project = |dom: &crate::dom::DomArena, root| {
            super::layout_input_from_dom(
                dom,
                root,
                Default::default(),
                Default::default(),
                Default::default(),
                Default::default(),
                &[],
            )
        };
        let parent_input = project(&parsed.dom, parsed.document);
        let child_input = project(&parsed.dom, child_document);
        assert_eq!(parent_input.document_base_url, "about:blank");
        assert!(parent_input.stylesheets.is_empty());
        assert!(parent_input.nodes.iter().all(|node| node.tag != "section"));
        assert_eq!(child_input.document_base_url, "https://child.test/assets/");
        assert_eq!(child_input.stylesheets, vec!["section{color:red}"]);
        assert!(child_input.nodes.iter().all(|node| node.tag != "main"));
        let text = parsed
            .dom
            .descendants_inclusive(child)
            .unwrap()
            .into_iter()
            .find(|id| matches!(&parsed.dom.get(*id).unwrap().kind, NodeKind::Text { data } if data == "before"))
            .unwrap();
        if let NodeKind::Text { data } = &mut parsed.dom.get_mut(text).unwrap().kind {
            *data = "after".into();
        }
        let updated = project(&parsed.dom, child_document);
        drop(parsed);
        let span_text = |input: &oryn_layout::LayoutInput| {
            input
                .nodes
                .iter()
                .find(|node| node.tag == "span")
                .unwrap()
                .text
                .clone()
        };
        assert_eq!(span_text(&child_input), "before");
        assert_eq!(span_text(&updated), "after");
    }

    #[cfg(feature = "v8-host")]
    #[test]
    fn native_layout_input_transports_ordered_text_children() {
        use oryn_layout::LayoutContent;
        let document = crate::html::parse("<span id='target'>before<em>inside</em>after</span>");
        let input = super::layout_input(
            &document,
            Default::default(),
            Default::default(),
            Default::default(),
            Default::default(),
            &[],
        );
        let target = input
            .nodes
            .iter()
            .find(|node| node.attributes.get("id").is_some_and(|id| id == "target"))
            .unwrap();
        let content = target.content.as_ref().unwrap();
        assert_eq!(content.len(), 3);
        let LayoutContent::Text {
            node_id: first,
            text: before,
        } = &content[0]
        else {
            panic!("leading text lost")
        };
        let LayoutContent::Element(child) = content[1] else {
            panic!("element order lost")
        };
        let LayoutContent::Text {
            node_id: last,
            text: after,
        } = &content[2]
        else {
            panic!("trailing text lost")
        };
        assert_eq!(before, "before");
        assert_eq!(after, "after");
        assert_ne!(first, last);
        assert_eq!(target.children, vec![child]);
        assert_eq!(
            input
                .nodes
                .iter()
                .find(|node| node.id == child)
                .unwrap()
                .text,
            "inside"
        );
        let restored: oryn_layout::LayoutInput =
            serde_json::from_slice(&serde_json::to_vec(&input).unwrap()).unwrap();
        assert_eq!(input, restored);
        let mut reordered = input.clone();
        reordered
            .nodes
            .iter_mut()
            .find(|node| node.id == target.id)
            .unwrap()
            .content
            .as_mut()
            .unwrap()
            .swap(0, 2);
        assert_ne!(
            input, reordered,
            "layout cache must detect order-only changes"
        );
    }

    #[cfg(feature = "v8-host")]
    #[test]
    fn native_shadow_snapshot_keeps_closed_tree_sheets_and_slot_identity() {
        let mut document = crate::html::parse(
            "<div id=host><span id=light>assigned</span></div><section id=source><style>p{width:27px}</style><slot></slot><p id=inside>shadow</p></section>",
        );
        let find = |dom: &crate::dom::DomArena, name: &str| {
            dom.iter()
                .find_map(|(id, node)| {
                    (node.attributes.get_null("id").map(String::as_str) == Some(name)).then_some(id)
                })
                .unwrap()
        };
        let host = find(&document.dom, "host");
        let source = find(&document.dom, "source");
        let light = find(&document.dom, "light");
        let inside = find(&document.dom, "inside");
        let shadow = document.dom.insert(crate::dom::NodeKind::ShadowRoot {
            mode: crate::dom::ShadowMode::Closed,
            clonable: false,
        });
        document.dom.append_child(host, shadow).unwrap();
        for child in document.dom.get(source).unwrap().children.clone() {
            document.dom.append_child(shadow, child).unwrap();
        }
        let adopted = document.dom.insert(crate::dom::NodeKind::Text {
            data: "p{height:19px}".into(),
        });
        document
            .dom
            .get_mut(shadow)
            .unwrap()
            .adopted_stylesheets
            .push(adopted);
        let input = super::layout_input(
            &document,
            Default::default(),
            Default::default(),
            Default::default(),
            Default::default(),
            &[],
        );
        let packed = super::pack_node_id(shadow);
        assert_eq!(
            input.shadow_trees.roots[&packed].host,
            super::pack_node_id(host)
        );
        assert_eq!(
            input.shadow_trees.node_scopes[&super::pack_node_id(inside)],
            packed
        );
        assert!(
            input
                .shadow_trees
                .assigned_slots
                .contains_key(&super::pack_node_id(light))
        );
        assert_eq!(
            input
                .shadow_trees
                .stylesheet_scopes
                .values()
                .filter(|root| **root == packed)
                .count(),
            2
        );
        assert!(
            input
                .nodes
                .iter()
                .find(|node| node.id == super::pack_node_id(inside))
                .unwrap()
                .parent
                .is_none()
        );
        let output = oryn_layout::compute(&input, &Default::default()).unwrap();
        assert_eq!(
            output.computed_styles[&super::pack_node_id(inside)]
                .get("width")
                .map(String::as_str),
            Some("27px")
        );
        let restored: oryn_layout::LayoutInput =
            serde_json::from_slice(&serde_json::to_vec(&input).unwrap()).unwrap();
        assert_eq!(restored, input);
    }

    #[cfg(feature = "v8-host")]
    #[test]
    fn native_video_poster_intrinsics_follow_showing_poster_without_replacing_video_dimensions() {
        let mut document = crate::html::parse("<video id='poster'></video>");
        let snapshot = |document: &ParsedDocument| {
            super::layout_input(
                document,
                Default::default(),
                Default::default(),
                Default::default(),
                Default::default(),
                &[],
            )
        };
        let input = snapshot(&document);
        let id = input
            .nodes
            .iter()
            .find(|node| node.attributes.get("id").is_some_and(|id| id == "poster"))
            .unwrap()
            .id;
        let node = crate::dom::NodeId {
            slot: id as u32,
            generation: (id >> 32) as u32,
        };
        {
            let record = document.dom.get_mut(node).unwrap();
            record.image_dimensions = Some((320, 240));
            record.media_poster_dimensions = Some((123, 123));
            record.showing_poster = true;
        }
        assert_eq!(
            snapshot(&document)
                .nodes
                .iter()
                .find(|node| node.id == id)
                .unwrap()
                .intrinsic_image_size,
            Some((123, 123))
        );
        document.dom.get_mut(node).unwrap().showing_poster = false;
        assert_eq!(
            snapshot(&document)
                .nodes
                .iter()
                .find(|node| node.id == id)
                .unwrap()
                .intrinsic_image_size,
            Some((320, 240))
        );
        assert_eq!(
            document.dom.get(node).unwrap().image_dimensions,
            Some((320, 240))
        );
    }

    #[test]
    fn native_layout_input_transports_canvas_bitmap_dimensions() {
        let document = crate::html::parse(
            "<canvas id='default'></canvas><canvas id='sized' width=' +80px' height='40.9' style='width:500px'></canvas><canvas id='zero' width='0' height='0'></canvas><canvas id='invalid' width='-1' height='2147483648'></canvas>",
        );
        let input = super::layout_input(
            &document,
            Default::default(),
            Default::default(),
            Default::default(),
            Default::default(),
            &[],
        );
        for (id, dimensions) in [
            ("default", (300, 150)),
            ("sized", (80, 40)),
            ("zero", (0, 0)),
            ("invalid", (300, 150)),
        ] {
            let canvas = input
                .nodes
                .iter()
                .find(|node| node.attributes.get("id").is_some_and(|value| value == id))
                .unwrap();
            assert_eq!(canvas.intrinsic_image_size, Some(dimensions), "{id}");
        }
    }

    #[cfg(feature = "v8-host")]
    #[tokio::test(flavor = "current_thread")]
    async fn last_public_page_owner_releases_context_with_active_timers() {
        let context = super::Browser::new().new_context();
        let weak = context.downgrade();
        let page = context.new_page();
        let sibling = context.new_page();
        page.load_html(
            "https://lifetime.test/",
            "<script>setInterval(() => {}, 1)</script><p>Alive</p>",
        )
        .await
        .unwrap();
        drop(context);
        assert!(weak.upgrade().is_some());
        assert_eq!(
            page.evaluate("document.querySelector('p').textContent")
                .await
                .unwrap(),
            serde_json::json!("Alive")
        );
        drop(page);
        assert!(
            weak.upgrade().is_some(),
            "a public sibling still owns the context"
        );
        drop(sibling);
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
        while weak.upgrade().is_some() {
            assert!(
                std::time::Instant::now() < deadline,
                "page actors or direct services retained the context after its final public owner"
            );
            tokio::time::sleep(std::time::Duration::from_millis(5)).await;
        }
    }

