    #[cfg(feature = "v8-host")]
    #[tokio::test(flavor = "current_thread")]
    async fn failed_action_batch_retains_completed_receipts_and_stops_suffix() {
        let page = super::Browser::new().new_context().new_page();
        page.load_html("https://batch.test/", "<button id=save>Save</button>")
            .await
            .unwrap();
        page.evaluate(
            "globalThis.clicks=0;document.querySelector('#save').onclick=()=>clicks++;true",
        )
        .await
        .unwrap();
        let target = page
            .resolve_selector("#save", SemanticAction::Click)
            .await
            .unwrap();
        let mut stale = target;
        stale.document_generation += 1;
        let click = |target| NativeAction {
            target,
            action: SemanticAction::Click,
            value: None,
        };
        let error = page
            .execute_batch(vec![click(target), click(stale), click(target)])
            .await
            .unwrap_err();
        let RuntimeError::BatchExecutionFailed {
            completed,
            failed_index,
            cause,
        } = &error
        else {
            panic!("unexpected error: {error:?}")
        };
        assert_eq!(*failed_index, 1);
        assert_eq!(completed.len(), 1);
        assert!(matches!(
            cause.as_ref(),
            RuntimeError::WrongDocumentGeneration { .. }
        ));
        assert_eq!(completed[0].page_id, page.page_id());
        assert_eq!(
            serde_json::from_str::<RuntimeError>(&serde_json::to_string(&error).unwrap()).unwrap(),
            error
        );
        assert_eq!(page.evaluate("String(clicks)").await.unwrap(), "1");
        let next = page.execute_batch(vec![click(target)]).await.unwrap();
        assert!(next[0].action_id.0 > completed[0].action_id.0);
        assert_eq!(page.evaluate("String(clicks)").await.unwrap(), "2");
        page.close().await.unwrap();
    }

