    #[test]
    fn script_close_requires_web_creation_or_native_single_entry_proof() {
        let context = super::Browser::new().new_context();
        let page = context.new_page();
        let id = page.page_id();
        assert!(!context.script_close_eligible(id, None));
        assert!(!context.script_close_eligible(id, Some(false)));
        assert!(context.script_close_eligible(id, Some(true)));
        {
            let mut pages = context.inner.group.pages.lock().unwrap();
            pages.get_mut(&id).unwrap().created_by_web_content = true;
        }
        assert!(context.script_close_eligible(id, None));
        assert!(context.script_close_eligible(id, Some(false)));
        // Later opener severance does not rewrite creation provenance.
        context
            .inner
            .group
            .pages
            .lock()
            .unwrap()
            .get_mut(&id)
            .unwrap()
            .descriptor
            .page
            .opener_page_id = None;
        assert!(context.script_close_eligible(id, Some(false)));
    }

    #[test]
    fn related_page_authority_requires_both_endpoints_to_remain_live() {
        let context = super::Browser::new().new_context();
        let parent = context.new_page();
        let child = context.new_popup(parent.page_id(), None);
        let unrelated = context.new_page();
        let parent_id = parent.page_id();
        let child_id = child.page_id();
        let absent = PageId(u64::MAX);
        assert!(context.may_read_related_page_origin(child_id, parent_id));
        assert!(!context.may_read_related_page_origin(unrelated.page_id(), child_id));
        assert!(!context.may_read_related_page_origin(absent, absent));
        for status in [PageStatus::Closed, PageStatus::Crashed] {
            context
                .inner
                .group
                .pages
                .lock()
                .unwrap()
                .get_mut(&parent_id)
                .unwrap()
                .descriptor
                .status = status;
            assert!(!context.may_read_related_page_origin(parent_id, child_id));
            assert!(!context.may_read_related_page_origin(child_id, parent_id));
            context
                .inner
                .group
                .pages
                .lock()
                .unwrap()
                .get_mut(&parent_id)
                .unwrap()
                .descriptor
                .status = PageStatus::Open;
        }
        context
            .inner
            .group
            .pages
            .lock()
            .unwrap()
            .get_mut(&child_id)
            .unwrap()
            .descriptor
            .status = PageStatus::Closed;
        assert!(!context.may_read_related_page_origin(parent_id, child_id));
    }

    #[tokio::test]
    async fn script_close_revokes_liveness_then_physically_destroys_actor_with_retained_custody() {
        let context = Browser::in_process_probe().new_context();
        let page = context.new_page();
        let sibling = context.new_page();
        let id = page.page_id();
        let sender = page.sender.as_ref().unwrap().clone();
        let lock = context
            .inner
            .group
            .pages
            .lock()
            .unwrap()
            .get(&id)
            .unwrap()
            .physical_close
            .clone();
        let blocked = lock.lock().await;
        context.queue_script_close(id).unwrap();
        let job = {
            let pages = context.inner.group.pages.lock().unwrap();
            let record = pages.get(&id).unwrap();
            assert_eq!(record.descriptor.status, PageStatus::Closed);
            assert!(!record.physical_close_complete);
            record.script_close.clone().unwrap()
        };
        let pending = job.clone();
        assert!(
            tokio::task::spawn_blocking(move || pending.drain(Duration::ZERO))
                .await
                .unwrap()
                .is_err()
        );
        assert!(!sender.is_closed());
        drop(blocked);
        tokio::task::spawn_blocking(move || job.drain(Duration::from_secs(2)))
            .await
            .unwrap()
            .unwrap();
        assert!(sender.is_closed());
        assert!(
            context
                .inner
                .group
                .pages
                .lock()
                .unwrap()
                .get(&id)
                .unwrap()
                .physical_close_complete
        );
        assert!(!sibling.sender.as_ref().unwrap().is_closed());
        context.close_page(id).await.unwrap();
        sibling.close().await.unwrap();
    }

    #[tokio::test]
    async fn script_close_failure_retains_job_until_explicit_physical_cleanup_and_retry() {
        let context = Browser::in_process_probe().new_context();
        let page = context.new_page();
        let mut missing = page.detached_clone();
        missing.sender = None;
        let job = crate::script_close_custody::Job::new(missing);
        let failed = job.clone();
        assert!(
            tokio::task::spawn_blocking(move || failed.drain(Duration::from_secs(2)))
                .await
                .unwrap()
                .is_err()
        );
        assert!(
            !context
                .inner
                .group
                .pages
                .lock()
                .unwrap()
                .get(&page.page_id())
                .unwrap()
                .physical_close_complete
        );
        page.close_ordered().await.unwrap();
        tokio::task::spawn_blocking(move || job.drain(Duration::from_secs(2)))
            .await
            .unwrap()
            .unwrap();
    }

    #[tokio::test]
    async fn post_registration_admission_failure_revokes_page_and_retains_ordered_cleanup() {
        let context = Browser::in_process_probe().new_context();
        let sibling = context.new_page();
        let page = context.new_page();
        let id = page.page_id();
        let error = context.reject_registered_page_admission(
            id,
            RuntimeError::ProtocolViolation("injected cleanup capability admission failure".into()),
        );
        assert!(
            error
                .to_string()
                .contains("injected cleanup capability admission failure")
        );
        let job = {
            let pages = context.inner.group.pages.lock().unwrap();
            let record = pages.get(&id).unwrap();
            assert!(!record.is_live());
            assert!(pages.get(&sibling.page_id()).unwrap().is_live());
            record
                .script_close
                .clone()
                .expect("registered ownership retained for cleanup")
        };
        tokio::task::spawn_blocking(move || job.drain(Duration::from_secs(5)))
            .await
            .unwrap()
            .unwrap();
        assert!(
            context
                .inner
                .group
                .pages
                .lock()
                .unwrap()
                .get(&id)
                .unwrap()
                .physical_close_complete
        );
        assert!(
            context
                .inner
                .group
                .pages
                .lock()
                .unwrap()
                .get(&sibling.page_id())
                .unwrap()
                .is_live()
        );
        sibling.close().await.unwrap();
    }

    #[test]
    fn page_retirement_emits_one_terminal_transition_and_does_not_revive() {
        let context = super::Browser::new().new_context();
        let sibling = context.new_page();
        let page = context.new_page();
        let id = page.page_id();
        context.inner.group.events.lock().unwrap().clear();
        assert!(context.inner.group.close(id));
        assert!(!context.inner.group.close(id));
        assert!(!context.inner.group.close(PageId(u64::MAX)));
        context.inner.group.crash(id, "late worker error".into());
        #[cfg(unix)]
        context.inner.group.worker_started(id, 99);
        let pages = context.pages();
        let closed = pages.iter().find(|page| page.page.page_id == id).unwrap();
        assert_eq!(closed.status, PageStatus::Closed);
        assert!(!closed.active);
        assert!(
            pages
                .iter()
                .find(|page| page.page.page_id == sibling.page_id())
                .unwrap()
                .active
        );
        let events = context.inner.group.events.lock().unwrap();
        assert_eq!(events.len(), 1);
        assert!(matches!(&events[0], PageLifecycleEvent::Closed { page_id } if *page_id == id));
    }

    #[test]
    fn repeated_worker_failure_preserves_generation_and_selects_live_page() {
        let context = super::Browser::new().new_context();
        let sibling = context.new_page();
        let failed = context.new_page();
        let id = failed.page_id();
        let before = context
            .pages()
            .into_iter()
            .find(|page| page.page.page_id == id)
            .unwrap()
            .page
            .document_generation;
        context.inner.group.events.lock().unwrap().clear();
        context.inner.group.crash(id, "first failure".into());
        context.inner.group.crash(id, "duplicate completion".into());
        let pages = context.pages();
        let failed = pages.iter().find(|page| page.page.page_id == id).unwrap();
        assert_eq!(failed.status, PageStatus::Crashed);
        assert_eq!(failed.page.document_generation, before + 1);
        assert_eq!(
            *context.inner.group.active.lock().unwrap(),
            Some(sibling.page_id())
        );
        assert_eq!(context.inner.group.events.lock().unwrap().len(), 1);
    }

    #[tokio::test(flavor = "current_thread")]
    async fn renderer_updates_preserve_parent_relationships_and_ignore_retired_pages() {
        let context = super::Browser::new().new_context();
        let opener = context.new_page();
        let page = context.new_popup(opener.page_id(), None);
        page.load_html("https://example.test/live", "<p>live</p>")
            .await
            .unwrap();
        let mut observation = page.observe().await.unwrap();
        observation.page.opener_page_id = Some(PageId(u64::MAX));
        context.inner.group.update_observation(&observation);
        context
            .inner
            .group
            .update_loaded(observation.page.clone(), observation.revision);
        let descriptor = context
            .pages()
            .into_iter()
            .find(|item| item.page.page_id == page.page_id())
            .unwrap();
        assert_eq!(descriptor.page.opener_page_id, Some(opener.page_id()));
        let navigation = NavigationResult {
            page_id: page.page_id(),
            requested_url: "https://example.test/late".into(),
            final_url: "https://example.test/late".into(),
            title: "late".into(),
            status: 200,
            document_generation: observation.page.document_generation + 1,
            revision: Revision(observation.revision.0 + 1),
            lifecycle: Vec::new(),
            challenge: ChallengeAssessment::default(),
        };
        page.close().await.unwrap();
        let event_count = context.inner.group.events.lock().unwrap().len();
        observation.page.url = navigation.final_url.clone();
        context.inner.group.update_observation(&observation);
        context
            .inner
            .group
            .update_loaded(observation.page, navigation.revision);
        context.inner.group.update_navigation(&navigation);
        context
            .inner
            .group
            .update_revision(page.page_id(), navigation.revision);
        let retired = context
            .pages()
            .into_iter()
            .find(|item| item.page.page_id == page.page_id())
            .unwrap();
        assert_eq!(retired.status, PageStatus::Closed);
        assert_eq!(retired.page, descriptor.page);
        assert_eq!(retired.revision, descriptor.revision);
        assert_eq!(
            context.inner.group.events.lock().unwrap().len(),
            event_count
        );
    }

    #[cfg(unix)]
    #[test]
    fn closed_worker_page_rejects_retained_handle_without_spawning() {
        let mut browser = Browser::new();
        browser.worker_process = true;
        let context = browser.new_context();
        let page = context.new_page();
        let sibling = context.new_page();
        let worker = page.worker.as_ref().unwrap();
        assert!(!worker.execution_retired());
        assert!(matches!(worker.close(), Ok(WorkerCloseOutcome::Closed)));
        assert!(worker.execution_retired());
        assert!(matches!(worker.enter_queue(), Err(RuntimeError::Closed)));
        assert!(matches!(
            worker.request(crate::worker::WorkerRequest::Ping),
            Err(RuntimeError::Closed)
        ));
        assert_eq!(worker.pending.load(Ordering::Acquire), 0);
        assert_eq!(worker.process_id.load(Ordering::Acquire), 0);
        assert!(worker.client.lock().unwrap().is_none());
        assert!(!sibling.worker.as_ref().unwrap().execution_retired());
        assert!(matches!(worker.close(), Ok(WorkerCloseOutcome::Closed)));
    }

    #[cfg(unix)]
    #[test]
    fn worker_retirement_rejects_already_queued_work_after_client_lock() {
        let mut browser = Browser::new();
        browser.worker_process = true;
        let context = browser.new_context();
        let page = context.new_page();
        let worker = page.worker.as_ref().unwrap().clone();
        let held_client = worker.client.lock().unwrap();
        let queued = worker.clone();
        let thread = std::thread::spawn(move || queued.request(crate::worker::WorkerRequest::Ping));
        let deadline = Instant::now() + Duration::from_secs(5);
        while worker.pending.load(Ordering::Acquire) == 0 && Instant::now() < deadline {
            std::thread::yield_now();
        }
        let admitted = worker.pending.load(Ordering::Acquire) == 1;
        worker.retired.store(true, Ordering::Release);
        drop(held_client);
        assert!(matches!(thread.join().unwrap(), Err(RuntimeError::Closed)));
        assert!(
            admitted,
            "request must have entered the queue before retirement"
        );
        assert_eq!(worker.pending.load(Ordering::Acquire), 0);
        assert!(worker.client.lock().unwrap().is_none());
    }

    #[cfg(unix)]
    #[test]
    fn worker_generation_allocation_exhausts_without_reusing_a_prefix() {
        let counter = Arc::new(AtomicU64::new(u64::from(u32::MAX)));
        let workers: Vec<_> = (0..4)
            .map(|_| {
                let counter = counter.clone();
                std::thread::spawn(move || allocate_worker_generation(&counter))
            })
            .collect();
        let results: Vec<_> = workers
            .into_iter()
            .map(|worker| worker.join().unwrap())
            .collect();
        let issued: Vec<_> = results
            .iter()
            .filter_map(|result| result.as_ref().ok().copied())
            .collect();
        assert_eq!(issued, vec![u64::from(u32::MAX) << 32]);
        assert_eq!(results.iter().filter(|result| result.is_err()).count(), 3);
        assert_eq!(counter.load(Ordering::Acquire), 1_u64 << 32);
        assert!(allocate_worker_generation(&counter).is_err());
        assert!(allocate_worker_generation(&AtomicU64::new(0)).is_err());
        assert!(allocate_worker_generation(&AtomicU64::new(u64::MAX)).is_err());
    }

    #[test]
    fn document_generation_cannot_cross_its_incarnation_boundary() {
        let base = 7_u64 << 32;
        assert_eq!(advance_document_generation(base, base).unwrap(), base + 1);
        assert_eq!(
            advance_document_generation(base + 41, base).unwrap(),
            base + 42
        );
        assert!(advance_document_generation(base | u64::from(u32::MAX), base).is_err());
        assert!(advance_document_generation(u64::MAX, u64::from(u32::MAX) << 32).is_err());
        assert!(advance_document_generation(3, base).is_err());
    }

