    #[tokio::test(flavor = "current_thread")]
    async fn page_close_retries_last_shared_agent_and_allows_broker_reentry() {
        use crate::agent_registry::{AgentOwner, AgentProcess};
        use oryn_js::worker_wire::*;
        struct ClosingAgent {
            context: std::sync::Weak<super::BrowserContextInner>,
            stops: Arc<std::sync::atomic::AtomicUsize>,
            reject: Arc<std::sync::atomic::AtomicBool>,
            successes: Arc<std::sync::atomic::AtomicUsize>,
            drops: Arc<std::sync::atomic::AtomicUsize>,
            suspended: bool,
            suspension_requested: Arc<std::sync::atomic::AtomicBool>,
        }
        impl Drop for ClosingAgent {
            fn drop(&mut self) {
                self.drops.fetch_add(1, Ordering::SeqCst);
            }
        }
        impl AgentProcess for ClosingAgent {
            fn send(&mut self, _: AgentCommand) -> Result<(), WorkerError> {
                Ok(())
            }
            fn poll(&mut self, _: usize) -> Result<Vec<AgentEvent>, WorkerError> {
                Ok(Vec::new())
            }
            fn set_suspended(&mut self, suspended: bool) -> Result<(), WorkerError> {
                self.suspended = suspended;
                if suspended {
                    self.suspension_requested.store(true, Ordering::SeqCst);
                }
                Ok(())
            }
            fn suspension_status(&mut self) -> Result<bool, WorkerError> {
                Ok(self.suspended)
            }
            fn terminate(&mut self) -> Result<(), WorkerError> {
                let context = self.context.upgrade().expect("context owns teardown");
                // A terminating agent can finish an outstanding broker request.
                // Close must release every authority lock before waiting on it.
                let _agents = context
                    .agents
                    .try_lock()
                    .expect("agent lock held during join");
                let _pages = context
                    .group
                    .pages
                    .try_lock()
                    .expect("page lock held during join");
                let _messages = context
                    .group
                    .messages
                    .try_lock()
                    .expect("message lock held during join");
                self.stops.fetch_add(1, Ordering::SeqCst);
                if self.reject.load(Ordering::SeqCst) {
                    return Err(WorkerError::new(
                        "InvalidStateError",
                        "injected teardown failure",
                    ));
                }
                self.successes.fetch_add(1, Ordering::SeqCst);
                Ok(())
            }
        }
        let context = Browser::native_test_with_config(BrowserConfig::default()).new_context();
        let first = context.new_page();
        let sibling = context.new_page();
        // Attach to loaded Documents so the later navigation parks a real
        // incumbent instead of retiring the initial blank Document first.
        first
            .load_html("https://example.test/first", "<p>first owner</p>")
            .await
            .unwrap();
        sibling
            .load_html("https://example.test/sibling", "<p>sibling owner</p>")
            .await
            .unwrap();
        let stops = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let suspension_requested = Arc::new(std::sync::atomic::AtomicBool::new(false));
        // Keep the failure active across internal retirement attempts until
        // the test repairs the mock transport and permits the retained retry.
        let reject = Arc::new(std::sync::atomic::AtomicBool::new(true));
        let successes = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let drops = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let bootstrap = AgentBootstrap {
            cookie_ancestor_urls: Vec::new(),
            import_metadata: Default::default(),
            service_skip_waiting: false,
            resource_digests: Default::default(),
            secure_context: true,
            service_registration: None,
            service_controller: None,
            policy: oryn_js::worker_wire::AgentPolicy::default(),
            top_level_url: None,
            id: AgentId(0),
            kind: AgentKind::Shared,
            partition: "close-regression".into(),
            origin: AgentOrigin {
                serialized: "https://example.test".into(),
                authority: "close-origin".into(),
                opaque: false,
            },
            script_url: "https://example.test/shared.js".into(),
            source: Vec::new(),
            modules: Default::default(),
            options: WorkerOptions {
                name: "shared".encode_utf16().collect(),
                ..Default::default()
            },
            referrer_policy: "strict-origin-when-cross-origin".into(),
            limits: AgentLimits::default(),
        };
        let owner = |page| {
            let Creator::Window {
                target,
                document_generation,
                stream_epoch,
            } = context.root_navigation_creator(page).unwrap()
            else {
                panic!("native Window creator")
            };
            AgentOwner::Window {
                page,
                target,
                generation: document_generation,
                epoch: stream_epoch,
            }
        };
        let (first_connection, sibling_connection) = {
            let mut agents = context.inner.agents.lock().unwrap();
            let first_connection = agents
                .connect(owner(first.page_id()), bootstrap.clone(), |_| {
                    Ok(Box::new(ClosingAgent {
                        context: Arc::downgrade(&context.inner),
                        stops: stops.clone(),
                        reject: reject.clone(),
                        successes: successes.clone(),
                        drops: drops.clone(),
                        suspended: false,
                        suspension_requested: suspension_requested.clone(),
                    }))
                })
                .unwrap();
            let sibling_connection = agents
                .connect(owner(sibling.page_id()), bootstrap, |_| {
                    panic!("shared connection must reuse the same agent")
                })
                .unwrap();
            (first_connection, sibling_connection)
        };
        assert_eq!(first_connection.agent, sibling_connection.agent);
        first.close().await.unwrap();
        assert_eq!(stops.load(Ordering::SeqCst), 0);
        {
            let agents = context.inner.agents.lock().unwrap();
            assert!(agents.connection_owner(&first_connection).is_err());
            assert_eq!(
                agents.connection_owner(&sibling_connection).unwrap(),
                owner(sibling.page_id())
            );
        }
        sibling
            .load_html("https://example.test/", "<p>still live</p>")
            .await
            .unwrap();
        assert!(
            suspension_requested.load(Ordering::SeqCst),
            "navigation must exercise the mock's acknowledged suspension contract"
        );
        let stops_before_close = stops.load(Ordering::SeqCst);
        assert_eq!(
            stops_before_close, 0,
            "cached navigation must preserve the worker until close"
        );
        let mut closing = Box::pin(sibling.close());
        tokio::time::timeout(Duration::from_secs(5), async {
            while stops.load(Ordering::SeqCst) < 2 {
                tokio::select! {
                    result = &mut closing => panic!("close acknowledged while termination still fails: {result:?}"),
                    _ = tokio::time::sleep(Duration::from_millis(1)) => {}
                }
            }
        }).await.expect("failed termination must be retried without holding authority locks");
        assert!(
            tokio::time::timeout(Duration::from_millis(25), &mut closing)
                .await
                .is_err(),
            "unrepaired teardown must retain the close acknowledgement"
        );
        assert_eq!(successes.load(Ordering::SeqCst), 0);
        assert_eq!(
            drops.load(Ordering::SeqCst),
            0,
            "failed termination must retain the process for retry"
        );
        reject.store(false, Ordering::SeqCst);
        tokio::time::timeout(Duration::from_secs(5), &mut closing)
            .await
            .expect("repaired teardown must complete")
            .unwrap();
        assert_eq!(
            successes.load(Ordering::SeqCst),
            1,
            "exactly one successful termination"
        );
        assert!(
            context.inner.group.handle(sibling.page_id()).is_none(),
            "closed page cannot be used for new commands"
        );
        assert_eq!(
            drops.load(Ordering::SeqCst),
            1,
            "successful retirement releases exactly one process"
        );
        let completed_attempts = stops.load(Ordering::SeqCst);
        context.close_page(sibling.page_id()).await.unwrap();
        sibling.close().await.unwrap();
        assert_eq!(
            stops.load(Ordering::SeqCst),
            completed_attempts,
            "completed teardown must not terminate twice"
        );
        assert!(
            context
                .inner
                .agents
                .lock()
                .unwrap()
                .principal(first_connection.agent)
                .is_err()
        );
    }

    #[cfg(unix)]
    #[tokio::test(flavor = "current_thread")]
    async fn qualification_worker_fault_rejects_foreign_and_unstarted_targets() {
        let mut browser = Browser::new();
        browser.worker_process = true;
        let context = browser.new_context();
        let foreign_context = browser.new_context();
        let page = context.new_page();
        let foreign = foreign_context.new_page();
        assert!(
            matches!(context.terminate_qualification_worker(foreign.page_id()).await,
            Err(RuntimeError::PageNotFound(id)) if id == foreign.page_id())
        );
        assert!(
            matches!(context.terminate_qualification_worker(page.page_id()).await,
            Err(RuntimeError::ProtocolViolation(detail)) if detail.contains("no running worker"))
        );
        assert!(
            matches!(context.cancel_qualification_operation(foreign.page_id()).await,
            Err(RuntimeError::PageNotFound(id)) if id==foreign.page_id())
        );
        assert!(
            matches!(context.cancel_qualification_operation(page.page_id()).await,
            Err(RuntimeError::ProtocolViolation(detail)) if detail.contains("no running worker"))
        );
        // Fault setup must not cause a worker launch or revoke an unused page.
        assert_eq!(
            page.worker
                .as_ref()
                .unwrap()
                .process_id
                .load(Ordering::Acquire),
            0
        );
        assert!(context.inner.group.handle(page.page_id()).is_some());
        assert!(!context.inner.workers_retired.load(Ordering::Acquire));
        assert!(
            page.navigation_control()
                .unwrap()
                .begin(crate::navigation_control::NavigationRequest {
                    command: crate::navigation_control::NavigationCommand::Refresh,
                    strategy: crate::navigation_control::PageLoadStrategy::Normal,
                    timeout_ms: None,
                })
                .is_ok()
        );
        assert!(
            foreign_context
                .inner
                .group
                .handle(foreign.page_id())
                .is_some()
        );
        page.close().await.unwrap();
        foreign.close().await.unwrap();
    }

    #[cfg(unix)]
    #[tokio::test(flavor = "current_thread")]
    async fn script_close_does_not_interrupt_but_host_close_can_cancel_inflight_worker() {
        struct ChildGuard(std::process::Child);
        impl Drop for ChildGuard {
            fn drop(&mut self) {
                let _ = self.0.kill();
                let _ = self.0.wait();
            }
        }
        // Model an in-flight command without needing a signed executable. The
        // client is intentionally empty; this test isolates cancellation policy.
        let mut process = ChildGuard(
            std::process::Command::new("/bin/sleep")
                .arg("30")
                .spawn()
                .expect("start cancellation sentinel"),
        );
        let mut browser = Browser::new();
        browser.worker_process = true;
        let context = browser.new_context();
        let page = context.new_page();
        let worker = page.worker.as_ref().unwrap();
        worker.pending.store(1, Ordering::Release);
        worker.process_id.store(process.0.id(), Ordering::Release);
        context
            .close_page_from_script(page.page_id())
            .await
            .unwrap();
        assert!(process.0.try_wait().unwrap().is_none());
        page.close().await.unwrap();
        use std::os::unix::process::ExitStatusExt;
        assert_eq!(process.0.wait().unwrap().signal(), Some(libc::SIGKILL));
        worker.process_id.store(0, Ordering::Release);
        worker.pending.store(0, Ordering::Release);
    }

