    #[test]
    fn worker_partition_separates_context_scheme_and_opaque_identity() {
        let a = SecurityOrigin::from_url("https://a.example.com/");
        let b = SecurityOrigin::from_url("https://b.example.com/");
        assert_eq!(
            native_storage_partition(1, &a),
            native_storage_partition(1, &b)
        );
        assert_ne!(
            native_storage_partition(1, &a),
            native_storage_partition(2, &a)
        );
        assert_ne!(
            native_storage_partition(1, &a),
            native_storage_partition(1, &SecurityOrigin::from_url("http://a.example.com/"))
        );
        let first = SecurityOrigin::opaque();
        let second = SecurityOrigin::opaque();
        assert_eq!(first.serialize(), second.serialize());
        assert_ne!(
            native_storage_partition(1, &first),
            native_storage_partition(1, &second)
        );
        assert_eq!(
            native_storage_partition(1, &first),
            native_storage_partition(1, &first.clone())
        );
    }

