    fn meta_referrer_policy_is_order_and_quote_independent() {
        assert_eq!(
            super::meta_referrer_policy(
                "<head><meta content='no-referrer' data-x=1 NAME=referrer></head>"
            )
            .as_deref(),
            Some("no-referrer")
        );
        assert_eq!(
            super::meta_referrer_policy("<meta name=viewport content=x>"),
            None
        );
        assert_eq!(
            super::meta_referrer_policy(
                r#"
            <!-- <meta name=referrer content=unsafe-url> -->
            <meta name=referrer content=origin>
            <script>const example='<meta name=referrer content=unsafe-url>';</script>
            <meta name=referrer content='no-referrer'>
            <template><meta name=referrer content=unsafe-url></template>
            <meta name=referrer content='unknown'>
        "#
            )
            .as_deref(),
            Some("no-referrer")
        );
        assert_eq!(
            super::meta_referrer_policy("<meta name=referrer content='origin, no-referrer'>"),
            None
        );
    }

