    #[tokio::test(flavor = "current_thread")]
    async fn page_handle_queues_typed_operations() {
        let browser = Browser::new();
        let context = browser.new_context();
        let page = context.new_page();
        let observation = page.observe().await.expect("observe blank page");

        assert_eq!(observation.execution_domain, ExecutionDomain::Native);
        assert_eq!(observation.source, ObservationSource::NativeDom);
        page.close().await.expect("close page");
    }

    #[tokio::test(flavor = "current_thread")]
    async fn loaded_html_produces_native_semantics() {
        let context = Browser::new().new_context();
        let page = context.new_page();
        let initial = page.observe().await.unwrap().page.document_generation;
        let revision = page
            .load_html(
                "https://example.test/form",
                "<title>Form</title><label>Email <input type=email required></label><button>Send</button>",
            )
            .await
            .expect("load HTML");
        let observation = page.observe().await.expect("observe document");

        // Commit and retained semantic publication are distinct revisions.
        assert!(revision.0 > 0);
        assert!(observation.revision.0 >= revision.0);
        assert_eq!(observation.page.title, "Form");
        assert!(observation.page.document_generation > initial);
        #[cfg(all(unix, feature = "v8-host"))]
        assert_eq!(
            observation.page.document_generation,
            context
                .inner
                .group
                .messages
                .lock()
                .unwrap()
                .root_document_identity(page.page_id().0)
                .unwrap()
                .0
        );
        assert!(observation.nodes.iter().any(|node| node.name == "Send"));
        page.load_html(
            "https://example.test/replacement",
            "<title>Replacement</title><button>Next</button>",
        )
        .await
        .unwrap();
        let replacement = page.observe().await.unwrap();
        assert!(replacement.page.document_generation > observation.page.document_generation);
        #[cfg(all(unix, feature = "v8-host"))]
        assert_eq!(
            replacement.page.document_generation,
            context
                .inner
                .group
                .messages
                .lock()
                .unwrap()
                .root_document_identity(page.page_id().0)
                .unwrap()
                .0
        );
        assert_eq!(replacement.page.title, "Replacement");
        assert!(replacement.nodes.iter().any(|node| node.name == "Next"));
        assert!(!replacement.nodes.iter().any(|node| node.name == "Send"));
        page.close().await.unwrap();
    }

    #[cfg(feature = "v8-host")]
    fn unfinished_history_resources(page: &mut PageState, url: &str) -> BTreeMap<String, String> {
        let generation = advance_document_generation(
            page.last_issued_document_generation,
            page.config.document_generation_base,
        )
        .unwrap();
        let (history, index) = page
            .prepare_navigation_history(url, HistoryUpdate::Push, generation)
            .unwrap();
        let visible = PageState::visible_navigation_history(&history, index, "push").unwrap();
        let session = PageState::full_session_history(&history, index, "push").unwrap();
        assert_eq!(session.entries.len(), history.len());
        assert_eq!(session.current, index);
        let resources = BTreeMap::from([
            (
                "oryn:navigation-history".into(),
                serde_json::to_string(&visible).unwrap(),
            ),
            (
                "oryn:session-history".into(),
                serde_json::to_string(&session).unwrap(),
            ),
        ]);
        page.history = history;
        page.history_index = Some(index);
        page.url = url.into();
        page.document_generation = generation;
        page.last_issued_document_generation = generation;
        resources
    }

    #[cfg(feature = "v8-host")]
    async fn settle_fixture_output(page: &PageHandle) -> String {
        let deadline = tokio::time::Instant::now() + BrowserConfig::default().navigation_timeout;
        loop {
            // Each command yields to the actual page actor. Do not make the
            // production drain block on parent IO or future timer deadlines.
            let value = page.evaluate("__oryn_drain(true);document.querySelector('#result').textContent")
                .await.expect("read asynchronous fixture output");
            if value != "pending" { return value; }
            assert!(tokio::time::Instant::now() < deadline, "fixture output did not settle");
            tokio::task::yield_now().await;
        }
    }

    #[cfg(feature = "v8-host")]
    fn settle_fixture_document(page: &mut PageState) {
        let deadline = Instant::now() + page.config.navigation_timeout;
        loop {
            match page.poll_page_tasks() {
                Ok(()) => {},
                Err(RuntimeError::PageTaskYield) if !page.terminal_close_requested() => {},
                Err(error) => panic!("fixture page task failed: {error}"),
            }
            if page.executable.as_ref().is_some_and(|executable| executable.document_load_complete())
                && page.lifecycle.contains(&LifecycleState::Load) { return; }
            assert!(Instant::now() < deadline, "fixture document did not settle");
            std::thread::yield_now();
        }
    }

    #[cfg(feature = "v8-host")]
    fn finish_fixture_rollback_publication(page: &mut PageState) {
        let deadline = Instant::now() + Duration::from_secs(3);
        while !page.history_publications.is_empty() {
            page.poll_history_publications().unwrap();
            assert!(
                Instant::now() < deadline,
                "retained rollback pageshow did not complete"
            );
            if !page.history_publications.is_empty() {
                std::thread::park_timeout(Duration::from_millis(1));
            }
        }
    }

    #[cfg(feature = "v8-host")]
    #[test]
    fn replacing_unfinished_document_releases_input_and_forces_history_reload() {
        struct Input {
            polls: std::rc::Rc<std::cell::Cell<usize>>,
            dropped: std::rc::Rc<std::cell::Cell<bool>>,
        }
        impl crate::host::DocumentInput for Input {
            fn poll_next(
                &mut self,
            ) -> std::task::Poll<Option<Result<String, crate::host::HostError>>> {
                self.polls.set(self.polls.get() + 1);
                std::task::Poll::Pending
            }
        }
        impl Drop for Input {
            fn drop(&mut self) {
                self.dropped.set(true);
            }
        }
        let polls = std::rc::Rc::new(std::cell::Cell::new(0));
        let dropped = std::rc::Rc::new(std::cell::Cell::new(false));
        let mut page = PageState::new(
            PageId(195),
            None,
            BrowserConfig::default(),
            ContextOptions::default(),
            None,
            #[cfg(unix)]
            None,
        );
        page.bind_direct_fixture_terminal_owner();
        let resources = unfinished_history_resources(&mut page, "https://example.test/unfinished");
        let stream = crate::host::DocumentStream {
            content_language: None,
            chunks: Box::new(Input {
                polls: polls.clone(),
                dropped: dropped.clone(),
            }),
            content_type: None,
            encoding: Default::default(),
        };
        let executable = crate::executable::RustExecutableDocument::load_stream_with_limits(
            stream,
            &resources,
            None,
            Some(Url::parse(&page.url).unwrap()),
            256 * 1024 * 1024,
            true,
        )
        .unwrap();
        page.document = Some(executable.document.clone());
        page.executable = Some(executable);
        page.suspend_current_document().unwrap();
        assert!(dropped.get());
        assert_eq!(polls.get(), 0);
        assert!(page.executable.is_none());
        assert!(page.document.is_none());
        assert!(!page.back_forward_cache.contains_key(&0));
        assert_eq!(page.history.len(), 1);
        assert!(
            page.restore_cached_document(0, page.url.clone())
                .unwrap()
                .is_none()
        );
    }

    #[cfg(feature = "v8-host")]
    #[test]
    fn deferred_response_waits_for_parser_and_rejects_replaced_document_identity() {
        for change_stream in [false, true] {
            let mut page = PageState::new(
                PageId(194),
                None,
                BrowserConfig::default(),
                ContextOptions::default(),
                None,
                #[cfg(unix)]
                None,
            );
            let source = "<title>Deferred</title><p>Body</p>";
            page.executable = Some(
                crate::executable::RustExecutableDocument::load_stream_with_limits(
                    crate::host::DocumentStream::html(Box::new(std::iter::once(Ok(source.into())))),
                    &BTreeMap::new(),
                    None,
                    Some(Url::parse("https://example.test/deferred").unwrap()),
                    256 * 1024 * 1024,
                    true,
                )
                .unwrap(),
            );
            let capture = Arc::new(Mutex::new(NavigationBodyCapture {
                source: source.into(),
                bytes: source.len(),
                completed: true,
            }));
            let identity = page
                .executable
                .as_ref()
                .unwrap()
                .form_history_root_identity()
                .map(|(realm, generation, epoch)| (u64::from(realm.0), generation, epoch));
            page.pending_navigation_response = Some(PendingNavigationResponse {
                generation: page.document_generation,
                root_identity: identity,
                current: Url::parse("https://example.test/deferred").unwrap(),
                status: 200,
                response_headers: Vec::new(),
                essence: "text/html".into(),
                capture: capture.clone(),
            });
            page.finish_pending_navigation_response().unwrap();
            assert!(page.pending_navigation_response.is_some());
            assert!(!capture.lock().unwrap().source.is_empty());
            if change_stream {
                page.executable
                    .as_mut()
                    .unwrap()
                    .execute("document.open()")
                    .unwrap();
            } else {
                page.document_generation += 1;
            }
            page.finish_pending_navigation_response().unwrap();
            assert!(page.pending_navigation_response.is_none());
            assert_eq!(Arc::strong_count(&capture), 1);
            assert_eq!(capture.lock().unwrap().source, source);
            assert!(!page.lifecycle.contains(&LifecycleState::Load));
        }
    }

    #[cfg(feature = "v8-host")]
    #[test]
    fn navigation_enforces_csp_before_inline_script_execution() {
        struct CspFixture;
        impl NetworkBroker for CspFixture {
            fn send(
                &self,
                request: NetworkRequest,
            ) -> Result<NetworkResponse, crate::network::NetworkError> {
                Ok(NetworkResponse {response_policy: None,timing:None,
                    request_id: request.request_id,
                    status: 200,
                    headers: vec![
                        ("content-type".into(), "text/html".into()),
                        ("content-security-policy".into(), "script-src 'none'".into()),
                    ],
                    body: b"<main id='state'>blocked</main><script>document.getElementById('state').textContent='ran'</script>".to_vec(),
                })
            }
        }
        let mut page = PageState::new(
            PageId(91),
            None,
            BrowserConfig::default(),
            ContextOptions::default(),
            Some(SharedNetworkBroker::new(CspFixture)),
            #[cfg(all(unix, feature = "v8-host"))]
            None,
        );
        page.bind_direct_fixture_terminal_owner();
        page.navigate("https://app.example/".into(), HistoryUpdate::Push)
            .expect("CSP-protected navigation");
        let state = page
            .document
            .as_ref()
            .unwrap()
            .dom
            .iter()
            .find(|(_, node)| {
                node.attributes
                    .get_null("id")
                    .is_some_and(|id| id == "state")
            })
            .map(|(id, _)| id)
            .unwrap();
        assert_eq!(
            page.document
                .as_ref()
                .unwrap()
                .dom
                .text_content(state)
                .unwrap(),
            "blocked"
        );
        let deadline = Instant::now() + Duration::from_secs(3);
        while page.pending_navigation_response.is_some() {
            page.poll_page_tasks().unwrap();
            assert!(Instant::now() < deadline, "inline CSP response publication");
            std::thread::park_timeout(Duration::from_millis(1));
        }
        assert!(
            page.trace.events().iter().any(|event| matches!(
                event.kind,
                TraceEventKind::CspViolation { ref effective_directive, .. }
                    if effective_directive == "script-src-elem"
            )),
            "missing inline CSP trace: pending_response={}, parser_pending={}, lifecycle={:?}, trace={:?}",
            page.pending_navigation_response.is_some(),
            page.executable
                .as_ref()
                .is_some_and(|page| page.parser_pending()),
            page.lifecycle,
            page.trace.events()
        );
    }

    #[cfg(feature = "v8-host")]
    #[test]
    fn navigation_scope_does_not_reuse_retained_page_request_identity() {
        #[derive(Default)]
        struct State {
            ids: Vec<u64>,
            held: Option<tokio::sync::mpsc::Sender<crate::network::NetworkEvent>>,
            cancelled: Vec<u64>,
        }
        struct Transport(Arc<Mutex<State>>);
        impl NetworkBroker for Transport {
            fn send(
                &self,
                _: NetworkRequest,
            ) -> Result<NetworkResponse, crate::network::NetworkError> {
                unreachable!()
            }
            fn start_operation(
                &self,
                request: NetworkRequest,
            ) -> Result<crate::network::NetworkOperation, crate::network::NetworkError>
            {
                let (sender, events) = tokio::sync::mpsc::channel(4);
                let mut state = self.0.lock().unwrap();
                state.ids.push(request.request_id);
                if state.ids.len() == 1 {
                    state.held = Some(sender);
                } else {
                    sender
                        .try_send(crate::network::NetworkEvent::Headers {
                            response_policy: None,
                            timing: None,
                            request_id: request.request_id,
                            status: 204,
                            headers: Vec::new(),
                            content_length: Some(0),
                            upload: None,
                        })
                        .unwrap();
                }
                Ok(crate::network::NetworkOperation {
                    body_demand_pending: Default::default(),
                    prefetched: Default::default(),
                    request_id: request.request_id,
                    events,
                    demand: None,
                })
            }
            fn cancel_operation(&self, id: u64) -> Result<(), crate::network::NetworkError> {
                let mut state = self.0.lock().unwrap();
                state.cancelled.push(id);
                if state.ids.first() == Some(&id) {
                    state.held.take();
                }
                Ok(())
            }
        }
        let state = Arc::new(Mutex::new(State::default()));
        let broker = SharedNetworkBroker::new(Transport(state.clone()));
        let mut page = PageState::new(
            PageId(225),
            None,
            BrowserConfig::default(),
            ContextOptions::default(),
            Some(broker.clone()),
            #[cfg(unix)]
            None,
        );
        let retained = broker
            .start_operation(NetworkRequest {
                request_id: page.revision + 1,
                method: "GET".into(),
                url: "https://scope.test/retained".into(),
                headers: Vec::new(),
                body: Vec::new(),
                credentials: false,
                security: Default::default(),
                resolved_addrs: Vec::new(),
            })
            .unwrap();
        assert_eq!(
            page.navigate("https://scope.test/new".into(), HistoryUpdate::Push)
                .unwrap()
                .status,
            204
        );
        {
            let state = state.lock().unwrap();
            assert_eq!(state.ids.len(), 2);
            assert_ne!(state.ids[0], state.ids[1]);
            assert!(!state.cancelled.contains(&state.ids[0]));
            assert!(state.held.is_some());
        }
        drop(retained);
        broker
            .drain_owned_operations(Duration::from_secs(2))
            .unwrap();
        let state = state.lock().unwrap();
        assert!(state.cancelled.contains(&state.ids[0]));
        assert!(state.held.is_none());
    }

    #[cfg(feature = "v8-host")]
    fn repair44_navigation_state(page: &PageState) -> String {
        let executable = page.executable.as_ref();
        // Cap item count before collecting and borrow bounded string slices.
        // Full structured-clone/history/request bodies are never formatted.
        let history = page
            .history
            .iter()
            .take(8)
            .map(|entry| {
                (
                    repair44_diagnostic_prefix(&entry.url),
                    entry.navigation.as_ref().map(|entry| {
                        (
                            repair44_diagnostic_prefix(&entry.id),
                            repair44_diagnostic_prefix(&entry.document_id),
                            entry.state.is_some(),
                            entry.history_state.is_some(),
                        )
                    }),
                    entry.request_state.is_some(),
                )
            })
            .collect::<Vec<_>>();
        let origin = executable.and_then(|page| page.native_navigation_origin());
        repair44_bounded_diagnostic(format_args!(
            "url={:?} generation={} history_index={:?} history_total={} history_first8={:?} lifecycle={:?} pending_response={} pending_transaction={} identity={:?} native_origin={:?} parser_pending={:?} interactive={:?} complete={:?}",
            repair44_diagnostic_prefix(&page.url),
            page.document_generation,
            page.history_index,
            page.history.len(),
            history,
            page.lifecycle,
            page.pending_navigation_response.is_some(),
            page.pending_navigation_transaction.is_some(),
            executable.and_then(|page| page.form_history_root_identity()),
            origin.as_deref().map(repair44_diagnostic_prefix),
            executable.map(|page| page.parser_pending()),
            executable.map(|page| page.document_interactive()),
            executable.map(|page| page.document_load_complete())
        ))
    }

    #[cfg(feature = "v8-host")]
    #[test]
    fn incumbent_timer_supersedes_navigation_waiting_for_response_headers() {
        struct PendingHeaders {
            held: Arc<Mutex<Vec<tokio::sync::mpsc::Sender<crate::network::NetworkEvent>>>>,
            cancelled: Arc<AtomicUsize>,
        }
        impl NetworkBroker for PendingHeaders {
            fn send(
                &self,
                _: NetworkRequest,
            ) -> Result<NetworkResponse, crate::network::NetworkError> {
                unreachable!()
            }
            fn start_operation(
                &self,
                request: NetworkRequest,
            ) -> Result<crate::network::NetworkOperation, crate::network::NetworkError>
            {
                let (sender, events) = tokio::sync::mpsc::channel(1);
                self.held.lock().unwrap().push(sender);
                Ok(crate::network::NetworkOperation {
                    body_demand_pending: Default::default(),
                    prefetched: Default::default(),
                    request_id: request.request_id,
                    events,
                    demand: None,
                })
            }
            fn cancel_operation(&self, _: u64) -> Result<(), crate::network::NetworkError> {
                self.cancelled.fetch_add(1, Ordering::SeqCst);
                self.held.lock().unwrap().clear();
                Ok(())
            }
        }
        let cancelled = Arc::new(AtomicUsize::new(0));
        let held = Arc::new(Mutex::new(Vec::new()));
        let broker = SharedNetworkBroker::new(PendingHeaders {
            held: held.clone(),
            cancelled: cancelled.clone(),
        });
        let mut page = PageState::new(
            PageId(224),
            None,
            BrowserConfig::default(),
            ContextOptions::default(),
            Some(broker.clone()),
            #[cfg(unix)]
            None,
        );
        page.bind_direct_fixture_terminal_owner();
        page.load_document(
            "https://headers.test/source".into(),
            "<title>Source</title>",
            None,
            None,
            HistoryUpdate::Push,
            &BTreeMap::new(),
            Vec::new(),
        )
        .unwrap();
        page.executable
            .as_mut()
            .unwrap()
            .execute("location.href='/pending'")
            .unwrap();
        let request = page
            .executable
            .as_ref()
            .unwrap()
            .take_location_navigation()
            .unwrap();
        assert_eq!(
            request.url, "https://headers.test/pending",
            "capture the initial request before its timer replacement"
        );
        let NavigationProgress::Pending(id) = page
            .begin_script_navigation(request, HistoryUpdate::Push)
            .unwrap()
        else {
            panic!("initial navigation must retain its pending response");
        };
        let (reply, mut response) = oneshot::channel();
        let transaction = page.pending_navigation_transaction.as_mut().unwrap();
        assert_eq!(transaction.id, id);
        transaction.reply = Some(NavigationReply::Navigation(reply));
        let deadline = Instant::now() + Duration::from_secs(5);
        while held.lock().unwrap().is_empty() {
            page.poll_page_tasks().unwrap();
            assert!(
                Instant::now() < deadline,
                "pending request must reach the broker"
            );
            std::thread::park_timeout(Duration::from_millis(1));
        }
        assert!(matches!(
            response.try_recv(),
            Err(oneshot::error::TryRecvError::Empty)
        ));
        // Arm the timer only after the original request is admitted and its
        // headers are held. A zero-delay timer in the setup script can run in
        // its checkpoint before the fixture captures the initial request.
        page.executable
            .as_mut()
            .unwrap()
            .execute("setTimeout(()=>location.href='/replacement',0)")
            .unwrap();
        let outcome = loop {
            page.poll_page_tasks().unwrap();
            match response.try_recv() {
                Ok(result) => break result,
                Err(oneshot::error::TryRecvError::Empty) => {}
                Err(error) => panic!("navigation reply lost: {error}"),
            }
            assert!(
                Instant::now() < deadline,
                "timer replacement must settle the initial navigation"
            );
            std::thread::park_timeout(Duration::from_millis(1));
        };
        eprintln!(
            "repair44 native29/103 result={} {}",
            repair44_bounded_diagnostic(format_args!("{outcome:?}")),
            repair44_navigation_state(&page)
        );
        assert!(matches!(outcome, Err(RuntimeError::NavigationCancelled)));
        assert_eq!(page.url, "https://headers.test/source");
        assert_eq!(
            page.pending_navigation_transaction
                .as_ref()
                .unwrap()
                .requested_url,
            "https://headers.test/replacement"
        );
        page.cancel_navigation_transaction(RuntimeError::NavigationCancelled);
        broker
            .drain_owned_operations(Duration::from_secs(2))
            .unwrap();
        assert!(cancelled.load(Ordering::SeqCst) > 0);
    }

    #[cfg(feature = "v8-host")]
    #[test]
    fn redirect_headers_share_one_navigation_deadline_even_when_already_queued() {
        struct RedirectChain {
            calls: Arc<AtomicUsize>,
            cancelled: Arc<AtomicUsize>,
        }
        impl NetworkBroker for RedirectChain {
            fn send(
                &self,
                _request: NetworkRequest,
            ) -> Result<NetworkResponse, crate::network::NetworkError> {
                unreachable!("navigation must use owned operations")
            }
            fn start_operation(
                &self,
                request: NetworkRequest,
            ) -> Result<crate::network::NetworkOperation, crate::network::NetworkError>
            {
                let index = self.calls.fetch_add(1, Ordering::SeqCst);
                std::thread::sleep(Duration::from_millis(15));
                let (sender, events) = tokio::sync::mpsc::channel(4);
                sender
                    .blocking_send(crate::network::NetworkEvent::Headers {
                        response_policy: None,
                        timing: None,
                        request_id: request.request_id,
                        status: if index < 2 { 302 } else { 200 },
                        headers: if index < 2 {
                            vec![(
                                "location".into(),
                                format!("https://deadline.test/{}", index + 1),
                            )]
                        } else {
                            vec![("content-type".into(), "text/html".into())]
                        },
                        content_length: Some(0),
                        upload: None,
                    })
                    .unwrap();
                sender
                    .blocking_send(crate::network::NetworkEvent::Complete {
                        encoded_body_size: None,
                        request_id: request.request_id,
                    })
                    .unwrap();
                Ok(crate::network::NetworkOperation {
                    body_demand_pending: Default::default(),
                    prefetched: Default::default(),
                    request_id: request.request_id,
                    events,
                    demand: None,
                })
            }
            fn cancel_operation(&self, _id: u64) -> Result<(), crate::network::NetworkError> {
                self.cancelled.fetch_add(1, Ordering::SeqCst);
                Ok(())
            }
        }
        let calls = Arc::new(AtomicUsize::new(0));
        let cancelled = Arc::new(AtomicUsize::new(0));
        let mut page = PageState::new(
            PageId(193),
            None,
            BrowserConfig {
                navigation_timeout: Duration::from_millis(25),
                ..Default::default()
            },
            ContextOptions::default(),
            Some(SharedNetworkBroker::new(RedirectChain {
                calls: calls.clone(),
                cancelled: cancelled.clone(),
            })),
            #[cfg(all(unix, feature = "v8-host"))]
            None,
        );
        assert!(
            matches!(page.navigate("https://deadline.test/0".into(),HistoryUpdate::Push),
            Err(RuntimeError::WorkerLimitExceeded{resource}) if resource=="navigation wall time")
        );
        assert!(calls.load(Ordering::SeqCst) <= 2);
        page.broker
            .as_ref()
            .unwrap()
            .drain_owned_operations(Duration::from_secs(2))
            .unwrap();
    }

    #[cfg(feature = "v8-host")]
    #[test]
    fn navigation_cancels_timeout_and_stale_header_operations() {
        struct MalformedNavigation {
            stale: bool,
            cancelled: Arc<AtomicUsize>,
        }
        impl NetworkBroker for MalformedNavigation {
            fn send(
                &self,
                _request: NetworkRequest,
            ) -> Result<NetworkResponse, crate::network::NetworkError> {
                unreachable!("navigation uses the operation path")
            }
            fn start_operation(
                &self,
                request: NetworkRequest,
            ) -> Result<crate::network::NetworkOperation, crate::network::NetworkError>
            {
                let (sender, events) = tokio::sync::mpsc::channel(2);
                if self.stale {
                    sender
                        .blocking_send(crate::network::NetworkEvent::Headers {
                            response_policy: None,
                            timing: None,
                            request_id: request.request_id + 1,
                            status: 200,
                            headers: Vec::new(),
                            content_length: Some(0),
                            upload: None,
                        })
                        .unwrap();
                } else {
                    std::thread::spawn(move || {
                        std::thread::sleep(Duration::from_secs(1));
                        drop(sender);
                    });
                }
                Ok(crate::network::NetworkOperation {
                    body_demand_pending: Default::default(),
                    prefetched: Default::default(),
                    request_id: request.request_id,
                    events,
                    demand: None,
                })
            }
            fn cancel_operation(
                &self,
                _request_id: u64,
            ) -> Result<(), crate::network::NetworkError> {
                self.cancelled.fetch_add(1, Ordering::SeqCst);
                Ok(())
            }
        }

        for stale in [false, true] {
            let cancelled = Arc::new(AtomicUsize::new(0));
            let config = BrowserConfig {
                navigation_timeout: if stale {
                    Duration::from_secs(2)
                } else {
                    Duration::from_millis(10)
                },
                ..BrowserConfig::default()
            };
            let mut page = PageState::new(
                PageId(190),
                None,
                config,
                ContextOptions::default(),
                Some(SharedNetworkBroker::new(MalformedNavigation {
                    stale,
                    cancelled: cancelled.clone(),
                })),
                #[cfg(all(unix, feature = "v8-host"))]
                None,
            );
            let error = page
                .navigate("https://timeout.example/".into(), HistoryUpdate::Push)
                .expect_err("malformed navigation must fail closed");
            if stale {
                assert!(
                    matches!(error, RuntimeError::Network(message) if message=="native network event identity mismatch")
                );
            } else {
                assert!(matches!(error, RuntimeError::WorkerLimitExceeded { .. }));
            }
            page.broker
                .as_ref()
                .unwrap()
                .drain_owned_operations(Duration::from_secs(2))
                .unwrap();
            if stale {
                assert_eq!(cancelled.load(Ordering::SeqCst), 1);
            } else {
                // Timeout can now precede admission, in which case no native
                // transport exists to cancel. Admitted work must drain above.
                assert!(cancelled.load(Ordering::SeqCst) <= 1);
            }
        }
    }

    #[cfg(feature = "v8-host")]
    #[test]
    fn csp_meta_order_guards_base_and_inline_attributes() {
        let mut page = PageState::new(
            PageId(92),
            None,
            BrowserConfig::default(),
            ContextOptions::default(),
            None,
            #[cfg(all(unix, feature = "v8-host"))]
            None,
        );
        page.url = "https://app.example/".into();
        page.csp = crate::csp::CspPolicySet::new(page.url.clone());
        let filtered = page.enforce_csp_html(
            r#"<script>globalThis.beforeMeta=true</script>
               <meta http-equiv="content-security-policy" content="base-uri 'none'; script-src-attr 'none'; style-src-attr 'none'">
               <base href="https://evil.example/">
               <button onclick="attack()" style="display:none">Safe</button>"#,
        );
        assert!(filtered.contains("beforeMeta"));
        assert!(!filtered.contains("evil.example"));
        assert!(!filtered.contains("onclick"));
        assert!(!filtered.contains("display:none"));
        let directives = page
            .trace
            .events()
            .iter()
            .filter_map(|event| match &event.kind {
                TraceEventKind::CspViolation {
                    effective_directive,
                    ..
                } => Some(effective_directive.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(directives.contains(&"base-uri"));
        assert!(directives.contains(&"script-src-attr"));
        assert!(directives.contains(&"style-src-attr"));
    }

    #[cfg(unix)]
    #[test]
    fn platform_window_state_distinguishes_parked_and_retired_document_authority() {
        use oryn_js::{
            message_wire::{MessageRequest, WindowTarget},
            platform_control::{Request, Response},
            worker_wire::Creator,
        };
        let context = Browser::in_process_with_config(BrowserConfig::default()).new_context();
        let page = context.new_page();
        let id = page.page_id();
        context
            .install_document_security(id, "https://app.example/page".into(), &[])
            .unwrap();
        context
            .handle_message_wire(
                id,
                MessageRequest::RegisterRootDocument {
                    document_generation: 1,
                    stream_epoch: 0,
                },
            )
            .unwrap();
        let creator = Creator::Window {
            target: WindowTarget::Root,
            document_generation: 1,
            stream_epoch: 0,
        };
        assert!(matches!(
            context
                .native_platform_query(id, creator.clone(), Request::WindowState)
                .unwrap(),
            Response::WindowState { .. }
        ));
        let token = context
            .inner
            .group
            .messages
            .lock()
            .unwrap()
            .park_document_authority(id.0, 1, 0)
            .unwrap();
        assert!(matches!(
            context
                .native_platform_query(id, creator.clone(), Request::WindowState)
                .unwrap(),
            Response::WindowSuspended
        ));
        context
            .inner
            .group
            .messages
            .lock()
            .unwrap()
            .discard_parked_document(id.0, &token)
            .unwrap();
        assert!(matches!(
            context
                .native_platform_query(id, creator, Request::WindowState)
                .unwrap(),
            Response::WindowRetired
        ));
    }

    #[cfg(unix)]
    #[test]
    fn native_permission_query_uses_top_and_embedded_committed_origins() {
        use oryn_js::{
            message_wire::{MessageRequest, WindowTarget},
            platform_control::{PermissionDescriptor, PermissionState, Request, Response},
            worker_wire::Creator,
        };
        let context = Browser::in_process_with_config(BrowserConfig::default()).new_context();
        let page = context.new_page();
        let id = page.page_id();
        context
            .install_document_security(id, "https://top.test/".into(), &[])
            .unwrap();
        context
            .handle_message_wire(
                id,
                MessageRequest::RegisterRootDocument {
                    document_generation: 1,
                    stream_epoch: 0,
                },
            )
            .unwrap();
        let frame = "c".repeat(64);
        let url = "https://embedded.test/frame";
        context
            .handle_message_wire(
                id,
                MessageRequest::RegisterWindow {
                    frame: frame.clone(),
                    document_generation: 1,
                    stream_epoch: 0,
                    origin: "https://embedded.test".into(),
                    inherit_origin: None,
                },
            )
            .unwrap();
        let policy = context
            .prepare_frame_worker_policy(id, url, &[], "")
            .unwrap();
        context
            .bind_frame_worker_policy(id, frame.clone(), 1, 0, url, &policy)
            .unwrap();
        let descriptor = PermissionDescriptor {
            name: "notifications".into(),
            sysex: None,
            pan_tilt_zoom: None,
            allow_without_gesture: None,
        };
        context
            .webdriver_set_permission_partitioned(
                "https://top.test",
                "https://embedded.test",
                descriptor.clone(),
                PermissionState::Granted,
            )
            .unwrap();
        let child = Creator::Window {
            target: WindowTarget::Frame(frame.clone()),
            document_generation: 1,
            stream_epoch: 0,
        };
        let root = Creator::Window {
            target: WindowTarget::Root,
            document_generation: 1,
            stream_epoch: 0,
        };
        assert!(matches!(
            context
                .native_platform_query(
                    id,
                    child,
                    Request::Permission {
                        descriptor: descriptor.clone()
                    }
                )
                .unwrap(),
            Response::Permission {
                state: PermissionState::Granted,
                ..
            }
        ));
        assert!(matches!(
            context
                .native_platform_query(id, root, Request::Permission { descriptor })
                .unwrap(),
            Response::Permission {
                state: PermissionState::Prompt,
                ..
            }
        ));
        let mut snapshot = crate::host::webdriver_script::AutomationRealmSnapshot {
            realm: oryn_js::realm::RealmId(1),
            parent_realm: Some(oryn_js::realm::RealmId(0)),
            frame: None,
            frame_generation: Some(1),
            frame_token: Some(frame),
            document_root: oryn_dom::DomRuntime::new().document(),
            document_generation: 1,
            stream_epoch: 0,
            document_authority_epoch: 0,
            url: "https://forged.test".into(),
            live: true,
        };
        assert_eq!(
            context.webdriver_permission_origins(id, &snapshot).unwrap(),
            ("https://top.test".into(), "https://embedded.test".into())
        );
        snapshot.live = false;
        assert!(context.webdriver_permission_origins(id, &snapshot).is_err());
    }

    #[cfg(unix)]
    #[test]
    fn storage_access_grant_uses_committed_partition_and_rejects_retired_request() {
        use oryn_js::{
            message_wire::{MessageRequest as Q, WindowTarget as T},
            platform_control::{PermissionDescriptor, PermissionState, Request, Response},
            worker_wire::Creator,
        };
        let context = Browser::in_process_with_config(BrowserConfig::default()).new_context();
        let page = context.new_page();
        let id = page.page_id();
        context
            .install_document_security(id, "https://top.test/".into(), &[])
            .unwrap();
        context
            .handle_message_wire(
                id,
                Q::RegisterRootDocument {
                    document_generation: 1,
                    stream_epoch: 0,
                },
            )
            .unwrap();
        let frame = "e".repeat(64);
        let url = "https://embedded.test/frame";
        context
            .handle_message_wire(
                id,
                Q::RegisterWindow {
                    frame: frame.clone(),
                    document_generation: 1,
                    stream_epoch: 0,
                    origin: "https://embedded.test".into(),
                    inherit_origin: None,
                },
            )
            .unwrap();
        let policy = context
            .prepare_frame_worker_policy(id, url, &[], "")
            .unwrap();
        context
            .bind_frame_worker_policy(id, frame.clone(), 1, 0, url, &policy)
            .unwrap();
        context
            .register_activation_parent(crate::runtime::worker_service::ActivationParentInputs {
                page: id,
                frame: frame.clone(),
                generation: 1,
                epoch: 0,
                parent: T::Root,
                parent_generation: 1,
                parent_epoch: 0,
            })
            .unwrap();
        context
            .register_isolation_container(
                crate::runtime::worker_service::IsolationContainerInputs {
                    page: id,
                    frame: frame.clone(),
                    generation: 1,
                    epoch: 0,
                    allow: "storage-access *".into(),
                    source: url.into(),
                    sandbox: None,
                },
            )
            .unwrap();
        let child = Creator::Window {
            target: T::Frame(frame.clone()),
            document_generation: 1,
            stream_epoch: 0,
        };
        let root_owner = context.window_worker_creator(id, &T::Root, 1, 0).unwrap().0;
        let child_owner = context
            .window_worker_creator(id, &T::Frame(frame.clone()), 1, 0)
            .unwrap()
            .0;
        assert!(
            !context.worker_secure_context(&child_owner).unwrap(),
            "origin registration alone does not publish secure-context authority"
        );
        context
            .publish_worker_secure_context(root_owner, true)
            .unwrap();
        context
            .publish_worker_secure_context(child_owner.clone(), true)
            .unwrap();
        assert!(context.worker_secure_context(&child_owner).unwrap());
        let descriptor = PermissionDescriptor {
            name: "storage-access".into(),
            sysex: None,
            pan_tilt_zoom: None,
            allow_without_gesture: None,
        };
        assert!(matches!(
            context
                .native_platform_query(id, child.clone(), Request::StorageAccess { request: false })
                .unwrap(),
            Response::StorageAccess { allowed: false }
        ));
        context
            .webdriver_set_permission_partitioned(
                "https://top.test",
                "https://embedded.test",
                descriptor.clone(),
                PermissionState::Denied,
            )
            .unwrap();
        assert!(matches!(
            context
                .native_platform_query(id, child.clone(), Request::StorageAccess { request: true })
                .unwrap(),
            Response::StorageAccess { allowed: false }
        ));
        context
            .webdriver_set_permission_partitioned(
                "https://top.test",
                "https://embedded.test",
                descriptor.clone(),
                PermissionState::Granted,
            )
            .unwrap();
        assert!(matches!(
            context
                .native_platform_query(id, child.clone(), Request::StorageAccess { request: true })
                .unwrap(),
            Response::StorageAccess { allowed: true }
        ));
        assert!(matches!(
            context
                .native_platform_query(id, child.clone(), Request::StorageAccess { request: false })
                .unwrap(),
            Response::StorageAccess { allowed: true }
        ));
        // Denying future grants does not silently revoke an existing cookie grant.
        context
            .webdriver_set_permission_partitioned(
                "https://top.test",
                "https://embedded.test",
                descriptor,
                PermissionState::Denied,
            )
            .unwrap();
        assert!(matches!(
            context
                .native_platform_query(id, child.clone(), Request::StorageAccess { request: true })
                .unwrap(),
            Response::StorageAccess { allowed: true }
        ));
        let mut stale = child;
        let Creator::Window {
            document_generation,
            ..
        } = &mut stale
        else {
            unreachable!()
        };
        *document_generation = 2;
        assert!(
            context
                .native_platform_query(id, stale, Request::StorageAccess { request: true })
                .is_err()
        );
    }

