    #[cfg(unix)]
    #[test]
    fn cached_frame_authority_preserves_root_sibling_and_exact_subtree_owner() {
        use oryn_js::message_wire::{MessageRequest as Q, MessageResponse as R, WindowTarget as T};
        use oryn_js::worker_wire::Creator;
        let context = Browser::in_process_with_config(BrowserConfig::default()).new_context();
        let page = context.new_page();
        let id = page.page_id();
        context
            .install_document_security(id, "https://root.example/".into(), &[])
            .unwrap();
        context
            .handle_message_wire(
                id,
                Q::RegisterRootDocument {
                    document_generation: 1,
                    stream_epoch: 0,
                },
            )
            .unwrap();
        let root = Creator::Window {
            target: T::Root,
            document_generation: 1,
            stream_epoch: 0,
        };
        let frame = "a".repeat(64);
        let child = "b".repeat(64);
        let sibling = "c".repeat(64);
        for (token, parent) in [
            (frame.clone(), T::Root),
            (child.clone(), T::Frame(frame.clone())),
            (sibling.clone(), T::Root),
        ] {
            context
                .handle_message_wire(
                    id,
                    Q::RegisterWindow {
                        frame: token.clone(),
                        document_generation: 1,
                        stream_epoch: 0,
                        origin: "null".into(),
                        inherit_origin: None,
                    },
                )
                .unwrap();
            let ticket = context
                .prepare_frame_worker_policy(id, "https://child.example/", &[], "")
                .unwrap();
            context
                .bind_frame_worker_policy(
                    id,
                    token.clone(),
                    1,
                    0,
                    "https://child.example/",
                    &ticket,
                )
                .unwrap();
            context
                .register_activation_parent(
                    crate::runtime::worker_service::ActivationParentInputs {
                        page: id,
                        frame: token,
                        generation: 1,
                        epoch: 0,
                        parent,
                        parent_generation: 1,
                        parent_epoch: 0,
                    },
                )
                .unwrap();
        }
        let creator = Creator::Window {
            target: T::Frame(frame.clone()),
            document_generation: 1,
            stream_epoch: 0,
        };
        let owner = crate::agent_registry::AgentOwner::Window {
            page: id,
            target: T::Frame(frame.clone()),
            generation: 1,
            epoch: 0,
        };
        let R::DocumentParked(token) = context
            .handle_message_wire(id, Q::ParkFrameDocument { creator })
            .unwrap()
        else {
            panic!()
        };
        assert!(context.native_worker_authority(&owner).is_err());
        assert!(context.retained_worker_authority(&owner).is_ok());
        assert!(context.window_worker_creator(id, &T::Root, 1, 0).is_ok());
        assert!(
            context
                .window_worker_creator(id, &T::Frame(sibling.clone()), 1, 0)
                .is_ok()
        );
        assert!(
            context
                .window_worker_creator(id, &T::Frame(child.clone()), 1, 0)
                .is_err()
        );
        assert!(
            context
                .handle_message_wire(
                    id,
                    Q::RestoreDocument {
                        token: token.clone()
                    }
                )
                .is_err()
        );
        assert!(
            context
                .handle_message_wire(
                    id,
                    Q::RestoreFrameDocument {
                        token: token.clone(),
                        parent: Creator::Window {
                            target: T::Frame(sibling),
                            document_generation: 1,
                            stream_epoch: 0
                        },
                        frame: frame.clone()
                    }
                )
                .is_err()
        );
        assert!(
            context
                .handle_message_wire(
                    id,
                    Q::RegisterWindow {
                        frame: frame.clone(),
                        document_generation: 1,
                        stream_epoch: 0,
                        origin: "null".into(),
                        inherit_origin: None
                    }
                )
                .is_err()
        );
        assert!(matches!(
            context
                .handle_message_wire(
                    id,
                    Q::RestoreFrameDocument {
                        token: token.clone(),
                        parent: root.clone(),
                        frame: frame.clone()
                    }
                )
                .unwrap(),
            R::DocumentRestored {
                document_generation: 1,
                stream_epoch: 0
            }
        ));
        assert!(context.native_worker_authority(&owner).is_ok());
        assert!(
            context
                .window_worker_creator(id, &T::Frame(child), 1, 0)
                .is_ok()
        );
        assert!(matches!(
            context.handle_message_wire(
                id,
                Q::RestoreFrameDocument {
                    token,
                    parent: root,
                    frame
                }
            ),
            Ok(oryn_js::message_wire::MessageResponse::DocumentRestored { .. })
        ));
    }

    #[cfg(unix)]
    #[test]
    fn cached_security_restores_original_opaque_identity_and_policy_atomically() {
        use oryn_js::message_wire::{MessageRequest, MessageResponse};
        let context = Browser::in_process_with_config(BrowserConfig::default()).new_context();
        let page = context.new_page();
        let id = page.page_id();
        let other = context.new_page();
        context
            .install_document_security(
                id,
                "https://app.example/old".into(),
                &[
                    (
                        "content-security-policy".into(),
                        "sandbox allow-scripts".into(),
                    ),
                    ("referrer-policy".into(), "no-referrer".into()),
                    ("cross-origin-opener-policy".into(), "same-origin".into()),
                    ("cross-origin-embedder-policy".into(), "require-corp".into()),
                ],
            )
            .unwrap();
        let original = context.security_origin(id).unwrap();
        context
            .handle_message_wire(
                id,
                MessageRequest::RegisterRootDocument {
                    document_generation: 1,
                    stream_epoch: 0,
                },
            )
            .unwrap();
        let frame = "9".repeat(64);
        let frame_target = oryn_js::message_wire::WindowTarget::Frame(frame.clone());
        context
            .handle_message_wire(
                id,
                MessageRequest::RegisterWindow {
                    frame: frame.clone(),
                    document_generation: 8,
                    stream_epoch: 1,
                    origin: "null".into(),
                    inherit_origin: None,
                },
            )
            .unwrap();
        let ticket = context
            .prepare_frame_worker_policy(id, "https://child.example/old", &[], "")
            .unwrap();
        context
            .bind_frame_worker_policy(
                id,
                frame.clone(),
                8,
                1,
                "https://child.example/old",
                &ticket,
            )
            .unwrap();
        let old_frame_origin = context
            .window_worker_creator(id, &frame_target, 8, 1)
            .unwrap()
            .2;
        let retained_owner = crate::agent_registry::AgentOwner::Window {
            page: id,
            target: oryn_js::message_wire::WindowTarget::Root,
            generation: 1,
            epoch: 0,
        };
        let authority = context.native_worker_authority(&retained_owner).unwrap();
        let MessageResponse::DocumentParked(old) = context
            .handle_message_wire(
                id,
                MessageRequest::ParkDocument {
                    document_generation: 1,
                    stream_epoch: 0,
                },
            )
            .unwrap()
        else {
            panic!()
        };
        assert!(
            context.native_worker_authority(&retained_owner).is_err(),
            "frozen document cannot create new work"
        );
        assert!(
            context
                .window_worker_creator(id, &frame_target, 8, 1)
                .is_err()
        );
        assert_eq!(
            context
                .retained_worker_authority(&retained_owner)
                .unwrap()
                .1
                .authority,
            authority.1.authority
        );
        context
            .install_document_security(id, "https://new.example/".into(), &[])
            .unwrap();
        let newer = context.security_origin(id).unwrap();
        assert_ne!(original, newer);
        let retained = context.retained_worker_authority(&retained_owner).unwrap();
        assert_eq!(retained.0, authority.0);
        assert_eq!(retained.1.authority, authority.1.authority);
        context
            .handle_message_wire(
                id,
                MessageRequest::RegisterRootDocument {
                    document_generation: 2,
                    stream_epoch: 0,
                },
            )
            .unwrap();
        context
            .handle_message_wire(
                id,
                MessageRequest::RegisterWindow {
                    frame: frame.clone(),
                    document_generation: 9,
                    stream_epoch: 0,
                    origin: "https://child.example".into(),
                    inherit_origin: None,
                },
            )
            .unwrap();
        let ticket = context
            .prepare_frame_worker_policy(id, "https://child.example/new", &[], "")
            .unwrap();
        context
            .bind_frame_worker_policy(
                id,
                frame.clone(),
                9,
                0,
                "https://child.example/new",
                &ticket,
            )
            .unwrap();
        assert!(
            context
                .handle_message_wire(id, MessageRequest::RestoreDocument { token: old.clone() })
                .is_err()
        );
        assert_eq!(context.security_origin(id).unwrap(), newer);
        assert!(
            context
                .handle_message_wire(
                    other.page_id(),
                    MessageRequest::RestoreDocument { token: old.clone() }
                )
                .is_err()
        );
        let MessageResponse::DocumentParked(next) = context
            .handle_message_wire(
                id,
                MessageRequest::ParkDocument {
                    document_generation: 2,
                    stream_epoch: 0,
                },
            )
            .unwrap()
        else {
            panic!()
        };
        context
            .handle_message_wire(id, MessageRequest::RestoreDocument { token: old.clone() })
            .unwrap();
        assert_eq!(context.security_origin(id).unwrap(), original);
        assert_eq!(
            context
                .window_worker_creator(id, &frame_target, 8, 1)
                .unwrap()
                .2
                .authority,
            old_frame_origin.authority
        );
        assert!(
            context
                .window_worker_creator(id, &frame_target, 9, 0)
                .is_err()
        );
        let isolation = context.inner.worker_policies.lock().unwrap().root_isolation[&id];
        assert!(isolation.same_origin_opener);
        assert_eq!(
            isolation.embedder,
            crate::agent_isolation::EmbedderPolicy::RequireCorp
        );
        assert_eq!(
            context
                .inner
                .document_referrer_policy
                .lock()
                .unwrap()
                .get(&id),
            Some(&crate::referrer::ReferrerPolicy::NoReferrer)
        );
        assert!(
            context
                .inner
                .document_security
                .lock()
                .unwrap()
                .get(&id)
                .unwrap()
                .sandbox()
                .is_some_and(|sandbox| !sandbox.allow_same_origin)
        );
        assert!(matches!(
            context.handle_message_wire(id, MessageRequest::RestoreDocument { token: old }),
            Ok(MessageResponse::DocumentRestored { .. })
        ));
        assert_eq!(
            context.security_origin(id).unwrap(),
            original,
            "identical ACK retry must not bind another document"
        );
        context
            .handle_message_wire(id, MessageRequest::DiscardDocument { token: next })
            .unwrap();
        assert!(
            context
                .inner
                .cached_document_security
                .lock()
                .unwrap()
                .is_empty()
        );
    }

