    #[cfg(unix)]
    #[test]
    fn concurrent_context_event_publication_preserves_cursor_order() {
        let context = Browser::new().new_context();
        let page = context.new_page();
        let id = page.page_id();
        let start = Arc::new(std::sync::Barrier::new(5));
        let writers = (0..4)
            .map(|producer| {
                let context = context.clone();
                let start = start.clone();
                std::thread::spawn(move || {
                    start.wait();
                    for sequence in 0..128 {
                        context.record_context_diagnostic(ContextEvent::CspReport {
                            target_page_id: id,
                            endpoint: format!("https://report.test/{producer}/{sequence}"),
                            format: crate::csp::CspReportFormat::LegacyReportUri,
                            outcome: "delivered".into(),
                        });
                        std::thread::yield_now();
                    }
                })
            })
            .collect::<Vec<_>>();
        start.wait();
        for writer in writers {
            writer.join().unwrap();
        }
        let events = context.inner.context_events.lock().unwrap();
        assert_eq!(events.len(), 256);
        assert_eq!(events.evidence().diagnostics_pruned, 256);
        assert!(
            events
                .iter()
                .collect::<Vec<_>>()
                .windows(2)
                .all(|pair| pair[0].event_id < pair[1].event_id)
        );
        // Small cursor pages recover the bounded retained diagnostic suffix exactly
        // once; this is the same monotone filter used by Window polling.
        let mut cursor = 0;
        let mut observed = Vec::new();
        loop {
            let batch = events
                .iter()
                .filter(|record| record.event_id > cursor)
                .take(7)
                .collect::<Vec<_>>();
            if batch.is_empty() {
                break;
            }
            cursor = batch.last().unwrap().event_id;
            observed.extend(batch.into_iter().map(|record| record.event_id));
        }
        assert_eq!(observed.len(), 256);
        assert_eq!(observed.into_iter().collect::<BTreeSet<_>>().len(), 256);
    }

