    #[cfg(unix)]
    #[test]
    fn poisoned_report_queue_preserves_complete_violation_batch() {
        let context = Browser::new().new_context_with_broker(
            ContextOptions::default(),
            SharedNetworkBroker::new(crate::network::UnavailableBroker),
        );
        let page = context.new_page();
        let id = page.page_id();
        let poisoned = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let _state = context.inner.csp_reporting.lock().unwrap();
            panic!("injected report-state panic");
        }));
        assert!(poisoned.is_err());
        let mut policy = crate::csp::CspPolicySet::new("https://source.test/");
        policy.install(
            "trusted-types 'none'; report-uri /report",
            crate::csp::CspDisposition::Enforce,
            "header",
        );
        policy.install(
            "trusted-types 'none'; report-uri /second-report",
            crate::csp::CspDisposition::Report,
            "header",
        );
        let decision = policy.authorize_trusted_type_policy("name", false);
        assert!(!decision.allowed);
        assert_eq!(decision.violations.len(), 2);
        let creator = context.native_initial_document_creator(id).unwrap();
        context
            .handle_csp_violations_for_creator(
                id,
                decision.violations,
                Some(&policy),
                Some(creator),
            )
            .unwrap();
        assert!(context.inner.csp_reporting.is_poisoned());
        let events = context.inner.context_events.lock().unwrap();
        assert_eq!(events.iter().filter(|record|matches!(&record.event,ContextEvent::CspViolation{target_page_id,..}if *target_page_id==id)).count(),2);
        assert_eq!(events.iter().filter(|record|matches!(&record.event,ContextEvent::CspReport{target_page_id,outcome,..}if *target_page_id==id&&outcome=="queue_poisoned")).count(),2);
    }

    #[test]
    fn dropping_context_cancels_report_operation_without_retaining_context() {
        use std::sync::atomic::AtomicBool;
        struct PendingReport {
            started: Arc<AtomicBool>,
            cancelled: Arc<AtomicBool>,
            stream: Mutex<Option<tokio::sync::mpsc::Sender<crate::network::NetworkEvent>>>,
        }
        impl crate::network::NetworkBroker for PendingReport {
            fn send(
                &self,
                _: NetworkRequest,
            ) -> Result<crate::network::NetworkResponse, crate::network::NetworkError> {
                panic!("report must use cancellable operation");
            }
            fn start_operation(
                &self,
                request: NetworkRequest,
            ) -> Result<crate::network::NetworkOperation, crate::network::NetworkError>
            {
                let (sender, events) = tokio::sync::mpsc::channel(1);
                *self.stream.lock().unwrap() = Some(sender);
                self.started.store(true, Ordering::Release);
                Ok(crate::network::NetworkOperation {
                    body_demand_pending: Default::default(),
                    prefetched: Default::default(),
                    request_id: request.request_id,
                    events,
                    demand: None,
                })
            }
            fn cancel_operation(&self, _: u64) -> Result<(), crate::network::NetworkError> {
                self.cancelled.store(true, Ordering::Release);
                self.stream.lock().unwrap().take();
                Ok(())
            }
        }
        let started = Arc::new(AtomicBool::new(false));
        let cancelled = Arc::new(AtomicBool::new(false));
        let context = Browser::new().new_context_with_broker(
            ContextOptions::default(),
            SharedNetworkBroker::new(PendingReport {
                started: started.clone(),
                cancelled: cancelled.clone(),
                stream: Mutex::new(None),
            }),
        );
        let weak = Arc::downgrade(&context.inner);
        let accounting = context.inner.csp_reporting.clone();
        context
            .queue_native_report_payload(
                None,
                "https://top.test/".into(),
                crate::csp::CspReportTarget {
                    url: "https://source.test/report".into(),
                    format: crate::csp::CspReportFormat::LegacyReportUri,
                },
                "https://source.test/".into(),
                "application/csp-report".into(),
                b"{}".to_vec(),
            )
            .unwrap();
        let deadline = Instant::now() + Duration::from_secs(2);
        while !started.load(Ordering::Acquire) && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(1));
        }
        assert!(started.load(Ordering::Acquire));
        drop(context);
        assert!(
            weak.upgrade().is_none(),
            "report worker must not own context"
        );
        while accounting.lock().unwrap().pending != 0 && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(1));
        }
        assert_eq!(accounting.lock().unwrap().pending, 0);
        assert!(cancelled.load(Ordering::Acquire));
    }

