    #[cfg(feature = "v8-host")]
    #[test]
    fn rollback_pageshow_retains_failed_publication_and_dispatches_once() {
        let mut page = PageState::new(
            PageId(721),
            None,
            BrowserConfig::default(),
            ContextOptions::default(),
            None,
            #[cfg(unix)]
            None,
        );
        page.load_document("https://history.test/rollback".into(), "<p>retained</p><script>globalThis.shows=[];onpageshow=e=>shows.push(e.persisted)</script>", None, None, HistoryUpdate::Push, &BTreeMap::new(), Vec::new()).unwrap();
        page.executable
            .as_mut()
            .unwrap()
            .execute("shows=[]")
            .unwrap();
        page.queue_rollback_pageshow(true).unwrap();
        let identity = page.history_publications.front().unwrap().identity;
        ROOT_RESTORE_PUBLICATION_FAULT.with(|fault| fault.set(true));
        assert!(page.poll_history_publications().is_err());
        assert_eq!(page.history_publications.len(), 1);
        assert_eq!(
            page.history_publications.front().unwrap().identity,
            identity
        );
        assert_eq!(
            page.executable
                .as_mut()
                .unwrap()
                .evaluate("shows.length")
                .unwrap(),
            "0"
        );
        finish_fixture_rollback_publication(&mut page);
        assert_eq!(
            page.executable
                .as_mut()
                .unwrap()
                .evaluate("shows.join(',')")
                .unwrap(),
            "true"
        );
        page.poll_history_publications().unwrap();
        assert_eq!(
            page.executable
                .as_mut()
                .unwrap()
                .evaluate("shows.join(',')")
                .unwrap(),
            "true"
        );
    }

    #[cfg(feature = "v8-host")]
    #[test]
    fn constructor_failure_recovers_push_and_reload_without_duplicate_pagehide() {
        for (update, persisted) in [(HistoryUpdate::Push, true), (HistoryUpdate::Reload, false)] {
            let mut page = PageState::new(
                PageId(219),
                None,
                BrowserConfig::default(),
                ContextOptions::default(),
                None,
                #[cfg(unix)]
                None,
            );
            page.bind_direct_fixture_terminal_owner();
            page.load_document("https://history.test/source".into(),"<p>retained</p><script>globalThis.kept=document;globalThis.transitions=[];onpagehide=e=>transitions.push('hide:'+e.persisted);onpageshow=e=>transitions.push('show:'+e.persisted)</script>",None,None,HistoryUpdate::Push,&BTreeMap::new(),Vec::new()).unwrap();
            settle_fixture_document(&mut page);
            let generation = page.document_generation;
            page.executable
                .as_mut()
                .unwrap()
                .execute("transitions=[]")
                .unwrap();
            let mut resources = BTreeMap::new();
            resources.insert(
                "oryn:frame-history".into(),
                "invalid native snapshot".into(),
            );
            page.network_quiet_since = Some(
                Instant::now()
                    .checked_sub(NETWORK_IDLE_QUIET_PERIOD)
                    .unwrap(),
            );
            let attempt = Instant::now();
            // A different URL avoids replacing the injected failure with the
            // legitimate same-resource restoration payload during reload.
            assert!(
                page.load_document(
                    "https://history.test/rejected".into(),
                    "<p>new</p>",
                    None,
                    None,
                    update,
                    &resources,
                    Vec::new()
                )
                .is_err()
            );
            assert_eq!(page.url, "https://history.test/source");
            assert_eq!(page.document_generation, generation);
            assert_eq!(page.history.len(), 1);
            assert_eq!(
                page.executable
                    .as_mut()
                    .unwrap()
                    .evaluate("kept===document")
                    .unwrap(),
                "true"
            );
            finish_fixture_rollback_publication(&mut page);
            assert_eq!(
                page.executable
                    .as_mut()
                    .unwrap()
                    .evaluate("transitions.join(',')")
                    .unwrap(),
                format!("hide:{persisted},show:{persisted}")
            );
            assert!(
                page.network_quiet_since.is_some_and(|at| at >= attempt),
                "rollback establishes a fresh quiet interval"
            );
            assert!(
                !page
                    .wait_satisfied(&WaitPredicate::Lifecycle(LifecycleState::NetworkIdle))
                    .unwrap()
            );
            page.wait_for_timeout(
                &WaitPredicate::Lifecycle(LifecycleState::NetworkIdle),
                Some(NETWORK_IDLE_QUIET_PERIOD + Duration::from_secs(2)),
            )
            .unwrap();
        }
    }

    #[cfg(all(unix, feature = "v8-host", feature = "in-process-probe"))]
    #[test]
    fn initial_constructor_failure_restores_native_blank_authority_and_allows_retry() {
        let context = Browser::in_process_probe().new_context();
        let handle = context.new_page();
        let id = handle.page_id();
        let client = crate::context_service::SharedContextClient::direct(context.clone(), id);
        let mut page = PageState::new(
            id,
            None,
            BrowserConfig::default(),
            ContextOptions::default(),
            None,
            Some(client),
        );
        let original_url = page.url.clone();
        let original = context
            .native_document_authority(id, "about:blank")
            .unwrap();
        let resources = BTreeMap::from([(
            "oryn:frame-history".into(),
            "invalid native snapshot".into(),
        )]);
        assert!(
            page.load_document_with_redirect_history(
                "https://initial.test/rejected".into(),
                "<p>rejected</p>",
                None,
                None,
                HistoryUpdate::Push,
                &resources,
                Vec::new(),
                false,
                Some(Vec::new())
            )
            .is_err()
        );
        assert!(page.executable.is_none());
        assert!(page.history.is_empty());
        assert_eq!(page.url, original_url);
        let restored = context
            .native_document_authority(id, "about:blank")
            .unwrap();
        assert_eq!(
            (restored.0, restored.1, restored.4),
            (original.0, original.1, true)
        );
        page.navigate_data_document(
            Url::parse("data:text/html,%3Ctitle%3ERetry%3C/title%3E").unwrap(),
            "data:text/html,%3Ctitle%3ERetry%3C/title%3E".into(),
            HistoryUpdate::Push,
        )
        .unwrap();
        assert_eq!(
            page.executable
                .as_mut()
                .unwrap()
                .evaluate("document.title")
                .unwrap(),
            "Retry"
        );
        assert!(!context.native_document_authority(id, &page.url).unwrap().4);
    }

