    #[cfg(feature = "v8-host")]
    #[test]
    fn queued_navigation_cannot_reacquire_authority_after_supersession() {
        for source in ["https://history.test/source", "data:text/html,source"] {
            let mut page = PageState::new(
                PageId(214),
                None,
                BrowserConfig::default(),
                ContextOptions::default(),
                None,
                #[cfg(unix)]
                None,
            );
            page.load_document(
                source.into(),
                "<p>retained</p>",
                None,
                None,
                HistoryUpdate::Push,
                &BTreeMap::new(),
                Vec::new(),
            )
            .unwrap();
            let generation = page.document_generation;
            page.executable
                .as_mut()
                .unwrap()
                .execute("location.href='about:blank'")
                .unwrap();
            let stale = page
                .executable
                .as_ref()
                .unwrap()
                .take_location_navigation()
                .unwrap();
            assert!(stale.navigation_operation.is_some());
            page.executable
                .as_mut()
                .unwrap()
                .execute("location.href='https://history.test/newer'")
                .unwrap();
            assert!(matches!(
                page.navigate_script(stale, HistoryUpdate::Push),
                Err(RuntimeError::NavigationCancelled)
            ));
            assert_eq!(page.document_generation, generation);
            assert_eq!(page.url, source);
            let newer = page
                .executable
                .as_ref()
                .unwrap()
                .take_location_navigation()
                .unwrap();
            assert_eq!(newer.url, "https://history.test/newer");
            assert!(page.script_navigation_operation.is_none());
            page.executable.take();
            assert!(matches!(
                page.navigate_script(newer, HistoryUpdate::Push),
                Err(RuntimeError::NavigationCancelled)
            ));
            assert_eq!(page.document_generation, generation);
            assert_eq!(page.url, source);
        }
    }

    #[cfg(all(unix, feature = "in-process-probe"))]
    #[test]
    fn navigation_execution_settlement_requires_exact_page_and_receipt() {
        use crate::context_service::{
            ContextServiceRequest as Q, ContextServiceResponse as R, ParentContextService,
        };
        use oryn_js::navigation::{
            NavigationExecutionOutcome as Outcome, NavigationExecutionToken,
        };
        let context = Browser::in_process_probe().new_context();
        let page = context.new_page();
        let other = context.new_page();
        let custody = context
            .inner
            .group
            .pages
            .lock()
            .unwrap()
            .get(&page.page_id())
            .unwrap()
            .queued_navigations
            .clone();
        let mut ticket = custody.admit().unwrap();
        let receipt = ticket.execution_receipt().unwrap();
        drop(ticket);
        let service = ParentContextService::new(context.clone(), page.page_id());
        assert!(
            service
                .handle(Q::SettleNavigationExecution {
                    page_id: other.page_id(),
                    receipt: receipt.clone(),
                    outcome: Outcome::Completed
                })
                .is_err()
        );
        let mut forged = receipt.0.clone();
        forged[0] ^= 1;
        assert!(
            service
                .handle(Q::SettleNavigationExecution {
                    page_id: page.page_id(),
                    receipt: NavigationExecutionToken(forged),
                    outcome: Outcome::Completed
                })
                .is_err()
        );
        assert_eq!(
            context
                .queued_navigation_status(page.page_id())
                .unwrap()
                .active,
            1
        );
        assert!(matches!(
            service
                .handle(Q::ClaimNavigationExecution {
                    page_id: page.page_id(),
                    receipt: receipt.clone()
                })
                .unwrap(),
            R::NavigationExecutionClaimed
        ));
        for _ in 0..2 {
            let request = Q::SettleNavigationExecution {
                page_id: page.page_id(),
                receipt: receipt.clone(),
                outcome: Outcome::Completed,
            };
            let encoded = serde_json::to_vec(&request).unwrap();
            let decoded: Q = serde_json::from_slice(&encoded).unwrap();
            assert!(
                !decoded.author_compatibility_operation(),
                "receipt publication is native-only"
            );
            assert!(matches!(
                service.handle(decoded).unwrap(),
                R::NavigationExecutionSettled
            ));
        }
        assert!(
            service
                .handle(Q::SettleNavigationExecution {
                    page_id: page.page_id(),
                    receipt,
                    outcome: Outcome::Canceled
                })
                .is_err()
        );
        let snapshot = context.queued_navigation_status(page.page_id()).unwrap();
        assert_eq!(snapshot.active, 0);
        assert_eq!(snapshot.outcomes.len(), 1);
        assert_eq!(snapshot.outcomes[0].execution, Some(Outcome::Completed));
        let mut pending = custody.admit().unwrap();
        let retired = pending.execution_receipt().unwrap();
        drop(pending);
        assert!(matches!(
            service
                .handle(Q::ClaimNavigationExecution {
                    page_id: page.page_id(),
                    receipt: retired.clone()
                })
                .unwrap(),
            R::NavigationExecutionClaimed
        ));
        service.cancel_all_network_operations();
        assert!(matches!(
            service
                .handle(Q::ClaimNavigationExecution {
                    page_id: page.page_id(),
                    receipt: retired.clone()
                })
                .unwrap(),
            R::NavigationExecutionClaimRejected
        ));
        assert!(matches!(
            service
                .handle(Q::SettleNavigationExecution {
                    page_id: page.page_id(),
                    receipt: retired,
                    outcome: Outcome::Completed
                })
                .unwrap(),
            R::NavigationExecutionRetired
        ));
        assert!(
            context
                .queued_navigation_status(page.page_id())
                .unwrap()
                .outcomes
                .last()
                .unwrap()
                .result
                .is_err()
        );
    }

