    #[cfg(all(unix, feature = "v8-host", feature = "in-process-probe"))]
    #[tokio::test(flavor = "current_thread")]
    async fn hidden_history_task_attachment_after_cache_eviction_retains_source() {
        struct Attachment(Arc<AtomicUsize>);
        impl NetworkBroker for Attachment {
            fn send(
                &self,
                request: NetworkRequest,
            ) -> Result<NetworkResponse, crate::network::NetworkError> {
                self.0.fetch_add(1, Ordering::SeqCst);
                Ok(NetworkResponse {
                    response_policy: None,
                    timing: None,
                    request_id: request.request_id,
                    status: 200,
                    headers: vec![
                        (
                            "content-disposition".into(),
                            "attachment; filename=history.bin".into(),
                        ),
                        ("content-type".into(), "application/octet-stream".into()),
                    ],
                    body: vec![0, 255, 9],
                })
            }
        }
        let mut options = ContextOptions::default();
        options.action_policy.rules.insert(
            ConsequentialAction::Download,
            crate::security::PolicyRule::Allow,
        );
        let requests = Arc::new(AtomicUsize::new(0));
        let context = Browser::in_process_probe().new_context_with_broker(
            options,
            SharedNetworkBroker::new(Attachment(requests.clone())),
        );
        let page = context.new_page();
        page.load_html("https://history-first.test/", "first")
            .await
            .unwrap();
        let count = MAX_CACHED_DOCUMENTS_PER_PAGE + 2;
        for index in 0..count {
            page.load_html(format!("https://history-other-{index}.test/"), "other")
                .await
                .unwrap();
        }
        page.evaluate(format!("globalThis.kept=document;globalThis.events=[];navigation.onnavigateerror=()=>events.push('error');onpageswap=()=>events.push('swap');history.go(-{count})")).await.unwrap();
        let deadline = Instant::now() + Duration::from_secs(5);
        while context.downloads().is_empty() {
            assert!(
                Instant::now() < deadline,
                "hidden history attachment deadline: requests={} native_publication={:?} page_state={:?}",
                requests.load(Ordering::SeqCst),
                context
                    .inner
                    .worker_policies
                    .try_lock()
                    .ok()
                    .map(|policies| policies
                        .root_lifetimes
                        .get(&page.page_id())
                        .map(|root| (root.epoch, root.initial_materialized))),
                context.inner.group.pages.try_lock().ok().map(|pages| pages
                    .get(&page.page_id())
                    .map(|record| (
                        record.descriptor.status,
                        record.is_closing,
                        record.physical_close_complete,
                        record.hidden_prerender
                    )))
            );
            page.evaluate("0").await.unwrap();
            tokio::time::sleep(Duration::from_millis(5)).await;
        }
        assert_eq!(
            page.evaluate("kept===document&&events.length===0")
                .await
                .unwrap(),
            "true"
        );
        let downloads = context.downloads();
        assert_eq!(downloads.len(), 1);
        assert_eq!(
            context.release_download(downloads[0].id).unwrap(),
            vec![0, 255, 9]
        );
        page.close().await.unwrap();
    }

