    #[cfg(all(unix, feature = "v8-host", feature = "in-process-probe"))]
    #[tokio::test(flavor = "current_thread")]
    async fn blob_anchor_download_uses_registered_binary_bytes_and_retains_document() {
        let mut options = ContextOptions::default();
        options.action_policy.rules.insert(
            ConsequentialAction::Download,
            crate::security::PolicyRule::Allow,
        );
        let context = Browser::in_process_probe().new_context_with_options(options);
        let page = context.new_page();
        page.load_html("https://download.test/source","<a id=download download=blob.bin>Download</a><script>globalThis.kept=document;globalThis.blobUrl=URL.createObjectURL(new Blob([new Uint8Array([0,255,128,1])],{type:'application/octet-stream'}));document.getElementById('download').href=blobUrl+'#ignored'</script>").await.unwrap();
        page.evaluate("document.getElementById('download').click()")
            .await
            .unwrap();
        assert_eq!(page.evaluate("kept===document").await.unwrap(), "true");
        assert_eq!(
            page.evaluate("location.href").await.unwrap(),
            "https://download.test/source"
        );
        let deadline = Instant::now() + Duration::from_secs(5);
        while context.downloads().is_empty() {
            assert!(
                Instant::now() < deadline,
                "native blob quarantine publication must complete"
            );
            page.evaluate("0").await.unwrap();
            tokio::time::sleep(Duration::from_millis(5)).await;
        }
        assert_eq!(page.evaluate("kept===document").await.unwrap(), "true");
        assert_eq!(
            page.evaluate("location.href").await.unwrap(),
            "https://download.test/source"
        );
        let downloads = context.downloads();
        assert_eq!(downloads.len(), 1);
        assert_eq!(downloads[0].suggested_filename, "blob.bin");
        assert_eq!(downloads[0].media_type, "application/octet-stream");
        assert_eq!(
            context.release_download(downloads[0].id).unwrap(),
            vec![0, 255, 128, 1]
        );
        page.evaluate("URL.revokeObjectURL(blobUrl)").await.unwrap();
        page.close().await.unwrap();
    }

