    #[cfg(feature = "v8-host")]
    #[test]
    fn joint_controlled_publication_waits_for_exact_ack_without_republishing_prefix() {
        use crate::navigation_control::{
            NavigationCommand, NavigationControl, NavigationEmitter, NavigationPhase,
            NavigationRequest, NavigationStop, PageLoadStrategy, PendingNavigationAck,
        };
        for reject in [false, true] {
            let control = NavigationControl::default();
            let job = control
                .begin(NavigationRequest {
                    command: NavigationCommand::Back,
                    strategy: PageLoadStrategy::Normal,
                    timeout_ms: Some(5000),
                })
                .unwrap();
            job.started().unwrap();
            job.committed(7, "https://joint.test/".into()).unwrap();
            let emitter = NavigationEmitter::Local(job.clone());
            let ack = PendingNavigationAck::test_pending();
            let mut publication = JointNavigationPublication {
                terminal: true,
                result: Ok(NavigationResult {
                    page_id: PageId(230),
                    requested_url: "https://joint.test/".into(),
                    final_url: "https://joint.test/".into(),
                    title: String::new(),
                    status: 200,
                    document_generation: 7,
                    revision: Revision(1),
                    lifecycle: Vec::new(),
                    challenge: ChallengeAssessment::default(),
                }),
                phase: 0,
                acknowledgement: Some(ack.clone()),
            };
            assert!(publication.poll(&emitter).is_pending());
            assert!(publication.poll(&emitter).is_pending());
            assert_eq!(publication.phase, 0);
            assert_eq!(job.progress().unwrap().phase, NavigationPhase::Committed);
            ack.test_finish(if reject {
                Err(NavigationStop::Failed("parent rejected commit".into()))
            } else {
                Ok(())
            });
            if reject {
                assert!(matches!(
                    publication.poll(&emitter),
                    std::task::Poll::Ready(Err(RuntimeError::Network(_)))
                ));
                assert_eq!(publication.phase, 0);
                assert_eq!(job.progress().unwrap().phase, NavigationPhase::Committed);
            } else {
                assert!(matches!(
                    publication.poll(&emitter),
                    std::task::Poll::Ready(Ok(()))
                ));
                assert_eq!(publication.phase, 3);
                assert_eq!(job.progress().unwrap().phase, NavigationPhase::Complete);
            }
        }
    }

    #[cfg(feature = "v8-host")]
    #[test]
    fn joint_eager_reply_waits_for_interactive_ack_and_retains_final_load_custody() {
        use crate::navigation_control::{
            NavigationCommand, NavigationControl, NavigationEmitter, NavigationPhase,
            NavigationRequest, PageLoadStrategy, PendingNavigationAck,
        };
        for eager in [false, true] {
            let mut page = PageState::new(
                PageId(233),
                None,
                BrowserConfig::default(),
                ContextOptions::default(),
                None,
                #[cfg(unix)]
                None,
            );
            page.bind_direct_fixture_terminal_owner();
            page.load_document(
                "https://joint.test/".into(),
                "<p>ready</p>",
                None,
                None,
                HistoryUpdate::Push,
                &BTreeMap::new(),
                Vec::new(),
            )
            .unwrap();
            settle_fixture_document(&mut page);
            let control = NavigationControl::default();
            let strategy = if eager {
                PageLoadStrategy::Eager
            } else {
                PageLoadStrategy::Normal
            };
            let job = control
                .begin(NavigationRequest {
                    command: NavigationCommand::Back,
                    strategy,
                    timeout_ms: Some(5000),
                })
                .unwrap();
            job.started().unwrap();
            job.committed(page.document_generation, page.url.clone())
                .unwrap();
            job.interactive(page.document_generation).unwrap();
            let emitter = NavigationEmitter::Local(job.clone());
            let mut timeline = oryn_js::joint_history::Timeline::default();
            let mut destination = page.history[0].navigation.clone().unwrap();
            timeline.attach("root".into(), destination.clone()).unwrap();
            destination.id = "selected".into();
            destination.document_id = "new-document".into();
            let plan = oryn_js::joint_history::Traversal {
                revision: timeline.revision(),
                from: timeline.cursor(),
                to: timeline.cursor(),
                destinations: vec![("root".into(), destination.clone())],
            };
            let receipt = timeline.begin_execution(&plan).unwrap();
            let ack = PendingNavigationAck::test_pending();
            let result = NavigationResult {
                page_id: page.page_id,
                requested_url: page.url.clone(),
                final_url: page.url.clone(),
                title: String::new(),
                status: 200,
                document_generation: page.document_generation,
                revision: Revision(page.revision),
                lifecycle: page.lifecycle.clone(),
                challenge: page.last_challenge.clone(),
            };
            let (reply, mut received) = oneshot::channel();
            let pending = PendingNavigationReply {
                joint_interactive_published: false,
                joint_eager_reply: eager,
                joint_checkpoint: None,
                joint_publication: Some(JointNavigationPublication {
                    terminal: false,
                    result: Ok(result.clone()),
                    phase: 1,
                    acknowledgement: Some(ack.clone()),
                }),
                joint: Some(receipt.clone()),
                generation: page.document_generation,
                load_epoch: None,
                identity: None,
                deadline: Instant::now() + Duration::from_secs(5),
                result,
                reply: NavigationReply::JointEvents(emitter, Some(reply)),
            };
            let pending = page.poll_joint_navigation_publication(pending).unwrap();
            assert!(matches!(
                received.try_recv(),
                Err(tokio::sync::oneshot::error::TryRecvError::Empty)
            ));
            ack.test_finish(Ok(()));
            let pending = page.poll_joint_navigation_publication(pending).unwrap();
            assert!(pending.joint_interactive_published);
            assert_eq!(job.progress().unwrap().phase, NavigationPhase::Interactive);
            assert!(!control.cleanup_is_drained().unwrap());
            if eager {
                assert!(received.try_recv().unwrap().is_ok());
            } else {
                assert!(matches!(
                    received.try_recv(),
                    Err(tokio::sync::oneshot::error::TryRecvError::Empty)
                ));
            }
            assert_eq!(receipt.poll(), None);
            timeline.record_commit("root", &destination.id);
            timeline.record_interactive("root", &destination.id);
            timeline.record_publication("root", &destination.id);
            assert_eq!(receipt.poll(), None);
            timeline.record_load("root", &destination.id);
            assert_eq!(receipt.poll(), Some(Ok(())));
            assert!(page.poll_navigation_reply(pending).is_none());
            assert_eq!(job.progress().unwrap().phase, NavigationPhase::Complete);
            assert!(control.cleanup_is_drained().unwrap());
            if !eager {
                assert!(received.try_recv().unwrap().is_ok());
            }
        }
    }

    #[cfg(feature = "v8-host")]
    #[test]
    fn joint_error_publication_retains_exact_terminal_ack() {
        use crate::navigation_control::{
            NavigationCommand, NavigationControl, NavigationEmitter, NavigationRequest,
            NavigationStop, PageLoadStrategy, PendingNavigationAck,
        };
        for reject in [false, true] {
            let control = NavigationControl::default();
            let job = control
                .begin(NavigationRequest {
                    command: NavigationCommand::Back,
                    strategy: PageLoadStrategy::Normal,
                    timeout_ms: Some(5000),
                })
                .unwrap();
            job.started().unwrap();
            let failure = NavigationStop::Failed("projection synchronization failed".into());
            job.stop(failure.clone()).unwrap();
            let emitter = NavigationEmitter::Local(job.clone());
            let ack = PendingNavigationAck::test_pending();
            let mut publication = JointNavigationPublication {
                terminal: true,
                result: Err(RuntimeError::Script(
                    "projection synchronization failed".into(),
                )),
                phase: 0,
                acknowledgement: Some(ack.clone()),
            };
            assert!(publication.poll(&emitter).is_pending());
            assert!(publication.poll(&emitter).is_pending());
            assert_eq!(publication.phase, 0);
            assert_eq!(job.progress().unwrap().stopped, Some(failure.clone()));
            ack.test_finish(if reject {
                Err(NavigationStop::Retired)
            } else {
                Ok(())
            });
            if reject {
                assert!(matches!(
                    publication.poll(&emitter),
                    std::task::Poll::Ready(Err(_))
                ));
                assert_eq!(publication.phase, 0);
            } else {
                assert!(matches!(
                    publication.poll(&emitter),
                    std::task::Poll::Ready(Ok(()))
                ));
                assert_eq!(publication.phase, 1);
            }
            assert_eq!(job.progress().unwrap().stopped, Some(failure));
        }
    }

    #[cfg(feature = "v8-host")]
    #[test]
    fn joint_history_reply_waits_for_selected_child_commit_and_cancels_on_deadline() {
        for timeout in [false, true] {
            let mut page = PageState::new(
                PageId(227),
                None,
                BrowserConfig::default(),
                ContextOptions::default(),
                None,
                #[cfg(unix)]
                None,
            );
            page.bind_direct_fixture_terminal_owner();
            page.load_document(
                "https://joint.test/root".into(),
                "<p>ready</p>",
                None,
                None,
                HistoryUpdate::Push,
                &BTreeMap::new(),
                Vec::new(),
            )
            .unwrap();
            let entry = page.history[page.history_index.unwrap()]
                .navigation
                .clone()
                .unwrap();
            let mut timeline = oryn_js::joint_history::Timeline::default();
            timeline.attach("root".into(), entry.clone()).unwrap();
            let mut child = entry.clone();
            child.id = "child-before".into();
            child.key = "child-before-key".into();
            child.document_id = "child-document".into();
            timeline.attach("child".into(), child.clone()).unwrap();
            child.id = "child-after".into();
            child.key = "child-after-key".into();
            timeline.push("child", child).unwrap();
            let plan = timeline.plan(-1).unwrap().unwrap();
            let receipt = timeline.begin_execution(&plan).unwrap();
            let retained = receipt.clone();
            let (reply, mut received) = oneshot::channel();
            let pending = page
                .dispatch_navigation_reply(reply, |page| {
                    Ok(NavigationProgress::Joint(
                        receipt,
                        NavigationResult {
                            page_id: page.page_id,
                            requested_url: page.url.clone(),
                            final_url: page.url.clone(),
                            title: String::new(),
                            status: 200,
                            document_generation: page.document_generation,
                            revision: Revision(page.revision),
                            lifecycle: page.lifecycle.clone(),
                            challenge: page.last_challenge.clone(),
                        },
                    ))
                })
                .unwrap();
            let mut pending = page
                .poll_navigation_reply(pending)
                .expect("root readiness cannot settle a child traversal");
            assert!(received.try_recv().is_err());
            if timeout {
                pending.deadline = Instant::now();
            } else {
                for (route, entry) in &plan.destinations {
                    timeline.record_commit(route, &entry.id);
                    timeline.record_publication(route, &entry.id);
                }
            }
            assert!(page.poll_navigation_reply(pending).is_none());
            let result = received.try_recv().unwrap();
            if timeout {
                assert!(matches!(result, Err(RuntimeError::Network(_))));
                assert_eq!(
                    retained.poll(),
                    Some(Err(oryn_js::joint_history::JointTraversalFailure::Canceled))
                );
            } else {
                assert_eq!(result.unwrap().final_url, "https://joint.test/root");
                assert_eq!(retained.poll(), Some(Ok(())));
            }
        }
    }

