    #[cfg(feature = "v8-host")]
    #[test]
    fn actor_mime_prefix_yields_and_preserves_incumbent_until_commit_or_cancel() {
        struct NoRefetch;
        impl NetworkBroker for NoRefetch {
            fn send(
                &self,
                _request: NetworkRequest,
            ) -> Result<NetworkResponse, crate::network::NetworkError> {
                panic!("prefix handoff must not refetch the response")
            }
        }
        for cancel in [false, true] {
            let broker = SharedNetworkBroker::new(NoRefetch);
            let mut page = PageState::new(
                PageId(232),
                None,
                BrowserConfig::default(),
                ContextOptions::default(),
                Some(broker.clone()),
                #[cfg(unix)]
                None,
            );
            page.bind_direct_fixture_terminal_owner();
            page.load_document(
                "https://mime.test/source".into(),
                "<p>source</p>",
                None,
                None,
                HistoryUpdate::Push,
                &BTreeMap::new(),
                Vec::new(),
            )
            .unwrap();
            let generation = page.document_generation;
            page.begin_navigation_resource(
                "https://mime.test/destination".into(),
                HistoryUpdate::Push,
                None,
                None,
                None,
                None,
            )
            .unwrap();
            let mut transaction = page.pending_navigation_transaction.take().unwrap();
            let (sender, events) = tokio::sync::mpsc::channel(4);
            let operation = crate::network::NetworkOperation {
                body_demand_pending: Default::default(),
                prefetched: Default::default(),
                request_id: 19,
                events,
                demand: None,
            };
            let response = navigation_http::Response {
                #[cfg(unix)]
                response_policy_cleanup: None,
                timing: oryn_js::navigation_timing::NavigationTiming::new(
                    Instant::now(),
                    oryn_js::navigation_timing::Kind::Navigate,
                ),
                request_state: NavigationRequestState {
                    initiator_url: Some(page.url.clone()),
                    opaque_initiator: false,
                    referrer: Some(page.url.clone()),
                    referrer_policy: "strict-origin-when-cross-origin".into(),
                },
                broker,
                current: Url::parse("https://mime.test/destination").unwrap(),
                post: None,
                cross_origin_redirect: false,
                headers: (200, Vec::new(), None, Instant::now(), Instant::now(), None),
            };
            transaction.phase = NavigationTransactionPhase::Mime {
                pending: crate::network::DocumentMimeSniff::new(operation, None, false),
                response,
            };
            assert!(
                page.step_navigation_transaction(&mut transaction)
                    .is_pending()
            );
            assert_eq!(page.document_generation, generation);
            assert_eq!(page.url, "https://mime.test/source");
            assert_eq!(
                page.executable.as_mut().unwrap().evaluate("1+2").unwrap(),
                "3"
            );
            if cancel {
                page.pending_navigation_transaction = Some(transaction);
                page.cancel_navigation_transaction(RuntimeError::NavigationCancelled);
                assert!(sender.is_closed());
                assert_eq!(page.document_generation, generation);
            } else {
                sender
                    .try_send(crate::network::NetworkEvent::Chunk {
                        request_id: 19,
                        bytes: bytes::Bytes::from_static(b"<title>Sniffed</title>"),
                    })
                    .unwrap();
                sender
                    .try_send(crate::network::NetworkEvent::Complete {
                        encoded_body_size: None,
                        request_id: 19,
                    })
                    .unwrap();
                let deadline = Instant::now() + Duration::from_secs(5);
                let completion = loop {
                    let progress = page.step_navigation_transaction(&mut transaction);
                    if progress.is_ready() {
                        break progress;
                    }
                    assert!(
                        Instant::now() < deadline,
                        "MIME admission must continue through departure and publication"
                    );
                    std::thread::yield_now();
                };
                assert!(matches!(completion, std::task::Poll::Ready(Ok(_))));
                assert_eq!(page.url, "https://mime.test/destination");
                assert_ne!(page.document_generation, generation);
            }
        }
    }

    #[cfg(feature = "v8-host")]
    #[test]
    fn deferred_navigation_reply_waits_for_parser_and_rejects_supersession() {
        for outcome in ["ready", "supersede", "stream-replacement", "timeout"] {
            let mut page = PageState::new(
                PageId(222),
                None,
                BrowserConfig::default(),
                ContextOptions::default(),
                None,
                #[cfg(unix)]
                None,
            );
            page.bind_direct_fixture_terminal_owner();
            let (reply, mut received) = oneshot::channel();
            let url = "data:text/html,%3Ctitle%3EReady%3C/title%3E";
            assert!(
                page.dispatch_navigation_reply(reply, |page| page.begin_browser_navigation(
                    url.into(),
                    HistoryUpdate::Push,
                    None,
                    None,
                    None
                ))
                .is_none()
            );
            let mut pending = loop {
                if let Some(pending) = page.poll_navigation_transaction() {
                    break pending;
                }
            };
            assert!(matches!(
                received.try_recv(),
                Err(tokio::sync::oneshot::error::TryRecvError::Empty)
            ));
            assert!(page.executable.as_ref().unwrap().parser_pending());
            if outcome == "stream-replacement" {
                page.executable
                    .as_mut()
                    .unwrap()
                    .execute("document.open();document.write('<title>Replacement stream</title>')")
                    .unwrap();
                pending.deadline = Instant::now();
                assert!(page.poll_navigation_reply(pending).is_none());
                assert!(matches!(
                    received.try_recv().unwrap(),
                    Err(RuntimeError::NavigationCancelled)
                ));
                page.executable
                    .as_mut()
                    .unwrap()
                    .execute("document.write('<p id=kept>live</p>');document.close()")
                    .unwrap();
                assert_eq!(
                    page.executable
                        .as_mut()
                        .unwrap()
                        .evaluate("document.getElementById('kept').textContent")
                        .unwrap(),
                    "live"
                );
            } else if outcome == "timeout" {
                pending.deadline = Instant::now();
                assert!(page.poll_navigation_reply(pending).is_none());
                assert!(matches!(
                    received.try_recv().unwrap(),
                    Err(RuntimeError::Network(_))
                ));
                assert!(!page.executable.as_ref().unwrap().parser_pending());
            } else if outcome == "supersede" {
                page.load_document(
                    "https://replacement.test/".into(),
                    "<title>Replacement</title>",
                    None,
                    None,
                    HistoryUpdate::Push,
                    &BTreeMap::new(),
                    Vec::new(),
                )
                .unwrap();
                assert!(page.poll_navigation_reply(pending).is_none());
                assert!(matches!(
                    received.try_recv().unwrap(),
                    Err(RuntimeError::NavigationCancelled)
                ));
            } else {
                let mut pending = Some(pending);
                for _ in 0..32 {
                    page.poll_page_tasks().unwrap();
                    pending = pending.and_then(|pending| page.poll_navigation_reply(pending));
                    if pending.is_none() {
                        break;
                    }
                }
                assert!(pending.is_none());
                let result = received.try_recv().unwrap().unwrap();
                assert_eq!(result.title, "Ready");
                assert_eq!(result.document_generation, page.document_generation);
            }
        }
    }

