    #[cfg(feature = "v8-host")]
    #[test]
    fn reload_and_uncached_history_keep_original_request_document_state() {
        struct Fixture(Arc<Mutex<Vec<NetworkRequest>>>);
        impl NetworkBroker for Fixture {
            fn send(&self, request: NetworkRequest) -> Result<NetworkResponse, NetworkError> {
                self.0.lock().unwrap().push(request.clone());
                Ok(NetworkResponse{response_policy: None,timing:None,request_id:request.request_id,status:200,
                headers:vec![("content-type".into(),"text/html".into()),("cache-control".into(),"no-store".into())],
                body:b"<!doctype html><script>globalThis.initialReferrer=document.referrer;globalThis.initialNavigationType=performance.getEntriesByType('navigation')[0].type;globalThis.initialTimeOrigin=performance.timeOrigin</script><body>history</body>".to_vec()})
            }
        }
        for reload in [false, true] {
            let requests = Arc::new(Mutex::new(Vec::new()));
            let mut page = PageState::new(
                PageId(299),
                None,
                BrowserConfig::default(),
                ContextOptions::default(),
                Some(SharedNetworkBroker::new(Fixture(requests.clone()))),
                #[cfg(unix)]
                None,
            );
            page.bind_direct_fixture_terminal_owner();
            page.navigate("https://a.test/original".into(), HistoryUpdate::Push)
                .unwrap();
            page.navigate("https://b.test/destination".into(), HistoryUpdate::Push)
                .unwrap();
            assert_eq!(
                page.executable
                    .as_mut()
                    .unwrap()
                    .evaluate("initialReferrer")
                    .unwrap(),
                "https://a.test/"
            );
            if reload {
                page.navigate("https://b.test/destination".into(), HistoryUpdate::Reload)
                    .unwrap();
            } else {
                // Exercise repopulation independently of cache admission policy.
                page.clear_cached_documents();
                page.traverse_history(-1).unwrap();
                page.navigate("https://b.test/replaced".into(), HistoryUpdate::Replace)
                    .unwrap();
                page.clear_cached_documents();
                page.traverse_history(1).unwrap();
            }
            assert_eq!(
                page.executable
                    .as_mut()
                    .unwrap()
                    .evaluate("initialNavigationType")
                    .unwrap(),
                if reload { "reload" } else { "back_forward" }
            );
            assert_eq!(page.executable.as_mut().unwrap().evaluate("String(initialTimeOrigin===performance.timeOrigin&&performance.getEntriesByType('navigation').length===1)").unwrap(),"true");
            let mut request = requests.lock().unwrap().last().unwrap().clone();
            assert_eq!(request.url, "https://b.test/destination");
            assert_eq!(
                request.security.initiator_url.as_deref(),
                Some("https://a.test/original")
            );
            crate::fetch_metadata::apply(&mut request).unwrap();
            assert!(
                request
                    .headers
                    .iter()
                    .any(|(name, value)| name.eq_ignore_ascii_case("sec-fetch-site")
                        && value == "cross-site")
            );
            assert!(
                request
                    .headers
                    .iter()
                    .any(|(name, value)| name.eq_ignore_ascii_case("referer")
                        && value == "https://a.test/")
            );
            assert_eq!(page.executable.as_mut().unwrap().evaluate("globalThis.__oryn_document_referrer='forged';initialReferrer+'|'+document.referrer").unwrap(),"https://a.test/|https://a.test/");
        }
    }

    #[cfg(feature = "v8-host")]
    #[test]
    fn native_fragment_history_uses_typed_trusted_events_and_stable_entries() {
        let mut page = PageState::new(
            PageId(201),
            None,
            BrowserConfig::default(),
            ContextOptions::default(),
            None,
            #[cfg(unix)]
            None,
        );
        page.bind_direct_fixture_terminal_owner();
        page.load_document(
            "https://history.test/page".into(),
            "<body></body>",
            None,
            None,
            HistoryUpdate::Push,
            &BTreeMap::new(),
            Vec::new(),
        )
        .unwrap();
        let generation = page.document_generation;
        page.executable.as_mut().unwrap().execute(r#"
            globalThis.events=[];const Hash=HashChangeEvent,Pop=PopStateEvent;
            onhashchange=e=>events.push(['hash',e instanceof Hash,e.isTrusted,e.oldURL,e.newURL]);
            document.body.onpopstate=e=>events.push(['pop',e instanceof Pop,e.isTrusted,e.state]);
            globalThis.Event=globalThis.HashChangeEvent=globalThis.PopStateEvent=function(){throw Error('author constructor')};
            globalThis.URL=function(){throw Error('author URL')};
            globalThis.dispatchEvent=function(){throw Error('author dispatcher')};
        "#).unwrap();
        page.navigate("https://history.test/page#one".into(), HistoryUpdate::Push)
            .unwrap();
        // Hash navigation fires trusted popstate before its hashchange task;
        // see pinned WPT history-traversal/event-order/after-load-hash.html.
        assert_eq!(
            page.executable
                .as_mut()
                .unwrap()
                .evaluate("JSON.stringify(events)")
                .unwrap(),
            r#"[["pop",true,true,null],["hash",true,true,"https://history.test/page","https://history.test/page#one"]]"#
        );
        let first = page.history[1].navigation.clone().unwrap();
        page.navigate("https://history.test/page#two".into(), HistoryUpdate::Push)
            .unwrap();
        assert_ne!(first.key, page.history[2].navigation.as_ref().unwrap().key);
        assert_eq!(
            first.document_id,
            page.history[2].navigation.as_ref().unwrap().document_id
        );
        assert_eq!(
            page.executable
                .as_mut()
                .unwrap()
                .evaluate("JSON.stringify(events)")
                .unwrap(),
            r#"[["pop",true,true,null],["hash",true,true,"https://history.test/page","https://history.test/page#one"],["pop",true,true,null],["hash",true,true,"https://history.test/page#one","https://history.test/page#two"]]"#
        );
        page.traverse_history(-1).unwrap();
        assert_eq!(page.document_generation, generation);
        assert_eq!(page.history_index, Some(1));
        assert_eq!(
            page.executable
                .as_mut()
                .unwrap()
                .evaluate("navigation.currentEntry.key")
                .unwrap(),
            first.key
        );
        assert_eq!(
            page.executable
                .as_mut()
                .unwrap()
                .evaluate("JSON.stringify(events)")
                .unwrap(),
            r#"[["pop",true,true,null],["hash",true,true,"https://history.test/page","https://history.test/page#one"],["pop",true,true,null],["hash",true,true,"https://history.test/page#one","https://history.test/page#two"],["pop",true,true,null],["hash",true,true,"https://history.test/page#two","https://history.test/page#one"]]"#
        );
    }

