    #[cfg(feature = "v8-host")]
    #[test]
    fn destination_scripts_inherit_the_committed_post_resource_after_redirect_rules() {
        type CapturedRequestBodies = Vec<(String, Vec<u8>)>;

        struct Response {
            redirect: bool,
            requests: Arc<Mutex<CapturedRequestBodies>>,
        }
        impl NetworkBroker for Response {
            fn send(
                &self,
                request: NetworkRequest,
            ) -> Result<NetworkResponse, crate::network::NetworkError> {
                self.requests
                    .lock()
                    .unwrap()
                    .push((request.method.clone(), request.body));
                if self.redirect && request.url.ends_with("/submitted") {
                    return Ok(NetworkResponse {
                        response_policy: None,
                        timing: None,
                        request_id: request.request_id,
                        status: 303,
                        headers: vec![("location".into(), "/final".into())],
                        body: Vec::new(),
                    });
                }
                Ok(NetworkResponse {
                    response_policy: None,
                    timing: None,
                    request_id: request.request_id,
                    status: 200,
                    headers: vec![("content-type".into(), "text/html".into())],
                    body: b"<script>history.pushState({saved:true},'', '/next')</script>".to_vec(),
                })
            }
        }
        for redirect in [false, true] {
            let requests = Arc::new(Mutex::new(Vec::new()));
            let mut page = PageState::new(
                PageId(229),
                None,
                BrowserConfig::default(),
                ContextOptions::default(),
                Some(SharedNetworkBroker::new(Response {
                    redirect,
                    requests: requests.clone(),
                })),
                #[cfg(unix)]
                None,
            );
            page.bind_direct_fixture_terminal_owner();
            let post = oryn_js::navigation::PostResource {
                bytes: b"field=original".to_vec(),
                content_type: "application/x-www-form-urlencoded".into(),
            };
            page.navigate_browser_resource(
                "https://history.test/submitted".into(),
                HistoryUpdate::Push,
                Some(post.clone()),
                None,
                None,
            )
            .unwrap();
            assert_eq!(page.history.len(), 2);
            assert_eq!(page.history_index, Some(1));
            for entry in &page.history {
                assert_eq!(entry.post, if redirect { None } else { Some(post.clone()) });
            }
            let requests = requests.lock().unwrap();
            assert_eq!(requests[0], ("POST".into(), post.bytes.clone()));
            if redirect {
                assert_eq!(requests.len(), 2);
                assert_eq!(requests[1], ("GET".into(), Vec::new()));
            } else {
                assert_eq!(requests.len(), 1);
            }
        }
    }

