    #[cfg(feature = "v8-host")]
    #[test]
    fn preserved_history_resolves_native_identity_after_index_changes() {
        let mut page = PageState::new(
            PageId(227),
            None,
            BrowserConfig::default(),
            ContextOptions::default(),
            None,
            #[cfg(unix)]
            None,
        );
        let (entries, index) = page
            .prepare_navigation_history("https://history.test/first", HistoryUpdate::Push, 1)
            .unwrap();
        page.history = entries;
        page.history_index = Some(index);
        let expected = page.history[0].navigation.clone().unwrap();
        let (entries, index) = page
            .prepare_navigation_history("https://history.test/second", HistoryUpdate::Push, 2)
            .unwrap();
        page.history = entries;
        page.history_index = Some(index);
        page.script_navigation_destination = Some(expected.clone());
        page.history.swap(0, 1);
        let (prepared, index) = page
            .prepare_navigation_history(
                "https://history.test/redirected",
                HistoryUpdate::Preserve(0),
                3,
            )
            .unwrap();
        assert_eq!(index, 1);
        assert_eq!(prepared[index].navigation.as_ref().unwrap().id, expected.id);
        assert_eq!(
            prepared[index].navigation.as_ref().unwrap().document_id,
            expected.document_id
        );
        assert_eq!(prepared[0].url, "https://history.test/second");
        let retained = page.history[1].clone();
        page.history.push(retained);
        assert!(matches!(
            page.resolve_history_target(0, Some(&expected)),
            Err(RuntimeError::ProtocolViolation(_))
        ));
        page.history.pop();
        page.history.remove(1);
        assert!(matches!(
            page.prepare_navigation_history(
                "https://history.test/first",
                HistoryUpdate::Preserve(0),
                4
            ),
            Err(RuntimeError::NavigationCancelled)
        ));
    }

    #[cfg(feature = "v8-host")]
    #[test]
    fn hidden_cross_origin_history_task_restores_cached_document_through_actor() {
        let mut page = PageState::new(
            PageId(994),
            None,
            BrowserConfig::default(),
            ContextOptions::default(),
            None,
            #[cfg(unix)]
            None,
        );
        page.bind_direct_fixture_terminal_owner();
        page.load_document(
            "https://first.test/".into(),
            "<p>first</p>",
            None,
            None,
            HistoryUpdate::Push,
            &BTreeMap::new(),
            Vec::new(),
        )
        .unwrap();
        page.executable
            .as_mut()
            .unwrap()
            .execute("globalThis.cachedDocument=document")
            .unwrap();
        let destination = page.history[0].navigation.clone().unwrap();
        page.load_document(
            "https://second.test/".into(),
            "<p>second</p>",
            None,
            None,
            HistoryUpdate::Push,
            &BTreeMap::new(),
            Vec::new(),
        )
        .unwrap();
        assert_eq!(
            page.executable
                .as_mut()
                .unwrap()
                .evaluate("navigation.entries().length")
                .unwrap(),
            "1"
        );
        page.executable
            .as_mut()
            .unwrap()
            .execute("history.back()")
            .unwrap();
        let task = page
            .executable
            .as_ref()
            .unwrap()
            .take_history_traversal()
            .unwrap()
            .unwrap();
        assert!(
            page.begin_queued_history_navigation(task)
                .unwrap()
                .is_none()
        );
        let request = page
            .executable
            .as_ref()
            .unwrap()
            .take_location_navigation()
            .unwrap();
        assert_eq!(
            request.navigation_destination.as_ref().unwrap().id,
            destination.id
        );
        let (reply, mut received) = oneshot::channel();
        let mut transaction_id = None;
        assert!(
            page.dispatch_navigation_reply(reply, |page| {
                let progress = page.begin_script_navigation(request, HistoryUpdate::Push)?;
                let NavigationProgress::Pending(id) = &progress else {
                    panic!("cached traversal must enter the retained actor transaction");
                };
                transaction_id = Some(*id);
                Ok(progress)
            })
            .is_none()
        );
        assert_eq!(page.url, "https://second.test/");
        assert!(matches!(
            received.try_recv(),
            Err(tokio::sync::oneshot::error::TryRecvError::Empty)
        ));
        let deadline = Instant::now() + Duration::from_secs(3);
        let mut readiness = None;
        let result = loop {
            if let Some(transaction) = page.pending_navigation_transaction.as_ref() {
                assert_eq!(Some(transaction.id), transaction_id);
            }
            // Use the same actor phases as the synchronous source adapter:
            // transaction, page tasks, then any retained load-completion reply.
            if let Some(pending) = page.poll_navigation_transaction() {
                assert!(readiness.replace(pending).is_none());
            }
            page.poll_page_tasks().unwrap();
            if let Some(pending) = page.pending_committed_navigation_reply.take() {
                assert!(readiness.replace(pending).is_none());
            }
            if let Some(pending) = readiness.take() {
                readiness = page.poll_navigation_reply(pending);
            }
            match received.try_recv() {
                Ok(result) => break result.unwrap(),
                Err(tokio::sync::oneshot::error::TryRecvError::Empty) => {}
                Err(error) => panic!("cached traversal reply lost: {error}"),
            }
            assert!(
                Instant::now() < deadline,
                "cached traversal actor transaction timed out"
            );
            std::thread::park_timeout(Duration::from_millis(1));
        };
        assert!(page.pending_navigation_transaction.is_none());
        assert!(page.settling_navigation.is_none());
        assert!(readiness.is_none());
        assert_eq!(result.final_url, "https://first.test/");
        assert_eq!(page.history_index, Some(0));
        assert_eq!(
            page.history[0].navigation.as_ref().unwrap().id,
            destination.id
        );
        assert_eq!(page.url, "https://first.test/");
        assert_eq!(
            page.executable
                .as_mut()
                .unwrap()
                .evaluate("cachedDocument===document")
                .unwrap(),
            "true"
        );
    }
