    #[cfg(all(unix, feature = "v8-host"))]
    #[test]
    fn failed_cached_parent_commit_restores_uncacheable_incumbent_without_reviving_input() {
        use std::io::{BufRead, Write};
        struct Input(std::rc::Rc<std::cell::Cell<bool>>);
        impl crate::host::DocumentInput for Input {
            fn poll_next(
                &mut self,
            ) -> std::task::Poll<Option<Result<String, crate::host::HostError>>> {
                panic!("unfinished input must not be polled by restoration")
            }
        }
        impl Drop for Input {
            fn drop(&mut self) {
                self.0.set(true);
            }
        }
        let mut page = PageState::new(
            PageId(196),
            None,
            BrowserConfig::default(),
            ContextOptions::default(),
            None,
            None,
        );
        page.bind_direct_fixture_terminal_owner();
        page.load_document(
            "https://history.test/one".into(),
            "<p>cached</p>",
            None,
            None,
            HistoryUpdate::Push,
            &BTreeMap::new(),
            Vec::new(),
        )
        .unwrap();
        assert!(!page.executable.as_ref().unwrap().uses_shared_agent_host());
        page.suspend_current_document().unwrap();
        assert!(page.back_forward_cache[&0].executable.has_agent_host());
        let resources = unfinished_history_resources(&mut page, "https://history.test/two");
        let dropped = std::rc::Rc::new(std::cell::Cell::new(false));
        let stream = crate::host::DocumentStream {
            content_language: None,
            chunks: Box::new(Input(dropped.clone())),
            content_type: None,
            encoding: Default::default(),
        };
        let mut executable = crate::executable::RustExecutableDocument::load_stream_with_limits(
            stream,
            &resources,
            None,
            Some(Url::parse("https://history.test/two").unwrap()),
            256 * 1024 * 1024,
            true,
        )
        .unwrap();
        executable.execute("globalThis.transitions=[];onpagehide=e=>transitions.push('hide:'+e.persisted);onpageshow=e=>transitions.push('show:'+e.persisted)").unwrap();
        page.document = Some(executable.document.clone());
        // This fixture installs the unfinished driver directly. Match normal
        // installation's projection reset so departure does not try to read
        // controls belonging to the previously parked document.
        page.semantic_graph
            .reset(&executable.document.dom, page.document_generation);
        page.semantic_graph
            .set_frame_ids(executable.semantic_frame_ids());
        page.semantic_publication_pending = true;
        page.executable = Some(executable);
        page.lifecycle = vec![LifecycleState::Commit];
        page.sync_executable_semantics()
            .expect("unfinished incumbent projection is valid before parent commit injection");
        let (client, mut server) = std::os::unix::net::UnixStream::pair().unwrap();
        server
            .set_read_timeout(Some(Duration::from_secs(5)))
            .unwrap();
        server
            .set_write_timeout(Some(Duration::from_secs(5)))
            .unwrap();
        let peer = std::thread::spawn(move || {
            let mut reader = std::io::BufReader::new(server.try_clone().unwrap());
            for (index, url) in ["https://history.test/one", "https://history.test/two"]
                .into_iter()
                .enumerate()
            {
                let mut line = String::new();
                let read = reader.read_line(&mut line).unwrap_or_else(|error| {
                    panic!("expected CommitPage #{index} for {url}: {error}")
                });
                assert!(
                    read > 0,
                    "transport ended before CommitPage #{index} for {url}"
                );
                let request: serde_json::Value = serde_json::from_str(&line).unwrap();
                let command: crate::context_service::ContextServiceRequest =
                    serde_json::from_value(request["request"].clone()).unwrap();
                assert!(
                    matches!(command,crate::context_service::ContextServiceRequest::CommitPage{url:actual,..} if actual==url)
                );
                let response = serde_json::json!({"protocol_version":request["protocol_version"],"route":request["route"],
                    "correlation_id":request["message_id"],
                    "response":if index==0{serde_json::Value::Null}else{serde_json::to_value(crate::context_service::ContextServiceResponse::PageCommitted).unwrap()},
                    "error":if index==0{Some("fixture parent commit failure")}else{None}});
                serde_json::to_writer(&mut server, &response).unwrap();
                server.write_all(b"\n").unwrap();
                server.flush().unwrap();
                // Valid error envelopes are acknowledged too. Consume the
                // correlated receipt before reading the rollback request.
                let mut receipt = String::new();
                assert!(reader.read_line(&mut receipt).unwrap() > 0);
                assert_eq!(
                    serde_json::from_str::<serde_json::Value>(&receipt).unwrap(),
                    serde_json::json!({
                        "protocol_version": request["protocol_version"],
                        "route": request["route"],
                        "received_id": request["message_id"],
                        "accepted": true,
                    }),
                    "correlated acknowledgement for CommitPage #{index}"
                );
            }
        });
        page.context_client = Some(crate::context_service::SharedContextClient::new(
            crate::context_service::IpcContextClient::new(client),
        ));
        assert!(
            !page.has_shared_root_driver(),
            "late parent commit transport must not change native isolate ownership"
        );
        let failure = page
            .restore_cached_document(0, "https://history.test/one".into())
            .unwrap_err();
        assert!(
            failure
                .to_string()
                .contains("fixture parent commit failure"),
            "unexpected restoration failure before injected commit: {failure}"
        );
        let deadline = Instant::now() + Duration::from_secs(5);
        while page.failed_install_recovery.is_some() {
            page.poll_failed_install_recovery();
            assert!(
                Instant::now() < deadline,
                "retained parent rollback did not complete"
            );
            std::thread::park_timeout(Duration::from_millis(1));
        }
        peer.join().unwrap();
        finish_fixture_rollback_publication(&mut page);
        assert!(dropped.get());
        assert_eq!(page.history_index, Some(1));
        assert_eq!(page.url, "https://history.test/two");
        let executable = page.executable.as_mut().unwrap();
        assert!(!executable.parser_pending());
        assert!(!executable.document_load_complete());
        assert_eq!(
            executable.evaluate("transitions.join(',')").unwrap(),
            "hide:false,show:false"
        );
        assert!(!page.back_forward_cache.contains_key(&0));
        assert!(!page.back_forward_cache.contains_key(&1));
        assert!(page.has_retired_agent_documents());
    }

