        let load = |page: &mut PageState, name: &str, update| {
            page.load_document(
                format!("https://history.test/{name}"),
                "<p>document</p>",
                None,
                None,
                update,
                &BTreeMap::new(),
                Vec::new(),
            )
            .unwrap();
        };
        load(&mut page, "one", HistoryUpdate::Push);
        load(&mut page, "two", HistoryUpdate::Push);
        load(&mut page, "three", HistoryUpdate::Push);
        let high_water = page.last_issued_document_generation;
        page.traverse_history(-1).unwrap();
        page.traverse_history(-1).unwrap();
        assert!(page.back_forward_cache.contains_key(&1));
        assert!(page.back_forward_cache.contains_key(&2));
        load(&mut page, "branch", HistoryUpdate::Push);
