    #[cfg(feature = "v8-host")]
    #[tokio::test(flavor = "current_thread")]
    async fn observation_traffic_does_not_starve_native_timer_tasks() {
        let page = Browser::in_process_with_config(BrowserConfig::default())
            .new_context()
            .new_page();
        page.load_html("https://scheduler.test/", "<button>Waiting</button>")
            .await
            .unwrap();
        let (started, observing) = tokio::sync::oneshot::channel();
        let observed_page = page.clone();
        let mut traffic = tokio::spawn(async move {
            let mut started = Some(started);
            let mut observations = 0;
            loop {
                let snapshot = observed_page.observe().await.unwrap();
                observations += 1;
                if let Some(started) = started.take() {
                    assert!(snapshot.nodes.iter().any(|node| node.name == "Waiting"));
                    started.send(()).unwrap();
                }
                if snapshot.nodes.iter().any(|node| node.name == "Finished") {
                    break observations;
                }
                // Keep issuing commands without a delay that would allow an
                // empty command queue to conceal scheduler starvation.
                tokio::task::yield_now().await;
            }
        });
        observing.await.unwrap();
        page.evaluate("setTimeout(()=>document.querySelector('button').textContent='Finished',50)")
            .await
            .unwrap();
        let observations = match tokio::time::timeout(Duration::from_secs(2), &mut traffic).await {
            Ok(result) => result.unwrap(),
            Err(error) => {
                traffic.abort();
                panic!("native timer must run despite continuous observations: {error}");
            }
        };
        assert!(
            observations > 1,
            "exercise observation traffic before the timer"
        );
        page.close().await.unwrap();
    }

    #[cfg(feature = "v8-host")]
    #[tokio::test(flavor = "current_thread")]
    async fn same_url_without_fragment_loads_a_new_document() {
        struct Receipt(Arc<Mutex<usize>>);
        impl NetworkBroker for Receipt {
            fn send(
                &self,
                request: NetworkRequest,
            ) -> Result<NetworkResponse, crate::network::NetworkError> {
                *self.0.lock().unwrap() += 1;
                Ok(NetworkResponse {
                    response_policy: None,
                    timing: None,
                    request_id: request.request_id,
                    status: 200,
                    headers: vec![("content-type".into(), "text/html".into())],
                    body: br##"<a href='/receipt'>Reload receipt</a><a href='#'>Fragment</a>"##
                        .to_vec(),
                })
            }
        }
        let requests = Arc::new(Mutex::new(0));
        let context = Browser::in_process_with_config(BrowserConfig::default())
            .new_context_with_broker(
                ContextOptions::default(),
                SharedNetworkBroker::new(Receipt(requests.clone())),
            );
        let page = context.new_page();
        page.goto("https://forms.test/receipt").await.unwrap();
        // Both identical no-fragment URLs and removal of an existing fragment
        // require a network load. An empty fragment is still a fragment.
        for name in ["Reload receipt", "Fragment", "Reload receipt"] {
            let before = page.observe().await.unwrap();
            let names = before
                .nodes
                .iter()
                .take(8)
                .map(|node| repair44_diagnostic_prefix(&node.name))
                .collect::<Vec<_>>();
            eprintln!(
                "repair44 native29/124 {}",
                repair44_bounded_diagnostic(format_args!(
                    "target={name:?} url={:?} generation={} node_count={} names_first8={names:?}",
                    repair44_diagnostic_prefix(&before.page.url),
                    before.page.document_generation,
                    before.nodes.len()
                ))
            );
            let count = *requests.lock().unwrap();
            let target = before
                .nodes
                .iter()
                .find(|node| node.name == name)
                .unwrap()
                .semantic_ref;
            page.execute(NativeAction {
                target,
                action: SemanticAction::Click,
                value: None,
            })
            .await
            .unwrap();
            let reload = name == "Reload receipt";
            // Action completion admits navigation; network commit is retained
            // by the actor and can finish after the action reply.
            let after = tokio::time::timeout(Duration::from_secs(5), async {
                loop {
                    let after = page.observe().await.unwrap();
                    let committed = if reload {
                        after.page.document_generation != before.page.document_generation
                            && after.page.url == "https://forms.test/receipt"
                    } else {
                        after.page.url == "https://forms.test/receipt#"
                    };
                    // A new generation establishes commit, not parser
                    // completion. The next iteration acts on this document's
                    // links, so require both authored controls to be published.
                    if committed
                        && ["Reload receipt", "Fragment"]
                            .iter()
                            .all(|name| after.nodes.iter().any(|node| node.name == *name))
                    {
                        break after;
                    }
                    tokio::task::yield_now().await;
                }
            })
            .await
            .expect("accepted receipt navigation must commit");
            assert_eq!(*requests.lock().unwrap(), count + usize::from(reload));
            assert_eq!(
                before.page.document_generation != after.page.document_generation,
                reload
            );
        }
    }

