    #[cfg(feature = "v8-host")]
    #[tokio::test(flavor = "current_thread")]
    async fn evaluate_publishes_one_revision_for_one_semantic_dom_change() {
        let page = Browser::new().new_context().new_page();
        page.load_html(
            "https://example.test/evaluate-revision",
            "<button id=target aria-label=Pending></button>",
        )
        .await
        .expect("load evaluation fixture");
        let before = page.observe().await.expect("observe initial state");

        assert_eq!(
            page.evaluate(
                "document.querySelector('#target').setAttribute('aria-label','Ready'); 'done'",
            )
            .await
            .expect("evaluate mutation"),
            "done"
        );

        let after = page.observe().await.expect("observe evaluated state");
        assert_eq!(after.revision, Revision(before.revision.0 + 1));
        let delta = page
            .observe_delta(before.revision)
            .await
            .expect("observe evaluated delta");
        assert_eq!(delta.from_revision, before.revision);
        assert_eq!(delta.to_revision, after.revision);
        assert!(delta.upserted.iter().any(|node| {
            node.semantic_ref
                == before
                    .nodes
                    .iter()
                    .find(|node| node.name == "Pending")
                    .expect("initial target")
                    .semantic_ref
                && node.name == "Ready"
        }));

        page.evaluate("'no mutation'")
            .await
            .expect("evaluate no-op");
        assert_eq!(
            page.observe().await.expect("observe after no-op").revision,
            after.revision,
            "an evaluation without an observable DOM change must not mint a revision"
        );
    }

    #[cfg(feature = "v8-host")]
    #[tokio::test(flavor = "current_thread")]
    async fn wait_task_drain_publishes_one_revision_and_one_delta() {
        let page = Browser::new().new_context().new_page();
        page.load_html(
            "https://example.test/wait-revision",
            "<button id=pending aria-label=Pending></button>",
        )
        .await
        .expect("load delayed mutation fixture");
        let before = page.observe().await.expect("observe pending state");
        let target = before
            .nodes
            .iter()
            .find(|node| node.name == "Pending")
            .expect("pending target")
            .semantic_ref;

        // Capture the initial revision before starting the timer: loading and
        // observing can take longer than the delay on a busy test machine.
        page.evaluate(
            r#"setTimeout(() => {
                const target = document.querySelector('#pending');
                target.id = 'ready';
                target.setAttribute('aria-label', 'Ready');
            }, 25); 'scheduled'"#,
        )
        .await
        .expect("schedule delayed mutation");

        page.wait_for(WaitPredicate::SelectorExists("#ready".into()))
            .await
            .expect("drain delayed task");

        let after = page.observe().await.expect("observe ready state");
        assert_eq!(after.revision, Revision(before.revision.0 + 1));
        let delta = page
            .observe_delta(before.revision)
            .await
            .expect("observe asynchronous delta");
        assert_eq!(delta.to_revision, after.revision);
        assert!(
            delta
                .upserted
                .iter()
                .any(|node| node.semantic_ref == target && node.name == "Ready")
        );

        page.wait_for(WaitPredicate::SelectorExists("#ready".into()))
            .await
            .expect("already-satisfied wait");
        assert_eq!(
            page.observe()
                .await
                .expect("observe after repeated wait")
                .revision,
            after.revision,
            "an already-satisfied wait must not publish the same task change twice"
        );
    }

    #[cfg(feature = "v8-host")]
    #[tokio::test(flavor = "current_thread")]
    async fn history_state_url_changes_keep_the_document_and_do_not_fetch() {
        struct HistoryNavigationFixture(Arc<Mutex<Vec<String>>>);
        impl NetworkBroker for HistoryNavigationFixture {
            fn send(
                &self,
                request: NetworkRequest,
            ) -> Result<NetworkResponse, crate::network::NetworkError> {
                self.0.lock().unwrap().push(request.url.clone());
                Ok(NetworkResponse {
                    response_policy: None,
                    timing: None,
                    request_id: request.request_id,
                    status: if request.url.ends_with("/start") {
                        200
                    } else {
                        404
                    },
                    headers: vec![("content-type".into(), "text/html".into())],
                    body: b"<!doctype html><p id=marker>original</p>".to_vec(),
                })
            }
        }
        let requests = Arc::new(Mutex::new(Vec::new()));
        let context = Browser::new().new_context_with_broker(
            ContextOptions::default(),
            SharedNetworkBroker::new(HistoryNavigationFixture(requests.clone())),
        );
        for method in ["pushState", "replaceState"] {
            let page = context.new_page();
            page.goto("https://history.example.test/start")
                .await
                .unwrap();
            page.evaluate("globalThis.originalMarker=document.getElementById('marker');'ready'")
                .await
                .unwrap();
            page.evaluate(format!(
                "history.{method}({{key:7}},'', '/changed');'changed'"
            ))
            .await
            .unwrap();
            assert_eq!(page.evaluate("[location.pathname,history.state.key,document.getElementById('marker')===originalMarker].join('|')").await.unwrap(), "/changed|7|true");
            page.evaluate("history.pushState({key:8},'', '/later');history.back();'back'")
                .await
                .unwrap();
            assert_eq!(page.evaluate("[location.pathname,history.state.key,document.getElementById('marker')===originalMarker].join('|')").await.unwrap(), "/changed|7|true");
            page.evaluate("location.href='/destination';'requested'")
                .await
                .unwrap();
            // A script evaluation reply precedes asynchronous destination
            // commit. The old global disappears at that commit, not admission.
            page.wait_for(WaitPredicate::UrlContains(
                "https://history.example.test/destination".into(),
            ))
            .await
            .unwrap();
            page.wait_for(WaitPredicate::Lifecycle(LifecycleState::Load))
                .await
                .unwrap();
            assert_eq!(
                page.evaluate("typeof originalMarker").await.unwrap(),
                "undefined"
            );
        }
        assert_eq!(
            *requests.lock().unwrap(),
            [
                "https://history.example.test/start",
                "https://history.example.test/destination",
                "https://history.example.test/start",
                "https://history.example.test/destination"
            ]
        );
    }

    #[cfg(feature = "v8-host")]
    #[tokio::test(flavor = "current_thread")]
    async fn form_post_navigation_preserves_owned_body_and_redirect_semantics() {
        struct Echo(Arc<Mutex<Vec<NetworkRequest>>>);
        impl NetworkBroker for Echo {
            fn send(
                &self,
                request: NetworkRequest,
            ) -> Result<NetworkResponse, crate::network::NetworkError> {
                let url = Url::parse(&request.url).unwrap();
                let status = url
                    .path()
                    .strip_prefix("/redirect/")
                    .and_then(|s| s.parse::<u16>().ok())
                    .unwrap_or(200);
                let mut headers = vec![("content-type".into(), "text/html".into())];
                if status != 200 {
                    headers.push(("location".into(), "/echo".into()));
                }
                let response = NetworkResponse {
                    response_policy: None,
                    timing: None,
                    request_id: request.request_id,
                    status,
                    headers,
                    body: b"<!doctype html><p>accepted</p>".to_vec(),
                };
                self.0.lock().unwrap().push(request);
                Ok(response)
            }
        }
        let requests = Arc::new(Mutex::new(Vec::new()));
        let mut options = ContextOptions::default();
        options.action_policy.rules.insert(
            ConsequentialAction::FormSubmission,
            crate::security::PolicyRule::Allow,
        );
        let context = Browser::in_process_with_config(BrowserConfig::default())
            .new_context_with_broker(options, SharedNetworkBroker::new(Echo(requests.clone())));
        for status in [200, 301, 302, 303, 307, 308] {
            let page = context.new_page();
            let path = if status == 200 {
                "/echo".into()
            } else {
                format!("/redirect/{status}")
            };
            page.load_html(
                "https://forms.test/start",
                &format!(
                    "<form id=f method=post action='{path}'><input name=x value=owned></form>"
                ),
            )
            .await
            .unwrap();
            page.evaluate("f.requestSubmit();'submitted'")
                .await
                .unwrap();
            // Evaluation admits navigation; await this destination's commit and
            // load before inspecting its complete redirect exchange.
            page.wait_for(WaitPredicate::UrlContains("https://forms.test/echo".into()))
                .await
                .unwrap();
            page.wait_for(WaitPredicate::Lifecycle(LifecycleState::Load))
                .await
                .unwrap();
            let sent = std::mem::take(&mut *requests.lock().unwrap());
            assert_eq!(sent.len(), if status == 200 { 1 } else { 2 }, "{status}");
            assert_eq!(sent[0].method, "POST");
            assert_eq!(sent[0].body, b"x=owned");
            assert!(
                sent[0]
                    .headers
                    .iter()
                    .any(|(name, value)| name == "content-type"
                        && value == "application/x-www-form-urlencoded")
            );
            if status != 200 {
                let preserves = matches!(status, 307 | 308);
                assert_eq!(sent[1].method, if preserves { "POST" } else { "GET" });
                assert_eq!(
                    sent[1].body.as_slice(),
                    if preserves { &b"x=owned"[..] } else { &[] }
                );
                assert_eq!(
                    sent[1]
                        .headers
                        .iter()
                        .any(|(name, _)| name == "content-type"),
                    preserves
                );
            }
            if status == 200 {
                page.refresh().await.unwrap();
                let repeated = std::mem::take(&mut *requests.lock().unwrap());
                assert_eq!(repeated.len(), 1);
                assert_eq!(repeated[0].method, "POST");
                assert_eq!(repeated[0].body, b"x=owned");
            }
            page.close().await.unwrap();
        }
    }

    #[cfg(feature = "v8-host")]
    #[tokio::test(flavor = "current_thread")]
    async fn evaluated_navigation_admission_precedes_held_response_and_document_commit() {
        struct Release(Arc<(Mutex<bool>, std::sync::Condvar)>);
        impl Drop for Release {
            fn drop(&mut self) {
                let (lock, wake) = &*self.0;
                *lock.lock().unwrap_or_else(|error| error.into_inner()) = true;
                wake.notify_all();
            }
        }
        struct HeldResponse {
            gate: Arc<(Mutex<bool>, std::sync::Condvar)>,
            requests: Arc<Mutex<Vec<NetworkRequest>>>,
            started: std::sync::mpsc::Sender<()>,
        }
        impl NetworkBroker for HeldResponse {
            fn send(
                &self,
                request: NetworkRequest,
            ) -> Result<NetworkResponse, crate::network::NetworkError> {
                let request_id = request.request_id;
                self.requests.lock().unwrap().push(request);
                let _ = self.started.send(());
                let (lock, wake) = &*self.gate;
                let released = lock.lock().unwrap();
                let (released, timeout) = wake
                    .wait_timeout_while(released, Duration::from_secs(10), |released| !*released)
                    .unwrap();
                assert!(
                    *released && !timeout.timed_out(),
                    "fixture response gate was not released"
                );
                Ok(NetworkResponse {
                    response_policy: None,
                    timing: None,
                    request_id,
                    status: 200,
                    headers: vec![("content-type".into(), "text/html".into())],
                    body: b"<!doctype html><p id=committed>destination</p>".to_vec(),
                })
            }
        }
        for submit in [false, true] {
            let gate = Arc::new((Mutex::new(false), std::sync::Condvar::new()));
            let requests = Arc::new(Mutex::new(Vec::new()));
            let (started, receive) = std::sync::mpsc::channel();
            let mut options = ContextOptions::default();
            options
                .action_policy
                .rules
                .insert(ConsequentialAction::FormSubmission, PolicyRule::Allow);
            let context = Browser::in_process_with_config(BrowserConfig::default())
                .new_context_with_broker(
                    options,
                    SharedNetworkBroker::new(HeldResponse {
                        gate: gate.clone(),
                        requests: requests.clone(),
                        started,
                    }),
                );
            let page = context.new_page();
            page.load_html("https://admission.test/source", "<!doctype html><form id=f method=post action=/destination><input name=x value=owned></form>")
                .await.unwrap();
            page.evaluate("globalThis.originalMarker=document;'ready'")
                .await
                .unwrap();
            // Declare after page/context so unwinding opens the gate before
            // their teardown; the broker also has a bounded fallback wait.
            let release = Release(gate.clone());
            let script = if submit {
                "f.requestSubmit();'admitted'"
            } else {
                "location.href='/destination';'admitted'"
            };
            assert_eq!(
                tokio::time::timeout(Duration::from_secs(5), page.evaluate(script))
                    .await
                    .expect("evaluation must not wait for the held response")
                    .unwrap(),
                "admitted"
            );
            tokio::task::spawn_blocking(move || {
                receive.recv_timeout(Duration::from_secs(5)).unwrap()
            })
            .await
            .unwrap();
            assert!(!*gate.0.lock().unwrap());
            {
                let sent = requests.lock().unwrap();
                assert_eq!(sent.len(), 1);
                assert_eq!(sent[0].url, "https://admission.test/destination");
                assert_eq!(sent[0].method, if submit { "POST" } else { "GET" });
                assert_eq!(
                    sent[0].body.as_slice(),
                    if submit { &b"x=owned"[..] } else { &[] }
                );
            }
            drop(release);
            page.wait_for(WaitPredicate::UrlContains(
                "https://admission.test/destination".into(),
            ))
            .await
            .unwrap();
            page.wait_for(WaitPredicate::Lifecycle(LifecycleState::Load))
                .await
                .unwrap();
            assert_eq!(
                page.evaluate(
                    "document.getElementById('committed').textContent+'|'+typeof originalMarker"
                )
                .await
                .unwrap(),
                "destination|undefined"
            );
            assert_eq!(requests.lock().unwrap().len(), 1);
            page.close().await.unwrap();
        }
    }

    #[cfg(feature = "v8-host")]
    #[tokio::test(flavor = "current_thread")]
    async fn image_button_loads_intrinsic_svg_size_before_window_load() {
        struct Svg;
        impl NetworkBroker for Svg {
            fn send(
                &self,
                request: NetworkRequest,
            ) -> Result<NetworkResponse, crate::network::NetworkError> {
                assert_eq!(request.url, "https://images.test/map.svg");
                Ok(NetworkResponse {response_policy: None,timing:None, request_id:request.request_id, status:200,
                    headers:vec![("content-type".into(), "image/svg+xml".into())],
                    body: br#"<svg xmlns="http://www.w3.org/2000/svg" width="200" height="200"><rect width="100" height="100"/></svg>"#.to_vec() })
            }
        }
        let context = Browser::in_process_with_config(BrowserConfig::default())
            .new_context_with_broker(ContextOptions::default(), SharedNetworkBroker::new(Svg));
        let page = context.new_page();
        page.load_html("https://images.test/start", r#"<!doctype html><meta charset=utf-8>

        <form id=f>
          <input id=i type=image src=/map.svg>
        </form>

        <script>
            f.onsubmit=e=>{e.preventDefault();const data=new FormData(f,i);globalThis.coords=data.get('x')+','+data.get('y')};
            window.addEventListener('load',()=>{const r=i.getBoundingClientRect();globalThis.sizes=r.width+'|'+r.height;i.dispatchEvent(new MouseEvent('click',{clientX:Math.round((r.left+r.right)/7),clientY:Math.round((r.top+r.bottom)/4)}))});
        </script>"#).await.unwrap();
        // load_html commits the document without blocking the actor on image
        // I/O. This assertion examines values produced by the load handler,
        // so synchronize with that lifecycle event rather than thread timing.
        page.wait_for(WaitPredicate::Lifecycle(LifecycleState::Load))
            .await
            .unwrap();
        assert_eq!(
            page.evaluate("sizes+'|'+coords").await.unwrap(),
            "200|200|23,46"
        );
        let images = "<img src=/map.svg>".repeat(40);
        page.load_html("https://images.test/many", &format!("{images}<script>window.addEventListener('load',()=>{{globalThis.loadedImages=Array.from(document.images).filter(image=>image.naturalWidth===200).length}})</script>")).await.unwrap();
        page.wait_for(WaitPredicate::Lifecycle(LifecycleState::Load))
            .await
            .unwrap();
        assert_eq!(page.evaluate("loadedImages").await.unwrap(), "40");
        page.close().await.unwrap();
    }

    #[cfg(feature = "v8-host")]
    #[tokio::test(flavor = "current_thread")]
    async fn form_post_frame_and_popup_targets_do_not_fall_back_to_get() {
        struct Echo(Arc<Mutex<Vec<NetworkRequest>>>);
        impl NetworkBroker for Echo {
            fn send(
                &self,
                request: NetworkRequest,
            ) -> Result<NetworkResponse, crate::network::NetworkError> {
                let result = NetworkResponse {
                    response_policy: None,
                    timing: None,
                    request_id: request.request_id,
                    status: 200,
                    headers: vec![("content-type".into(), "text/html".into())],
                    body: b"<!doctype html><p>accepted</p>".to_vec(),
                };
                self.0.lock().unwrap().push(request);
                Ok(result)
            }
        }
        for (target, encoding) in [
            "result",
            "_blank",
            "parser-frame",
            "load-frame",
            "base-target",
        ]
        .into_iter()
        .flat_map(|target| {
            [
                "application/x-www-form-urlencoded",
                "text/plain",
                "multipart/form-data",
            ]
            .map(|encoding| (target, encoding))
        }) {
            let requests = Arc::new(Mutex::new(Vec::new()));
            let mut options = ContextOptions::default();
            options.action_policy.rules.insert(
                ConsequentialAction::FormSubmission,
                crate::security::PolicyRule::Allow,
            );
            options.action_policy.rules.insert(
                ConsequentialAction::Popup,
                crate::security::PolicyRule::Allow,
            );
            let context = Browser::in_process_with_config(BrowserConfig::default())
                .new_context_with_broker(options, SharedNetworkBroker::new(Echo(requests.clone())));
            let page = context.new_page();
            if matches!(target, "parser-frame" | "load-frame") {
                let start = if target == "load-frame" {
                    "addEventListener('load',()=>{Promise.resolve().then(()=>{"
                } else {
                    ""
                };
                let end = if target == "load-frame" { "})})" } else { "" };
                page.load_html("https://forms.test/start", &format!("<form id=f action=/echo><input name=x value=owned></form><script>{start}const frame=document.createElement('iframe');frame.name='result';document.body.appendChild(frame);f.method='post';f.target=frame.name;f.enctype='{encoding}';globalThis.loaded=[];frame.onload=()=>{{loaded.push(frame.contentDocument.body.textContent);f.remove()}};f.submit();{end}</script>")).await.unwrap();
                tokio::time::timeout(Duration::from_secs(5), async {
                    while page.evaluate("String(loaded.length)").await.unwrap() == "0" {
                        tokio::time::sleep(Duration::from_millis(10)).await;
                    }
                })
                .await
                .expect("submitted frame must publish its load");
                assert_eq!(
                    page.evaluate("JSON.stringify(loaded)").await.unwrap(),
                    r#"["accepted"]"#,
                    "initial blank load must not overtake the pending form navigation: {target}/{encoding}"
                );
            } else {
                page.load_html("https://forms.test/start", "<iframe name=result></iframe><form id=f action=/echo><input name=x value=owned></form>").await.unwrap();
                let set_target = if target == "base-target" {
                    "const base=document.createElement('base');base.target='result';document.head.append(base);".to_string()
                } else {
                    format!("f.target='{target}';")
                };
                page.evaluate(&format!("f.method='post';{set_target}f.encoding='{encoding}';f.requestSubmit();'submitted'"))
                    .await
                    .unwrap();
            }
            tokio::time::timeout(Duration::from_secs(5), async {
                while requests.lock().unwrap().is_empty() {
                    tokio::time::sleep(Duration::from_millis(10)).await;
                }
            })
            .await
            .expect("target request must complete");
            let sent = requests.lock().unwrap().clone();
            assert_eq!(sent.len(), 1, "{target}");
            assert_eq!(sent[0].method, "POST", "{target}");
            let content_type = sent[0]
                .headers
                .iter()
                .find(|(name, _)| name.eq_ignore_ascii_case("content-type"))
                .map(|(_, value)| value.as_str())
                .expect("POST content type");
            match encoding {
                "text/plain" => {
                    assert_eq!(content_type, encoding);
                    assert_eq!(sent[0].body, b"x=owned\r\n", "{target}");
                }
                "multipart/form-data" => {
                    let boundary = content_type
                        .strip_prefix("multipart/form-data; boundary=")
                        .expect("native multipart boundary");
                    assert_eq!(sent[0].body, format!("--{boundary}\r\nContent-Disposition: form-data; name=\"x\"\r\n\r\nowned\r\n--{boundary}--\r\n").as_bytes(), "{target}");
                }
                _ => {
                    assert_eq!(content_type, encoding);
                    assert_eq!(sent[0].body, b"x=owned", "{target}");
                }
            }
            assert_eq!(
                page.evaluate("location.pathname").await.unwrap(),
                "/start",
                "source page must not navigate"
            );
            for descriptor in context.pages() {
                context.close_page(descriptor.page.page_id).await.unwrap();
            }
        }
    }

    #[cfg(all(unix, feature = "v8-host"))]
    #[tokio::test(flavor = "current_thread")]
    async fn form_post_redirect_rechecks_policy_before_forwarding_body() {
        struct Redirect(Arc<Mutex<Vec<NetworkRequest>>>);
        impl NetworkBroker for Redirect {
            fn send(
                &self,
                request: NetworkRequest,
            ) -> Result<NetworkResponse, crate::network::NetworkError> {
                let response = NetworkResponse {
                    response_policy: None,
                    timing: None,
                    request_id: request.request_id,
                    status: 307,
                    headers: vec![("location".into(), "https://blocked.test/charge".into())],
                    body: vec![],
                };
                self.0.lock().unwrap().push(request);
                Ok(response)
            }
        }
        for target in ["_self", "result"] {
            let requests = Arc::new(Mutex::new(Vec::new()));
            let mut options = ContextOptions::default();
            options
                .action_policy
                .rules
                .insert(ConsequentialAction::FormSubmission, PolicyRule::Allow);
            options.action_policy.rules.insert(
                ConsequentialAction::CrossOriginNavigation,
                PolicyRule::Allow,
            );
            options
                .action_policy
                .denied_origins
                .insert("https://blocked.test".into());
            let context = Browser::in_process_with_config(BrowserConfig::default())
                .new_context_with_broker(
                    options,
                    SharedNetworkBroker::new(Redirect(requests.clone())),
                );
            let page = context.new_page();
            page.load_html("https://forms.test/start", &format!("<iframe name=result></iframe><form id=f method=post action=/send target='{target}'><input name=secret value=owned></form>")).await.unwrap();
            // Frame load errors can surface asynchronously as frame error events.
            let _ = page.evaluate("f.requestSubmit();'submitted'").await;
            // Redirect authorization runs after the evaluation reply. Await
            // the exact parent denial before checking that no body crossed it.
            tokio::time::timeout(Duration::from_secs(5), async {
                loop {
                    if context.security_audit().iter().any(|record| {
                        record.request.action == ConsequentialAction::FormSubmission
                            && record.request.target_origin.as_deref()
                                == Some("https://blocked.test")
                            && record.decision == PolicyDecision::Denied
                    }) {
                        break;
                    }
                    tokio::time::sleep(Duration::from_millis(10)).await;
                }
            })
            .await
            .expect("redirect must reach the parent form-policy denial");
            let sent = requests.lock().unwrap().clone();
            assert_eq!(
                sent.len(),
                1,
                "{target}: denied destination must receive no request"
            );
            assert_eq!(sent[0].url, "https://forms.test/send");
            assert_eq!(sent[0].body, b"secret=owned");
            assert!(
                context
                    .security_audit()
                    .iter()
                    .any(
                        |record| record.request.action == ConsequentialAction::FormSubmission
                            && record.request.target_origin.as_deref()
                                == Some("https://blocked.test")
                            && record.decision == PolicyDecision::Denied
                    ),
                "{target}: parent form policy denial missing"
            );
            page.close().await.unwrap();
        }
    }

    #[cfg(feature = "v8-host")]
    #[tokio::test(flavor = "current_thread")]
    async fn generated_blob_urls_share_bytes_across_fetch_xhr_and_workers() {
        let page = Browser::in_process_with_config(BrowserConfig::default())
            .new_context()
            .new_page();
        page.load_html("https://blob.example.test/", r#"<!doctype html><output id=result>pending</output><script>
            const result=document.getElementById('result');
            (async () => {
                const readXHR=url=>new Promise((resolve,reject)=>{
                    const xhr=new XMLHttpRequest();xhr.open('GET',url);xhr.responseType='arraybuffer';
                    xhr.onload=()=>resolve([...new Uint8Array(xhr.response)]);
                    xhr.onerror=()=>reject(new Error('XHR failed'));xhr.send();
                });
                const bytes=[0,255,128,0,1];
                const url=URL.createObjectURL(new Blob([new Uint8Array(bytes)]));
                const fetched=[...new Uint8Array(await (await fetch(url)).arrayBuffer())];
                const xhr=await readXHR(url);
                const source='postMessage("shared-registry")';
                const workerURL=URL.createObjectURL(new Blob([source],{type:'application/javascript'}));
                const fetchedSource=await (await fetch(workerURL)).text();
                const reply=await new Promise((resolve,reject)=>{
                    const worker=new Worker(workerURL);
                    worker.onmessage=event=>{resolve(event.data);worker.terminate()};
                    worker.onerror=event=>reject(new Error(event.message));
                });
                URL.revokeObjectURL(url);URL.revokeObjectURL(workerURL);
                let fetchRejected=false,xhrRejected=false;
                try {await fetch(url)} catch {fetchRejected=true}
                try {await readXHR(url)} catch {xhrRejected=true}
                result.textContent=JSON.stringify({fetched,xhr,fetchedSource,reply,fetchRejected,xhrRejected});
            })().catch(error=>result.textContent=String(error)).finally(()=>result.setAttribute('data-done',''));
        </script>"#).await.unwrap();
        page.wait_for(WaitPredicate::SelectorExists("#result[data-done]".into()))
            .await
            .unwrap();
        let value = page
            .evaluate("document.getElementById('result').textContent")
            .await
            .unwrap();
        assert_eq!(
            serde_json::from_str::<serde_json::Value>(&value).expect(&value),
            serde_json::json!({
                "fetched": [0,255,128,0,1], "xhr": [0,255,128,0,1],
                "fetchedSource": "postMessage(\"shared-registry\")", "reply": "shared-registry",
                "fetchRejected": true, "xhrRejected": true,
            })
        );
    }

    #[cfg(feature = "v8-host")]
    #[tokio::test(flavor = "current_thread")]
    async fn same_task_history_rewrite_is_used_by_script_referrer_before_checkpoint() {
        struct Fixture(Arc<Mutex<Vec<NetworkRequest>>>);
        impl NetworkBroker for Fixture {
            fn send(
                &self,
                request: NetworkRequest,
            ) -> Result<NetworkResponse, crate::network::NetworkError> {
                let path = Url::parse(&request.url).unwrap().path().to_owned();
                let (mime, body) = if path == "/start" {
                    (
                        "text/html",
                        "<!doctype html><base href='/assets/'><script>history.pushState(null,'','/');history.replaceState(null,'','A'.repeat(4097-location.href.length));const s=document.createElement('script');s.src='probe.js';document.head.appendChild(s)</script><body>root",
                    )
                } else if path == "/assets/probe.js" {
                    ("text/javascript", "globalThis.probeLoaded=true")
                } else {
                    panic!("unexpected navigation {}", request.url)
                };
                let response = NetworkResponse {
                    response_policy: None,
                    timing: None,
                    request_id: request.request_id,
                    status: 200,
                    headers: vec![("content-type".into(), mime.into())],
                    body: body.as_bytes().to_vec(),
                };
                self.0.lock().unwrap().push(request);
                Ok(response)
            }
        }
        let requests = Arc::new(Mutex::new(Vec::new()));
        let context = Browser::new().new_context_with_broker(
            ContextOptions::default(),
            SharedNetworkBroker::new(Fixture(requests.clone())),
        );
        let page = context.new_page();
        page.goto("https://referrer.example.test/start")
            .await
            .unwrap();
        assert_eq!(page.evaluate("probeLoaded").await.unwrap(), "true");
        let requests = requests.lock().unwrap();
        let probe = requests
            .iter()
            .find(|request| request.url.ends_with("/assets/probe.js"))
            .unwrap();
        assert_eq!(
            probe
                .headers
                .iter()
                .find(|(name, _)| name.eq_ignore_ascii_case("referer"))
                .map(|(_, value)| value.as_str()),
            Some("https://referrer.example.test/")
        );
        assert_eq!(
            requests.len(),
            2,
            "history rewrite must not fetch another Document"
        );
    }

    #[cfg(feature = "v8-host")]
    #[tokio::test(flavor = "current_thread")]
    async fn frame_history_updates_keep_document_and_update_navigation_referrer() {
        struct FrameHistoryFixture(Arc<Mutex<Vec<NetworkRequest>>>);
        impl NetworkBroker for FrameHistoryFixture {
            fn send(
                &self,
                request: NetworkRequest,
            ) -> Result<NetworkResponse, crate::network::NetworkError> {
                let body = match Url::parse(&request.url).unwrap().path() {
                    "/start" if request.url.ends_with("?dynamic") => {
                        "<!doctype html><body><script>const frame=document.createElement('iframe');frame.id='child';frame.src='/child';document.body.appendChild(frame)</script>"
                    }
                    "/start" => "<!doctype html><iframe id=child src=/child></iframe>",
                    "/child" => {
                        r#"<!doctype html><p id=marker>original</p><script>
                        globalThis.originalMarker=document.getElementById('marker');
                        globalThis.navigateFromHere=()=>{location.href='/destination'};
                        globalThis.updateHistory=(method, navigate)=>{
                            history[method]({key:7},'', '/changed?state=7');
                            parent.immediateInitiator=document.URL;
                            if(navigate) location.href='/destination';
                        };
                    </script>"#
                    }
                    "/destination" => "<!doctype html><p>destination</p>",
                    _ => panic!("same-document URL was fetched: {}", request.url),
                };
                let response = NetworkResponse {
                    response_policy: None,
                    timing: None,
                    request_id: request.request_id,
                    status: 200,
                    headers: vec![("content-type".into(), "text/html".into())],
                    body: body.as_bytes().to_vec(),
                };
                self.0.lock().unwrap().push(request);
                Ok(response)
            }
        }
        let requests = Arc::new(Mutex::new(Vec::new()));
        let context = Browser::new().new_context_with_broker(
            ContextOptions::default(),
            SharedNetworkBroker::new(FrameHistoryFixture(requests.clone())),
        );
        for query in ["", "?dynamic"] {
            for method in ["pushState", "replaceState"] {
                for same_task in [false, true] {
                    let page = context.new_page();
                    page.goto(format!("https://history.example.test/start{query}"))
                        .await
                        .unwrap();
                    page.evaluate(format!(
                    "document.getElementById('child').contentWindow.updateHistory('{method}',{same_task});'updated'"
                )).await.unwrap();
                    assert_eq!(
                        page.evaluate("immediateInitiator").await.unwrap(),
                        "https://history.example.test/changed?state=7"
                    );
                    if !same_task {
                        assert_eq!(page.evaluate("(() => {const w=document.getElementById('child').contentWindow;return [w.location.pathname,w.history.state.key,w.document.getElementById('marker')===w.originalMarker].join('|')})()").await.unwrap(), "/changed|7|true");
                        page.evaluate("document.getElementById('child').contentWindow.navigateFromHere();'requested'").await.unwrap();
                    }
                    assert_eq!(
                        page.evaluate("document.getElementById('child').contentDocument.referrer")
                            .await
                            .unwrap(),
                        "https://history.example.test/changed?state=7",
                        "method={method} same_task={same_task} requests={:?}",
                        requests.lock().unwrap()
                    );
                    assert_eq!(
                        page.evaluate(
                            "typeof document.getElementById('child').contentWindow.originalMarker"
                        )
                        .await
                        .unwrap(),
                        "undefined"
                    );
                }
            }
        }
        let requests = requests.lock().unwrap();
        assert_eq!(requests.len(), 24);
        for request in requests
            .iter()
            .filter(|request| request.url.ends_with("/destination"))
        {
            assert_eq!(
                request
                    .headers
                    .iter()
                    .find(|(name, _)| name.eq_ignore_ascii_case("referer"))
                    .map(|(_, value)| value.as_str()),
                Some("https://history.example.test/changed?state=7")
            );
        }
    }

