    #[cfg(feature = "v8-host")]
    #[tokio::test(flavor = "current_thread")]
    async fn settings_value_conversion_cannot_mutate_replaced_frame_document() {
        let page = Browser::new().new_context().new_page();
        page.load_html("https://editing.example.test/settings-owner",
            "<!doctype html><iframe></iframe>").await.unwrap();
        let result = page.evaluate(r#"(() => {
            const check=(ok,label)=>{if(!ok)throw Error(label)};
            const commands=['styleWithCSS','useCSS','defaultParagraphSeparator'];
            document.execCommand('styleWithCSS',false,'false');
            document.execCommand('defaultParagraphSeparator',false,'div');
            for(const command of commands) {
                let frame=document.querySelector('iframe');
                if(!frame){frame=document.createElement('iframe');document.body.append(frame);}
                const old=frame.contentDocument;
                check(old.queryCommandEnabled(command),'connected child settings enabled');
                check(old.execCommand('styleWithCSS',false,'false'),'child baseline');
                check(old.execCommand('defaultParagraphSeparator',false,'div'),'child separator baseline');
                let calls=0,replacement;
                const value={toString(){calls++;frame.remove();replacement=document.createElement('iframe');
                    document.body.append(replacement);return command==='defaultParagraphSeparator'?'p':command==='useCSS'?'false':'true';}};
                check(old.execCommand(command,false,value)===false,'retired conversion rejected: '+command);
                check(calls===1,'single conversion');
                const current=replacement.contentDocument;
                check(!current.queryCommandState('styleWithCSS'),'replacement CSS unchanged');
                check(current.queryCommandValue('defaultParagraphSeparator')==='div','replacement separator unchanged');
                check(!document.queryCommandState('styleWithCSS'),'parent CSS unchanged');
                check(document.queryCommandValue('defaultParagraphSeparator')==='div','parent separator unchanged');
                check(current.execCommand(command,false,command==='defaultParagraphSeparator'?'p':'true'),'next live receiver executes');
                replacement.remove();
            }
            return 'passed';
        })()"#).await.unwrap();
        assert_eq!(result, "passed");
    }

    #[cfg(feature = "v8-host")]
    #[tokio::test(flavor = "current_thread")]
    async fn editing_typing_consumes_terminal_placeholders_and_keeps_visible_breaks() {
        let page = Browser::new().new_context().new_page();
        page.load_html(
            "https://editing.example.test/placeholders",
            "<!doctype html><div id=host contenteditable></div>",
        )
        .await
        .unwrap();
        let result = page.evaluate(r#"(() => {
          const host = document.getElementById('host');
          let checked = 0;
          for (const editable of ['true','plaintext-only']) {
            host.contentEditable = editable;
            for (const mode of ['normal','nowrap','pre','pre-wrap','pre-line','break-spaces']) {
              host.style.whiteSpace = mode;
              const line = mode === 'normal' || mode === 'nowrap' ? '<br>' : '\n';
              for (const selectAll of [false,true]) {
                host.innerHTML = '<p><b>AB</b></p>';
                const bold = host.firstChild.firstChild;
                host.focus();
                const range = document.createRange();
                range.setStart(bold.firstChild, selectAll ? 0 : 2); range.setEnd(bold.firstChild, 2);
                getSelection().removeAllRanges(); getSelection().addRange(range);
                document.execCommand('insertLineBreak');
                const observer = new MutationObserver(() => {});
                observer.observe(host, {subtree:true, childList:true, characterData:true});
                document.execCommand('insertText', false, 'a');
                const records = observer.takeRecords(); observer.disconnect();
                const last = records[records.length - 1];
                if (!last || !(last.type === 'characterData' || last.addedNodes.length && last.addedNodes[0].nodeType === 3)) throw new Error('text insertion was not the final DOM mutation');
                const expected = '<p><b>' + (selectAll ? '' : 'AB') + line + 'a</b></p>';
                if (host.innerHTML !== expected) throw new Error(JSON.stringify({editable,mode,selectAll,expected,actual:host.innerHTML}));
                document.execCommand('insertText', false, 'b');
                if (bold.textContent !== (selectAll ? '' : 'AB') + (line === '<br>' ? '' : '\n') + 'ab') throw new Error('typing caret or formatting lost');
                checked++;
              }
              for (const tail of ['<br>tail','<br><br>']) {
                host.innerHTML = '<p><b>AB' + tail + '</b></p>';
                host.focus();getSelection().collapse(host.firstChild.firstChild.firstChild,2);
                document.execCommand('insertText', false, 'a');
                if (host.innerHTML !== '<p><b>ABa' + tail + '</b></p>') throw new Error('visible line break removed');
                checked++;
              }
            }
          }
          return String(checked);
        })()"#).await.unwrap();
        assert_eq!(result, "48");
    }

    // Yield after each complete case to retain the production command limit.
    #[cfg(feature = "v8-host")]
    async fn run_editing_matrix(page: &PageHandle, cases: usize, generator: &str) {
        page.evaluate(&format!("globalThis.editingMatrix = {generator}; 'ready'"))
            .await
            .expect("initialize editing matrix");
        for case in 1..=cases {
            let result = page
                .evaluate("JSON.stringify(globalThis.editingMatrix.next())")
                .await
                .unwrap_or_else(|error| panic!("editing matrix case {case}: {error:?}"));
            assert_eq!(result, format!(r#"{{"value":{case},"done":false}}"#));
        }
        let result = page.evaluate("const end = globalThis.editingMatrix.next(); delete globalThis.editingMatrix; JSON.stringify(end)")
            .await.expect("finish editing matrix");
        assert_eq!(result, format!(r#"{{"value":"{cases}","done":true}}"#));
    }

    #[cfg(feature = "v8-host")]
    #[tokio::test(flavor = "current_thread")]
    async fn editing_join_preserves_author_whitespace_but_not_ua_defaults() {
        let page = Browser::new().new_context().new_page();
        page.load_html(
            "https://editing.example.test/origins",
            "<!doctype html><style id=rules></style><div id=host contenteditable></div>",
        )
        .await
        .unwrap();
        run_editing_matrix(&page, 72, r#"(function* () {
          const host = document.getElementById('host');
          const rules = document.getElementById('rules');
          let checked = 0;
          for (const tag of ['div','p','blockquote']) {
            for (const authored of [false,true]) {
              rules.textContent = authored ? 'pre {white-space:pre}' : '';
              for (const preOnLeft of [false,true]) {
                for (const direction of ['backward','forward','selection']) for (const separator of ['', '\n']) {
                  const leftTag = preOnLeft ? 'pre' : tag;
                  const rightTag = preOnLeft ? tag : 'pre';
                  host.innerHTML = '<' + leftTag + '>abc</' + leftTag + '>' + separator + '<' + rightTag + '>def</' + rightTag + '>';
                  const left = host.firstChild, right = host.lastChild;
                  host.focus();
                  const range = document.createRange();
                  if (direction === 'backward') {
                    range.setStart(right.firstChild, 0); range.collapse(true);
                  } else {
                    range.setStart(left.firstChild, 3);
                    if (direction === 'forward') range.collapse(true);
                    else range.setEnd(right.firstChild, 0);
                  }
                  getSelection().removeAllRanges(); getSelection().addRange(range);
                  document.execCommand(direction === 'forward' ? 'forwardDelete' : 'delete');
                  const suffix = authored && !preOnLeft ? '<span style="white-space: pre;">def</span>' : 'def';
                  const expected = '<' + leftTag + '>abc' + suffix + '</' + leftTag + '>';
                  if (host.innerHTML !== expected) throw new Error(JSON.stringify({tag,authored,preOnLeft,direction,actual:host.innerHTML,expected}));
                  document.execCommand('insertText', false, 'X');
                  if (left.textContent !== 'abcXdef') throw new Error('join caret moved');
                  yield ++checked;
                }
              }
            }
          }
          return String(checked);
        })()"#).await;
    }

    #[cfg(feature = "v8-host")]
    #[tokio::test(flavor = "current_thread")]
    async fn editing_join_respects_preformatted_containers_and_placeholder_breaks() {
        let context = Browser::new().new_context();
        let page = context.new_page();
        page.load_html(
            "https://editing.example.test/preformatted-inline",
            "<!doctype html><div id=host contenteditable></div>",
        )
        .await
        .unwrap();
        run_editing_matrix(&page, 150, r#"(function* () {
          const host = document.getElementById('host');let checked=0;
          for (const css of [false,true]) {
            for (const tag of ['pre','listing']) for (const attrs of ['', ' style="white-space:pre"', ' style="white-space:pre-wrap"']) {
              for (const source of ['bar','<span style="white-space:normal">bar</span>','<span style="white-space:nowrap">bar</span>','<b>bar</b>']) {
                for (const direction of ['backward','forward','selection']) {
                  host.innerHTML='<'+tag+attrs+'>foo</'+tag+'>'+source;
                  const left=host.firstChild;let right=host.lastChild;
                  while (right.nodeType!==3) right=right.firstChild;
                  host.focus();document.execCommand('styleWithCSS',false,css);
                  const range=document.createRange();
                  if (direction==='backward') {range.setStart(right,0);range.collapse(true);}
                  else {range.setStart(left.firstChild,3);if(direction==='forward')range.collapse(true);else range.setEnd(right,0);}
                  getSelection().removeAllRanges();getSelection().addRange(range);
                  document.execCommand(direction==='forward'?'forwardDelete':'delete');
                  const expected='<'+tag+attrs+'>foo'+(source.startsWith('<b>')?'<b>bar</b>':'bar')+'</'+tag+'>';
                  if(host.innerHTML!==expected)throw new Error(JSON.stringify({css,tag,attrs,source,direction,expected,actual:host.innerHTML}));
                  document.execCommand('insertText',false,'X');
                  if(left.textContent!=='fooXbar')throw new Error('preformatted join caret changed');
                  yield ++checked;
                }
              }
            }
            for (const breaks of [1,2,3]) {
              host.innerHTML='<p>foo</p>'+'<br>'.repeat(breaks)+'<p>bar</p>';
              host.focus();document.execCommand('styleWithCSS',false,css);getSelection().collapse(host.firstChild.firstChild,3);document.execCommand('forwardDelete');
              const expected='<p>foo</p>'+'<br>'.repeat(breaks-1)+'<p>bar</p>';
              if(host.innerHTML!==expected)throw new Error(JSON.stringify({css,breaks,expected,actual:host.innerHTML}));
              yield ++checked;
            }
          }
          return String(checked);
        })()"#).await;
    }

    #[cfg(feature = "v8-host")]
    #[tokio::test(flavor = "current_thread")]
    async fn editing_join_preserves_default_inline_whitespace_and_outer_formatting() {
        let page = Browser::new().new_context().new_page();
        page.load_html(
            "https://editing.example.test/default-inline",
            "<!doctype html><style id=rules></style><div id=host contenteditable></div>",
        )
        .await
        .unwrap();
        run_editing_matrix(&page, 300, r#"(function* () {
          const host = document.getElementById('host'), rules = document.getElementById('rules');
          const cases = [
            ['def', '', null],
            ['def<br>ghi', 'ghi', null],
            ['def<div>ghi</div>', '<div>ghi</div>', null],
            ['<b>def</b>', '', 'b'],
            ['<b>def<br>ghi</b>', '<b>ghi</b>', 'b'],
            ['<b>def</b><br>ghi', 'ghi', 'b'],
            ['<b>def<br></b>ghi', 'ghi', 'b'],
            ['<em>def<br>ghi</em>', '<em>ghi</em>', 'em'],
            ['<b style="color:red">def<br>ghi</b>', '<b style="color:red">ghi</b>', 'b'],
            ['<b><i>def<br>ghi</i></b>', '<b><i>ghi</i></b>', 'i']
          ];
          let checked = 0;
          for (const mode of ['nowrap','pre','pre-wrap','pre-line','break-spaces']) {
            rules.textContent = '.left{white-space:' + mode + '}';
            for (const authored of [false,true]) for (const direction of ['backward','forward','selection']) {
              for (const [body, remainder, formatting] of cases) {
                host.innerHTML = (authored ? '<div style="white-space:' + mode + '">' : '<div class="left">') + 'abc</div>' + body;
                const left = host.firstChild, source = left.nextSibling;
                let rightText = source;
                while (rightText.nodeType !== 3) rightText = rightText.firstChild;
                host.focus();
                const range = document.createRange();
                if (direction === 'backward') {range.setStart(rightText,0);range.collapse(true);}
                else {range.setStart(left.firstChild,3);if (direction === 'forward') range.collapse(true);else range.setEnd(rightText,0);}
                getSelection().removeAllRanges();getSelection().addRange(range);
                document.execCommand(direction === 'forward' ? 'forwardDelete' : 'delete');
                const details = () => JSON.stringify({mode,authored,direction,body,actual:host.innerHTML});
                if (left.textContent !== 'abcdef') throw new Error('first line changed ' + details());
                const remaining = Array.from(host.childNodes).slice(1).map(n => n.nodeType === 3 ? n.data : n.outerHTML).join('');
                if (remaining !== remainder) throw new Error('remainder changed ' + details());
                const walker = document.createTreeWalker(left,NodeFilter.SHOW_TEXT);
                let moved;
                while (walker.nextNode()) if (walker.currentNode.data.includes('def')) moved = walker.currentNode;
                if (!moved || getComputedStyle(moved.parentElement).whiteSpace !== 'normal') throw new Error('default whitespace lost ' + details());
                if (formatting && !moved.parentElement.closest(formatting)) throw new Error('outer formatting lost ' + details());
                if (body === '<b>def</b>' && !left.contains(source)) throw new Error('whole inline identity lost ' + details());
                if (body.includes('color:red') && getComputedStyle(moved.parentElement).color !== 'rgb(255, 0, 0)') throw new Error('authored declaration lost ' + details());
                document.execCommand('insertText',false,'X');
                if (left.textContent !== 'abcXdef') throw new Error('caret changed ' + details());
                yield ++checked;
              }
            }
          }
          return String(checked);
        })()"#).await;
    }

