    #[cfg(feature = "v8-host")]
    #[tokio::test(flavor = "current_thread")]
    async fn scrolling_element_tracks_document_mode_and_body_overflow() {
        for (doctype, quirks) in [("", true), ("<!doctype html>", false)] {
            let page = Browser::new().new_context().new_page();
            page.load_html("https://geometry.example.test/scrolling-element",
                &format!("{doctype}<style>body{{margin:0}}</style><div style='height:1000px'>Content</div>")).await.unwrap();
            let initial = if quirks {
                "document.scrollingElement===document.body"
            } else {
                "document.scrollingElement===document.documentElement"
            };
            assert_eq!(page.evaluate(initial).await.unwrap(), "true");
            assert_eq!(page.evaluate("document.scrollingElement.scrollTop=50;[document.scrollingElement.scrollTop,scrollY,document.documentElement.scrollTop].join('|')").await.unwrap(),
                if quirks { "50|50|0" } else { "50|50|50" });
            if quirks {
                assert_eq!(
                    page.evaluate("document.documentElement.scrollTop=0;scrollY")
                        .await
                        .unwrap(),
                    "50"
                );
            }
            page.evaluate("document.documentElement.style.overflow='auto';document.body.style.overflow='auto'").await.unwrap();
            let independent = if quirks {
                "document.scrollingElement===null"
            } else {
                "document.scrollingElement===document.documentElement"
            };
            assert_eq!(page.evaluate(independent).await.unwrap(), "true");
            page.evaluate("document.documentElement.style.overflow='clip'")
                .await
                .unwrap();
            assert_eq!(page.evaluate(initial).await.unwrap(), "true");
        }
    }

    #[cfg(feature = "v8-host")]
