    async fn semantic_scroll_into_view_traverses_assigned_slot_ancestors() {
        let page = Browser::new().new_context().new_page();
        page.load_html("https://geometry.example.test/slotted-scroll",r#"<!doctype html>
            <div id="host" style="display:block;width:100px;height:100px">
                <div style="height:200px"></div>
                <button id="target" style="display:block;height:20px;margin:0;padding:0;border:0">Target</button>
                <div style="height:300px"></div>
            </div>"#).await.unwrap();
        page.evaluate(
            r#"document.getElementById('host').attachShadow({mode:'open'}).innerHTML=
            '<div id="port" style="width:100px;height:100px;overflow:auto"><slot></slot></div>'"#,
        )
        .await
        .unwrap();
        let before = page.observe().await.unwrap();
        let target = before
            .nodes
            .iter()
            .find(|node| node.name == "Target")
            .unwrap()
            .semantic_ref;
        let offset =
            "String(document.getElementById('host').shadowRoot.querySelector('#port').scrollTop)";
        page.evaluate("document.getElementById('target').scrollIntoView({container:'nearest'})")
            .await
            .unwrap();
        assert_eq!(page.evaluate(offset).await.unwrap(), "200");
        page.evaluate(
            "document.getElementById('host').shadowRoot.querySelector('#port').scrollTop=0",
        )
        .await
        .unwrap();
        page.scroll_into_view(target).await.unwrap();
        assert_eq!(page.evaluate(offset).await.unwrap(), "200");
        let snapshot = page.paint_snapshot().await.unwrap();
        let button = snapshot
            .nodes
            .iter()
            .find(|node| node.tag == "button")
            .unwrap();
        assert!(
            button
                .projection
                .as_ref()
                .is_some_and(|projection| !projection.clips.is_empty())
        );
        assert_eq!(page.evaluate(r#"(()=>{const target=document.getElementById('target'),port=document.getElementById('host').shadowRoot.querySelector('#port');
            const a=target.getBoundingClientRect(),b=port.getBoundingClientRect();return Math.abs(a.top-b.top)<0.001})()"#).await.unwrap(),"true");
    }

    #[cfg(feature = "v8-host")]
    #[tokio::test(flavor = "current_thread")]
    async fn scroll_into_view_aligns_target_geometry_and_validates_options() {
        let page = Browser::new().new_context().new_page();
        page.load_html("https://geometry.example.test/into-view",r#"<!doctype html>
            <style>#outer{width:100px;height:100px;overflow:auto}#content{height:600px}#spacer{height:200px}#target{height:20px}</style>
            <section id="outer"><div id="content"><div id="spacer"></div><div id="target">Target</div></div></section>"#).await.unwrap();
        for (argument, expected) in [
            ("{block:'start'}", "200"),
            ("{block:'center'}", "160"),
            ("{block:'end'}", "120"),
            ("{block:'nearest'}", "120"),
            ("false", "120"),
            ("true", "200"),
        ] {
            let script = format!(
                "(()=>{{const e=document.getElementById('outer');e.scrollTop=0;document.getElementById('target').scrollIntoView({argument});return String(e.scrollTop)}})()"
            );
            assert_eq!(
                page.evaluate(&script).await.unwrap(),
                expected,
                "{argument}"
            );
        }
        assert_eq!(page.evaluate(r#"(()=>{const e=document.getElementById('outer');e.scrollTop=180;
            document.getElementById('target').scrollIntoView({block:'nearest'});return String(e.scrollTop)})()"#).await.unwrap(),"180");
        assert_eq!(page.evaluate(r#"(()=>{const e=document.getElementById('outer');e.scrollTop=0;
            try{document.getElementById('target').scrollIntoView({block:'invalid'})}catch(error){return error instanceof TypeError && e.scrollTop===0}return false})()"#).await.unwrap(),"true");
        assert_eq!(page.evaluate(r#"(()=>{const e=document.getElementById('outer');e.scrollTop=0;
            const marker={},log=[];try{document.getElementById('target').scrollIntoView({
                get behavior(){log.push('behavior');return 'auto'},get block(){log.push('block');throw marker},
                get container(){log.push('container');return 'all'}})}catch(error){
                return error===marker && e.scrollTop===0 && log.join('|')==='behavior|block'}return false})()"#).await.unwrap(),"true");
        assert_eq!(page.evaluate(r#"(()=>{const log=[];document.getElementById('target').scrollIntoView({
            get behavior(){log.push('behavior');return 'instant'},get block(){log.push('block');return 'nearest'},
            get container(){log.push('container');return 'nearest'},get inline(){log.push('inline');return 'nearest'}});
            return log.join('|')})()"#).await.unwrap(),"behavior|block|container|inline");
        page.evaluate("document.getElementById('target').style.cssText='scroll-margin-top:7px;scroll-margin-bottom:11px'").await.unwrap();
        for transform in ["none", "scale(2)"] {
            page.evaluate(&format!("document.getElementById('outer').style.cssText='scroll-padding:10% 0 20%;transform:{transform};transform-origin:0 0'")).await.unwrap();
            for (alignment, expected) in [("start", "183"), ("center", "167"), ("end", "151")] {
                let script = format!(
                    "(()=>{{const e=document.getElementById('outer');e.scrollTop=0;document.getElementById('target').scrollIntoView({{block:'{alignment}',container:'nearest'}});return String(e.scrollTop)}})()"
                );
                assert_eq!(
                    page.evaluate(&script).await.unwrap(),
                    expected,
                    "{transform} {alignment}"
                );
            }
        }
    }

