    #[cfg(feature = "v8-host")]
    #[tokio::test(flavor = "current_thread")]
    async fn shrinking_scroll_content_and_overflow_changes_reconcile_before_paint() {
        let page = Browser::new().new_context().new_page();
        page.load_html("https://geometry.example.test/scroll-clamping",r#"<!doctype html>
            <style>body{margin:0}section{width:100px;height:100px;overflow:auto}article{width:400px;height:400px}</style>
            <section id="outer"><article id="inner"></article></section>"#).await.unwrap();
        page.evaluate("document.getElementById('outer').scrollTo(200,200)")
            .await
            .unwrap();
        let initial = page.paint_snapshot().await.unwrap();
        let matrix = |snapshot: &oryn_common::v4::PaintSnapshot| {
            snapshot
                .nodes
                .iter()
                .find(|node| node.tag == "article")
                .unwrap()
                .projection
                .as_ref()
                .unwrap()
                .matrix
        };
        assert_eq!((matrix(&initial)[12], matrix(&initial)[13]), (-200., -200.));
        // Paint is the first geometry consumer after shrinking the content.
        page.evaluate("document.getElementById('inner').style.cssText='width:150px;height:125px'")
            .await
            .unwrap();
        let shrunk = page.paint_snapshot().await.unwrap();
        assert_eq!((matrix(&shrunk)[12], matrix(&shrunk)[13]), (-50., -25.));
        let offsets = "(()=>{const e=document.getElementById('outer');return [e.scrollLeft,e.scrollTop].join('|')})()";
        assert_eq!(page.evaluate(offsets).await.unwrap(), "50|25");
        page.evaluate("document.getElementById('inner').style.cssText='width:400px;height:400px';document.getElementById('outer').scrollTo(200,200)").await.unwrap();
        page.evaluate("document.getElementById('inner').style.cssText='width:150px;height:125px';document.getElementById('outer').scrollBy(-10,-5)").await.unwrap();
        assert_eq!(page.evaluate(offsets).await.unwrap(), "40|20");
        page.evaluate("document.getElementById('outer').style.overflow='clip'")
            .await
            .unwrap();
        let clipped = page.paint_snapshot().await.unwrap();
        assert_eq!((matrix(&clipped)[12], matrix(&clipped)[13]), (0., 0.));
        assert_eq!(page.evaluate(offsets).await.unwrap(), "0|0");
        page.evaluate("document.getElementById('outer').style.overflow='hidden'")
            .await
            .unwrap();
        assert_eq!(page.evaluate(offsets).await.unwrap(), "0|0");
        page.evaluate("document.getElementById('outer').scrollTo(50,25)")
            .await
            .unwrap();
        page.evaluate("document.getElementById('inner').style.cssText='width:20px;height:20px'")
            .await
            .unwrap();
        // The getter path independently reconciles and republishes geometry.
        assert_eq!(page.evaluate(offsets).await.unwrap(), "0|0");
        let cleared = page.paint_snapshot().await.unwrap();
        assert_eq!((matrix(&cleared)[12], matrix(&cleared)[13]), (0., 0.));
        page.evaluate("document.getElementById('inner').style.cssText='width:400px;height:400px';document.getElementById('outer').scrollTo(100,100);document.getElementById('outer').style.display='none'").await.unwrap();
        assert_eq!(page.evaluate(offsets).await.unwrap(), "0|0");
        page.evaluate("document.getElementById('outer').style.display='block'")
            .await
            .unwrap();
        assert_eq!(page.evaluate(offsets).await.unwrap(), "0|0");
    }

