        page.load_html("https://paint.example.test/",r#"<!doctype html><style>body{margin:0}svg{margin-left:400px;width:200px;height:100px}foreignObject div{width:40px;height:20px;background:red}</style><svg viewBox="0 0 200 100"><foreignObject x="25%" y="10" width="50%" height="60"><div>Local</div><img width="1" height="1" src="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII="/></foreignObject></svg>"#).await.unwrap();
