    #[cfg(feature = "v8-host")]
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn slow_paint_images_do_not_hold_the_page_actor() {
        struct ReleaseImage(Arc<(std::sync::Mutex<(bool, bool)>, std::sync::Condvar)>);
        impl Drop for ReleaseImage {
            fn drop(&mut self) {
                let (lock, wake) = &*self.0;
                lock.lock().unwrap_or_else(|poison| poison.into_inner()).1 = true;
                wake.notify_all();
            }
        }
        struct SlowImage {
            state: Arc<(std::sync::Mutex<(bool, bool)>, std::sync::Condvar)>,
        }
        impl NetworkBroker for SlowImage {
            fn send(
                &self,
                request: NetworkRequest,
            ) -> Result<NetworkResponse, crate::network::NetworkError> {
                let (lock, wake) = &*self.state;
                let mut state = lock.lock().unwrap();
                state.0 = true;
                wake.notify_all();
                while !state.1 {
                    state = wake.wait(state).unwrap();
                }
                Ok(NetworkResponse {response_policy: None,timing:None,
                    request_id: request.request_id,
                    status: 200,
                    headers: vec![("content-type".into(), "image/png".into())],
                    body: BASE64
                        .decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=")
                        .unwrap(),
                })
            }
        }

        let state = Arc::new((
            std::sync::Mutex::new((false, false)),
            std::sync::Condvar::new(),
        ));
        // A deadline assertion must not leave blocked fixture threads alive
        // and contaminate later tests in the same native process.
        let _release_image = ReleaseImage(state.clone());
        let context = Browser::new().new_context_with_broker(
            ContextOptions::default(),
            SharedNetworkBroker::new(SlowImage {
                state: state.clone(),
            }),
        );
        let page = context.new_page();
        let load_page = page.clone();
        let mut load = tokio::spawn(async move {
            load_page.load_html(
                "https://paint.example.test/",
                "<style>img{width:8px;height:8px}</style><img alt=slow src=/slow.png><script>globalThis.loadEvents=[];document.addEventListener('DOMContentLoaded',()=>loadEvents.push('dom'));window.addEventListener('load',()=>loadEvents.push('load'))</script>",
            ).await
        });
        let mut last_events = String::new();
        let dom_loaded = tokio::time::timeout(Duration::from_secs(5), async {
            let mut document_admitted = false;
            loop {
                // A terminal constructor failure is not a held image. Retain
                // its actual error instead of obscuring it as a DCL timeout.
                if load.is_finished() {
                    panic!("image fixture load terminated before image release: {:?}", (&mut load).await);
                }
                match page
                    .evaluate("typeof loadEvents==='undefined'?'':loadEvents.join(',')")
                    .await
                {
                    Ok(events) => {
                        document_admitted = true;
                        last_events.clone_from(&events);
                        if events == "dom" {
                            break;
                        }
                    }
                    // The spawned load may not have installed its first document.
                    // Once evaluation succeeds, loss of that document is a failure.
                    Err(RuntimeError::EvaluationUnavailable) if !document_admitted => {}
                    Err(error) => panic!("image fixture document evaluation failed: {error}"),
                }
                tokio::time::sleep(Duration::from_millis(5)).await;
            }
        })
        .await;
        if dom_loaded.is_err() {
            // Bound diagnostic observation independently: a blocked actor must
            // remain a failure, not turn this timeout report into another wait.
            let diagnostic = tokio::time::timeout(Duration::from_millis(250), page.trace()).await;
            if let Ok(Ok(trace)) = diagnostic {
                for entry in trace.iter().rev().filter(|entry| matches!(entry.kind,
                    TraceEventKind::ScriptDiagnostic { .. } | TraceEventKind::LifecycleChanged { .. }
                )).take(8) {
                    eprintln!("slow image lifecycle diagnostic: {:?}", entry.kind);
                }
            }
        }
        assert!(dom_loaded.is_ok(),
            "DOMContentLoaded remains observable while image load is suspended: last_events={last_events:?}, load_finished={}, image_started={}",
            load.is_finished(), state.0.lock().unwrap().0);
        assert_eq!(page.evaluate("loadEvents.join(',')").await.unwrap(), "dom");
        let trace = page.trace().await.unwrap();
        // Trace custody spans the initial about:blank and its successor.
        // Assert this navigation's load barrier, not the predecessor's load.
        let navigation_started = trace.iter().rev().find_map(|event| {
            matches!(&event.kind, TraceEventKind::NavigationStarted { url }
                if url == "https://paint.example.test/").then_some(event.sequence)
        }).expect("held-image navigation has an actual start event");
        assert!(!trace.iter().filter(|event| event.sequence > navigation_started).any(|event| matches!(
            event.kind,
            TraceEventKind::LifecycleChanged {
                state: LifecycleState::Load
            }
        )));
        let paint_page = page.clone();
        let paint = tokio::spawn(async move { paint_page.paint_snapshot().await });
        tokio::task::spawn_blocking({
            let state = state.clone();
            move || {
                let (lock, wake) = &*state;
                let mut value = lock.lock().unwrap();
                while !value.0 {
                    value = wake.wait(value).unwrap();
                }
            }
        })
        .await
        .unwrap();
        tokio::time::timeout(Duration::from_millis(250), page.observe())
            .await
            .expect("observe must not queue behind image I/O")
            .expect("observe while paint is pending");
        {
            let (lock, wake) = &*state;
            let mut value = lock.lock().unwrap();
            value.1 = true;
            wake.notify_all();
        }
        load.await.unwrap().unwrap();
        assert_eq!(paint.await.unwrap().unwrap().images.len(), 1);
        for _ in 0..100 {
            if page.evaluate("loadEvents.join(',')").await.unwrap() == "dom,load" {
                break;
            }
            tokio::time::sleep(Duration::from_millis(10)).await;
        }
        assert_eq!(
            page.evaluate("loadEvents.join(',')").await.unwrap(),
            "dom,load"
        );
        assert!(page.trace().await.unwrap().iter()
            .filter(|event| event.sequence > navigation_started).any(|event| matches!(
            event.kind,
            TraceEventKind::LifecycleChanged {
                state: LifecycleState::Load
            }
        )));
    }

