    #[cfg(feature = "v8-host")]
    #[tokio::test]
    async fn stale_action_cancel_at_page_route_drops_old_held_source_custody() {
        use crate::host::webdriver_script::{
            FrameCommand, FrameResponse, ScriptContext, ScriptValue,
        };
        use crate::webdriver_actions::{ActionCommand, ActionsRequest};
        let context = Browser::in_process_with_config(BrowserConfig::default()).new_context();
        let page = context.new_page();
        page.load_html("https://input.test/","<textarea id=t></textarea><script>globalThis.releases=[];t.onkeyup=e=>releases.push(e.key);t.focus()</script>").await.unwrap();
        let FrameResponse::Inventory(realms) = page
            .webdriver_frames(FrameCommand::Inventory)
            .await
            .unwrap()
        else {
            panic!("inventory")
        };
        let selected = realms
            .into_iter()
            .find(|realm| realm.parent_realm.is_none() && realm.live)
            .unwrap();
        let request=ActionsRequest::parse(&ScriptValue::from_json_text(r#"{"actions":[{"id":"held","type":"key","actions":[{"type":"keyDown","value":"a"}]}]}"#).unwrap()).unwrap();
        page.execute_webdriver_actions_in_context(
            ActionCommand::Perform(request),
            ScriptContext {
                selected: Some(selected.clone()),
                ..Default::default()
            },
        )
        .await
        .unwrap();
        let mut stale = selected.clone();
        stale.document_generation += 1;
        assert!(
            page.execute_webdriver_actions_in_context(
                ActionCommand::Cancel,
                ScriptContext {
                    selected: Some(stale),
                    ..Default::default()
                }
            )
            .await
            .is_err()
        );
        page.execute_webdriver_actions_in_context(
            ActionCommand::Release,
            ScriptContext {
                selected: Some(selected),
                ..Default::default()
            },
        )
        .await
        .unwrap();
        assert_eq!(page.evaluate("releases.join(',')").await.unwrap(), "");
        context.close_page(page.page_id()).await.unwrap();
    }

    #[cfg(unix)]
    #[test]
    fn webdriver_cookie_snapshot_requires_live_native_authority_and_ignores_authored_url() {
        use oryn_js::message_wire::MessageRequest;
        let context = Browser::in_process_with_config(BrowserConfig::default()).new_context();
        let page = context.new_page();
        let id = page.page_id();
        context
            .install_document_security(id, "https://cookies.test/path".into(), &[])
            .unwrap();
        context
            .handle_message_wire(
                id,
                MessageRequest::RegisterRootDocument {
                    document_generation: 1,
                    stream_epoch: 0,
                },
            )
            .unwrap();
        let url = Url::parse("https://cookies.test/path").unwrap();
        let store = context.inner.parent_cookies.as_ref().unwrap();
        store
            .store_response(
                &url,
                &crate::cookies::CookieRequestContext::navigation(Some(url.to_string())),
                ["secret=yes; Secure; HttpOnly; Path=/".into()],
            )
            .unwrap();
        let mut snapshot = crate::host::webdriver_script::AutomationRealmSnapshot {
            realm: oryn_js::realm::RealmId(0),
            parent_realm: None,
            frame: None,
            frame_generation: None,
            frame_token: None,
            document_root: oryn_dom::DomRuntime::new().document(),
            document_generation: 1,
            stream_epoch: 0,
            document_authority_epoch: 0,
            url: "https://forged.test/".into(),
            live: false,
        };
        assert!(matches!(
            context.webdriver_cookies(id, &snapshot, true),
            Err(RuntimeError::Closed)
        ));
        assert_eq!(store.webdriver_cookies(&url, false).unwrap().len(), 1);
        assert!(matches!(
            context.webdriver_permission_origin(id, &snapshot),
            Err(RuntimeError::Closed)
        ));
        snapshot.live = true;
        snapshot.document_generation = 2;
        assert!(context.webdriver_cookies(id, &snapshot, true).is_err());
        assert_eq!(store.webdriver_cookies(&url, false).unwrap().len(), 1);
        snapshot.document_generation = 1;
        assert_eq!(
            context.webdriver_permission_origin(id, &snapshot).unwrap(),
            "https://cookies.test"
        );
        let cookies = context.webdriver_cookies(id, &snapshot, false).unwrap();
        assert_eq!(cookies.len(), 1);
        assert_eq!(cookies[0]["name"], "secret");
        assert_eq!(cookies[0]["httpOnly"], true);
        snapshot.frame_token = Some("foreign".repeat(16));
        assert!(context.webdriver_cookies(id, &snapshot, true).is_err());
        assert_eq!(store.webdriver_cookies(&url, false).unwrap().len(), 1);
        snapshot.frame_token = None;
        context.webdriver_cookies(id, &snapshot, true).unwrap();
        assert!(store.webdriver_cookies(&url, false).unwrap().is_empty());
    }

    #[cfg(unix)]
    #[test]
    fn webdriver_upload_rejects_fifo_without_waiting_for_a_writer() {
        use std::os::unix::ffi::OsStrExt;
        let mut options = ContextOptions::default();
        options.action_policy.rules.insert(
            ConsequentialAction::FileUpload,
            crate::security::PolicyRule::Allow,
        );
        let context = Browser::in_process_with_config(BrowserConfig::default())
            .new_context_with_options(options);
        let page = context.new_page();
        let id = page.page_id();
        context
            .install_document_security(id, "https://upload.test/".into(), &[])
            .unwrap();
        context
            .handle_message_wire(
                id,
                oryn_js::message_wire::MessageRequest::RegisterRootDocument {
                    document_generation: 1,
                    stream_epoch: 0,
                },
            )
            .unwrap();
        let path = std::env::temp_dir().join(format!("oryn-upload-fifo-{}", uuid::Uuid::new_v4()));
        let cpath = std::ffi::CString::new(path.as_os_str().as_bytes()).unwrap();
        assert_eq!(unsafe { libc::mkfifo(cpath.as_ptr(), 0o600) }, 0);
        let result = context.webdriver_upload_files(id, std::slice::from_ref(&path));
        std::fs::remove_file(path).unwrap();
        assert!(
            matches!(result,Err(RuntimeError::Upload(message))if message.contains("regular file"))
        );
    }

    #[cfg(unix)]
    #[test]
    fn webdriver_upload_binds_selected_frame_origin_and_rejects_stale_or_foreign_authority() {
        use oryn_js::message_wire::MessageRequest;
        let mut options = ContextOptions::default();
        options.action_policy.rules.insert(
            ConsequentialAction::FileUpload,
            crate::security::PolicyRule::Allow,
        );
        options
            .action_policy
            .denied_origins
            .insert("https://cross.test".into());
        let context = Browser::in_process_with_config(BrowserConfig::default())
            .new_context_with_options(options);
        let page = context.new_page();
        let id = page.page_id();
        context
            .install_document_security(id, "https://top.test/".into(), &[])
            .unwrap();
        context
            .handle_message_wire(
                id,
                MessageRequest::RegisterRootDocument {
                    document_generation: 1,
                    stream_epoch: 0,
                },
            )
            .unwrap();
        assert!(
            context
                .handle_message_wire(
                    id,
                    MessageRequest::RegisterWindow {
                        frame: "u".repeat(64),
                        document_generation: 1,
                        stream_epoch: 0,
                        origin: "https://cross.test".into(),
                        inherit_origin: None,
                    }
                )
                .is_err(),
            "malformed capability is rejected before registration"
        );
        let token = "a".repeat(64);
        let url = "https://cross.test/frame";
        context
            .handle_message_wire(
                id,
                MessageRequest::RegisterWindow {
                    frame: token.clone(),
                    document_generation: 1,
                    stream_epoch: 0,
                    origin: "https://cross.test".into(),
                    inherit_origin: None,
                },
            )
            .unwrap();
        let policy = context
            .prepare_frame_worker_policy(id, url, &[], "<input type=file>")
            .unwrap();
        context
            .bind_frame_worker_policy(id, token.clone(), 1, 0, url, &policy)
            .unwrap();
        let mut snapshot = crate::host::webdriver_script::AutomationRealmSnapshot {
            realm: oryn_js::realm::RealmId(1),
            parent_realm: Some(oryn_js::realm::RealmId(0)),
            frame: None,
            frame_generation: Some(1),
            frame_token: Some(token),
            document_root: oryn_dom::DomRuntime::new().document(),
            document_generation: 1,
            stream_epoch: 0,
            document_authority_epoch: 0,
            url: url.into(),
            live: true,
        };
        let path = std::path::PathBuf::from("/missing-selected-upload-proof");
        assert!(matches!(
            context.webdriver_upload_files_in_context(id, &snapshot, std::slice::from_ref(&path)),
            Err(RuntimeError::PolicyDenied {
                action: ConsequentialAction::FileUpload
            })
        ));
        assert!(matches!(
            context.webdriver_upload_files(id, std::slice::from_ref(&path)),
            Err(RuntimeError::Upload(_))
        ));
        snapshot.document_generation = 2;
        assert!(
            context
                .webdriver_upload_files_in_context(id, &snapshot, std::slice::from_ref(&path))
                .is_err()
        );
        snapshot.document_generation = 1;
        snapshot.frame_token = Some("foreign".repeat(16));
        assert!(
            context
                .webdriver_upload_files_in_context(id, &snapshot, std::slice::from_ref(&path))
                .is_err()
        );
        snapshot.frame_token = Some("b".repeat(64));
        assert!(
            context
                .webdriver_upload_files_in_context(id, &snapshot, std::slice::from_ref(&path))
                .is_err(),
            "well-formed but unregistered capability has no selected-frame authority"
        );
        snapshot.live = false;
        assert!(matches!(
            context.webdriver_upload_files_in_context(id, &snapshot, &[path]),
            Err(RuntimeError::Closed)
        ));
    }

    #[cfg(feature = "v8-host")]
    #[tokio::test]
    async fn webdriver_upload_authorization_precedes_file_access_and_retains_metadata() {
        let mut denied = ContextOptions::default();
        denied.action_policy.rules.insert(
            ConsequentialAction::FileUpload,
            crate::security::PolicyRule::Deny,
        );
        let context = Browser::in_process_with_config(BrowserConfig::default())
            .new_context_with_options(denied);
        let page = context.new_page();
        page.load_html("https://upload.test/", "<input type=file>")
            .await
            .unwrap();
        assert!(matches!(
            context.webdriver_upload_files(
                page.page_id(),
                &[std::path::PathBuf::from("/missing-oryn-upload-proof")]
            ),
            Err(RuntimeError::PolicyDenied {
                action: ConsequentialAction::FileUpload
            })
        ));
        context.close_page(page.page_id()).await.unwrap();

        let mut allowed = ContextOptions::default();
        allowed.action_policy.rules.insert(
            ConsequentialAction::FileUpload,
            crate::security::PolicyRule::Allow,
        );
        let context = Browser::in_process_with_config(BrowserConfig::default())
            .new_context_with_options(allowed);
        let page = context.new_page();
        page.load_html("https://upload.test/", "<input type=file>")
            .await
            .unwrap();
        let mut entropy = [0u8; 16];
        getrandom::fill(&mut entropy).unwrap();
        let name = format!(
            "oryn-webdriver-upload-{}.txt",
            entropy
                .iter()
                .map(|byte| format!("{byte:02x}"))
                .collect::<String>()
        );
        let path = std::env::temp_dir().join(&name);
        std::fs::write(&path, b"selected bytes").unwrap();
        let files = context
            .webdriver_upload_files(page.page_id(), std::slice::from_ref(&path))
            .unwrap();
        std::fs::remove_file(&path).unwrap();
        assert_eq!(files.len(), 1);
        assert_eq!(files[0].file.filename, name);
        assert_eq!(files[0].file.bytes, b"selected bytes");
        assert_eq!(files[0].file.media_type, "text/plain");
        assert!(files[0].last_modified > 0);
        assert!(
            context
                .webdriver_upload_files(page.page_id(), &[std::path::PathBuf::from("relative.txt")])
                .is_err()
        );
        assert!(context.webdriver_upload_files(page.page_id(), &[]).is_err());
        context.close_page(page.page_id()).await.unwrap();
    }

