mod webdriver_cancellation_regressions {
    use super::*;
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn null_timeout_pending_script_is_cancelled_before_actor_close() {
        let context = Browser::in_process_with_config(BrowserConfig::default()).new_context();
        let page = context.new_page();
        page.goto("about:blank").await.unwrap();
        let running = page.clone();
        let script = tokio::spawn(async move {
            running
                .execute_webdriver_script(crate::host::webdriver_script::ScriptRequest {
                    body: "globalThis.pendingCallback=arguments[0]"
                        .encode_utf16()
                        .collect(),
                    args: vec![],
                    asynchronous: true,
                    timeout_ms: None,
                })
                .await
        });
        tokio::time::sleep(Duration::from_millis(20)).await;
        assert!(
            !script.is_finished(),
            "null-timeout callback must remain pending"
        );
        tokio::time::timeout(Duration::from_secs(2), page.close())
            .await
            .expect("close must interrupt pending native script")
            .unwrap();
        assert!(
            tokio::time::timeout(Duration::from_secs(2), script)
                .await
                .unwrap()
                .unwrap()
                .is_err()
        );
    }
}

