mod popup_atomic_admission_tests {
    use super::*;
    #[test]
    fn stale_creator_at_registration_rolls_back_unexposed_popup_policy() {
        use oryn_js::{
            message_wire::{MessageRequest, WindowTarget},
            worker_wire::Creator,
        };
        let context = Browser::new().new_context();
        let opener = context.new_page();
        context
            .install_document_security(opener.page_id(), "https://a.test/".into(), &[])
            .unwrap();
        context
            .handle_message_wire(
                opener.page_id(),
                MessageRequest::RegisterRootDocument {
                    document_generation: 1,
                    stream_epoch: 0,
                },
            )
            .unwrap();
        let origin = context.security_origin(opener.page_id()).unwrap();
        let policy = InitialPopupPolicy {
            relaxed_domain: None,
            sandbox_navigator: false,
            target_name: String::new(),
            source_page: opener.page_id(),
            source_origin: origin.security_token_key(),
            creator: Creator::Window {
                target: WindowTarget::Root,
                document_generation: 1,
                stream_epoch: 0,
            },
            target: WindowTarget::Root,
            origin,
            policy: crate::csp::CspPolicySet::new("https://a.test/"),
            isolation: Default::default(),
            permissions: Vec::new(),
        };
        context
            .handle_message_wire(
                opener.page_id(),
                MessageRequest::RetireRootDocument {
                    document_generation: 1,
                    stream_epoch: 0,
                },
            )
            .unwrap();
        let count = context.pages().len();
        let id = PageId(NEXT_PAGE_ID.fetch_add(1, Ordering::Relaxed));
        assert!(
            context
                .create_page_with_policy(id, Some(opener.page_id()), false, true, Some(policy))
                .is_err()
        );
        assert_eq!(context.pages().len(), count);
        assert!(
            !context
                .inner
                .security_origins
                .lock()
                .unwrap()
                .contains_key(&id)
        );
        assert!(
            !context
                .inner
                .document_security
                .lock()
                .unwrap()
                .contains_key(&id)
        );
        assert!(
            !context
                .inner
                .group
                .opener_targets
                .lock()
                .unwrap()
                .contains_key(&id)
        );
        assert!(
            context
                .inner
                .group
                .browsing_groups
                .lock()
                .unwrap()
                .snapshot(id)
                .is_none()
        );
    }
}

#[cfg(unix)]
impl BrowserContext {
    /// Read-only driver diagnostic; caller-provided values never establish a
    /// process identity, native mapping holder, or executable attestation.
    pub fn execution_placement_snapshot(
        &self,
        nonce: &str,
    ) -> Result<serde_json::Value, RuntimeError> {
        if nonce.len() != 64 || !nonce.bytes().all(|byte| byte.is_ascii_hexdigit()) {
            return Err(RuntimeError::ContextService(
                "placement nonce requires 32 bytes of hex".into(),
            ));
        }
        let mut capture = [0u8; 32];
        getrandom::fill(&mut capture)
            .map_err(|error| RuntimeError::ContextService(error.to_string()))?;
        let pages =
            self.inner.group.pages.lock().map_err(|_| {
                RuntimeError::ContextService("placement page registry poisoned".into())
            })?;
        let agents = self.inner.agents.lock().map_err(|_| {
            RuntimeError::ContextService("placement agent registry poisoned".into())
        })?;
        let memory = self.inner.group.shared_memory.lock().map_err(|_| {
            RuntimeError::ContextService("placement shared memory registry poisoned".into())
        })?;
        let pages=pages.iter().filter(|(_,record)|record.is_live()).map(|(id,record)|{
            let placement=match &record.handle.worker{
                Some(worker)=>worker.client.try_lock().ok().and_then(|client|client.as_ref().and_then(|client|client.execution_placement())),
                None=>Some(crate::execution_placement::ExecutionPlacement::thread()),
            };
            serde_json::json!({"id":id.0,"url":record.descriptor.page.url,"placement":placement})
        }).collect::<Vec<_>>();
        Ok(
            serde_json::json!({"schema":1,"nonce":nonce,"capture_id":crate::execution_placement::fingerprint(&capture),"parent_pid":std::process::id(),
            "pages":pages,"agents":agents.execution_placements(),"shared_backings":memory.execution_placements()}),
        )
    }
}

#[cfg(all(test, unix))]
mod execution_placement_tests {
    use super::*;
    #[test]
    fn native_snapshot_is_nonce_bound_and_never_exports_mapping_capabilities() {
        let context = Browser::new().new_context();
        let page = context.new_page();
        let id = page.page_id();
        assert!(context.execution_placement_snapshot("forged").is_err());
        let owner = crate::agent_registry::AgentOwner::Window {
            page: id,
            target: oryn_js::message_wire::WindowTarget::Root,
            generation: 1,
            epoch: 0,
        };
        let descriptor = {
            let mut registry = context.inner.group.shared_memory.lock().unwrap();
            registry
                .admit_root(owner.clone(), "test-native-origin".into())
                .unwrap();
            registry
                .allocate(crate::shared_memory::SharedAllocationInputs {
                    owner: &owner,
                    byte_length: 4,
                    maximum_length: None,
                    granularity: 4096,
                    guard_length: 0,
                    wasm: false,
                    memory64: false,
                })
                .unwrap()
                .0
        };
        let nonce = "a".repeat(64);
        let snapshot = context.execution_placement_snapshot(&nonce).unwrap();
        assert_eq!(snapshot["nonce"], nonce);
        assert_eq!(snapshot["parent_pid"], std::process::id());
        let encoded = serde_json::to_string(&snapshot).unwrap();
        let secret = descriptor
            .token
            .0
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>();
        assert!(!encoded.contains(&secret));
        assert!(!encoded.contains("secret"));
        assert_eq!(snapshot["shared_backings"][0]["holders"][0]["id"], id.0);
        assert_eq!(
            snapshot["shared_backings"][0]["backing_sha256"],
            crate::execution_placement::fingerprint(&descriptor.token.0)
        );
    }
}

#[cfg(all(test, unix))]
mod form_popup_relationship_regressions {
    use super::*;
    #[test]
    fn noopener_popup_has_fresh_group_and_no_opener_from_initial_registration() {
        use oryn_js::{
            message_wire::{MessageRequest, WindowTarget},
            worker_wire::Creator,
        };
        let context = Browser::new().new_context();
        let source = context.new_page();
        let id = source.page_id();
        context
            .install_document_security(id, "https://forms.test/".into(), &[])
            .unwrap();
        context
            .handle_message_wire(
                id,
                MessageRequest::RegisterRootDocument {
                    document_generation: 1,
                    stream_epoch: 0,
                },
            )
            .unwrap();
        let creator = Creator::Window {
            target: WindowTarget::Root,
            document_generation: 1,
            stream_epoch: 0,
        };
        let isolated = context
            .new_named_popup_from_creator(id, &creator, true, "receipt".into())
            .unwrap();
        assert_eq!(
            context
                .inner
                .group
                .pages
                .lock()
                .unwrap()
                .get(&isolated.page_id())
                .unwrap()
                .target_name,
            ""
        );
        assert!(
            context
                .inner
                .group
                .pages
                .lock()
                .unwrap()
                .get(&isolated.page_id())
                .unwrap()
                .sandbox_navigator
                .is_none()
        );
        let connected = context
            .new_popup_from_creator_with_opener(id, &creator, false)
            .unwrap();
        let pages = context.pages();
        assert_eq!(
            pages
                .iter()
                .find(|page| page.page.page_id == isolated.page_id())
                .unwrap()
                .page
                .opener_page_id,
            None
        );
        assert_eq!(
            pages
                .iter()
                .find(|page| page.page.page_id == connected.page_id())
                .unwrap()
                .page
                .opener_page_id,
            Some(id)
        );
        let groups = context.inner.group.browsing_groups.lock().unwrap();
        assert!(!groups.related(id, isolated.page_id(), None));
        assert!(groups.related(id, connected.page_id(), None));
        drop(groups);
        assert!(
            !context
                .inner
                .group
                .opener_targets
                .lock()
                .unwrap()
                .contains_key(&isolated.page_id())
        );
        assert_eq!(
            context.page_origin(isolated.page_id()).unwrap(),
            "https://forms.test"
        );
        context
            .handle_message_wire(
                id,
                MessageRequest::RetireRootDocument {
                    document_generation: 1,
                    stream_epoch: 0,
                },
            )
            .unwrap();
        assert!(
            context
                .new_popup_from_creator_with_opener(id, &creator, true)
                .is_err()
        );
    }
}

