    #[test]
    fn authored_context_traces_cannot_change_native_network_idle() {
        let mut page = page();
        let quiet = Instant::now()
            .checked_sub(NETWORK_IDLE_QUIET_PERIOD)
            .unwrap();
        page.network_quiet_since = Some(quiet);
        page.executable.as_mut().unwrap().evaluate("globalThis.__oryn_take_context_trace=()=>[{kind:'request_started',detail:{method:'GET',url:'https://unrelated.test/'}}]").unwrap();
        page.poll_page_tasks().unwrap();
        assert_eq!(page.network_quiet_since, Some(quiet));
        assert!(
            page.wait_satisfied(&WaitPredicate::Lifecycle(LifecycleState::NetworkIdle))
                .unwrap()
        );
        page.executable.as_mut().unwrap().evaluate("globalThis.__oryn_take_context_trace=()=>[{kind:'response_received',detail:{url:'https://unrelated.test/',status:200}}]").unwrap();
        page.poll_page_tasks().unwrap();
        assert_eq!(
            page.network_quiet_since,
            Some(quiet),
            "diagnostic response events cannot restart the quiet interval"
        );
    }

    #[test]
    fn selected_frame_network_idle_tracks_its_body_without_blocking_siblings() {
        struct Buffered;
        impl crate::network::NetworkBroker for Buffered {
            fn send(
                &self,
                request: crate::network::NetworkRequest,
            ) -> Result<crate::network::NetworkResponse, crate::network::NetworkError> {
                Ok(crate::network::NetworkResponse {
                    response_policy: None,
                    timing: None,
                    request_id: request.request_id,
                    status: 200,
                    headers: vec![],
                    body: vec![1],
                })
            }
        }
        let mut page = PageState::new(
            PageId(904),
            None,
            BrowserConfig::default(),
            ContextOptions::default(),
            Some(SharedNetworkBroker::new(Buffered)),
            #[cfg(unix)]
            None,
        );
        page.bind_direct_fixture_terminal_owner();
        page.load_document(
            "https://semantics.test/frames".into(),
            "<iframe srcdoc='<p>First</p>'></iframe><iframe srcdoc='<p>Second</p>'></iframe>",
            None,
            None,
            HistoryUpdate::Push,
            &BTreeMap::new(),
            Vec::new(),
        )
        .unwrap();
        page.poll_page_tasks().unwrap();
        let frames = page
            .executable
            .as_ref()
            .unwrap()
            .automation_realms()
            .into_iter()
            .filter(|entry| entry.live && entry.parent_realm.is_some())
            .collect::<Vec<_>>();
        assert_eq!(frames.len(), 2);
        for scope in &frames {
            page.scoped_worker_request(
                scope.clone(),
                crate::worker::WorkerRequest::Observe { profile: None },
            )
            .unwrap();
        }
        let quiet = Instant::now()
            .checked_sub(NETWORK_IDLE_QUIET_PERIOD)
            .unwrap();
        for frame in page.frame_states.values_mut() {
            frame.network_quiet_since = Some(quiet);
        }
        let executable = page.executable.as_mut().unwrap();
        executable
            .set_automation_scope(Some(frames[0].clone()))
            .unwrap();
        let broker = executable.selected_network_broker().unwrap();
        executable.set_automation_scope(None).unwrap();
        let mut response = broker
            .start_stream(crate::network::NetworkRequest {
                request_id: 1,
                method: "GET".into(),
                url: "https://semantics.test/body".into(),
                headers: vec![],
                body: vec![],
                credentials: false,
                resolved_addrs: vec![],
                security: Default::default(),
            })
            .unwrap();
        let wait = |timeout_ms| crate::worker::WorkerRequest::WaitForUntil {
            predicate: WaitPredicate::Lifecycle(LifecycleState::NetworkIdle),
            timeout_ms: Some(timeout_ms),
        };
        assert!(matches!(
            page.scoped_worker_request(frames[0].clone(), wait(0)),
            Err(RuntimeError::WaitUnsatisfied(_))
        ));
        assert!(matches!(
            page.scoped_worker_request(frames[1].clone(), wait(0))
                .unwrap(),
            crate::worker::WorkerResponse::Satisfied
        ));
        let native_stages = loading_stage_diagnostics::Guard::wait(page.page_id.0, &frames[0]);
        let eof_started = Instant::now();
        let mut bytes = Vec::new();
        std::io::Read::read_to_end(&mut response.body, &mut bytes).unwrap();
        assert_eq!(bytes, vec![1]);
        let activity_after_eof = broker.owned_operation_activity();
        // EOF is real; only the decision clock is fixed so expensive native
        // checkpoints cannot silently consume this negative quiet interval.
        let clock =
            network_idle_test_clock::Guard::at(activity_after_eof.1.expect("EOF activity time"));
        let idle_probe = page.scoped_worker_request(frames[0].clone(), wait(0));
        assert!(
            matches!(idle_probe, Err(RuntimeError::WaitUnsatisfied(_))),
            "EOF begins a new quiet interval; eof_started={eof_started:?}, eof_elapsed={:?}, active={}, activity_after_eof={:?}, quiet_period={:?}, native_stages={:?}",
            eof_started.elapsed(),
            activity_after_eof.0,
            activity_after_eof
                .1
                .map(|changed| (changed >= eof_started, changed.elapsed())),
            NETWORK_IDLE_QUIET_PERIOD,
            native_stages.snapshot()
        );
        drop(clock);
        assert!(matches!(
            page.scoped_worker_request(frames[0].clone(), wait(2000))
                .unwrap(),
            crate::worker::WorkerResponse::Satisfied
        ));
    }

    #[test]
    fn selected_frame_projection_does_not_reuse_a_different_document_authority() {
        let mut page = page();
        // The shared page() constructor already owns publication authority.
        page.load_document(
            "https://semantics.test/frames".into(),
            "<iframe srcdoc='<button>Frame</button>'></iframe>",
            None,
            None,
            HistoryUpdate::Push,
            &BTreeMap::new(),
            Vec::new(),
        )
        .unwrap();
        page.poll_page_tasks().unwrap();
        let scope = page
            .executable
            .as_ref()
            .unwrap()
            .automation_realms()
            .into_iter()
            .find(|entry| entry.parent_realm.is_some() && entry.live)
            .unwrap();
        page.scoped_worker_request(
            scope.clone(),
            crate::worker::WorkerRequest::Observe { profile: None },
        )
        .unwrap();
        let key = (
            page.document_generation,
            scope.realm.0,
            scope.document_generation,
            scope.stream_epoch,
        );
        let cached = page.frame_states.get_mut(&key).unwrap();
        let old_generation = cached.document_generation;
        cached
            .frame_scope
            .as_mut()
            .unwrap()
            .document_authority_epoch += 1;
        page.scoped_worker_request(
            scope.clone(),
            crate::worker::WorkerRequest::Observe { profile: None },
        )
        .unwrap();
        let current = page.frame_states.get(&key).unwrap();
        assert!(
            current.document_generation > old_generation,
            "authority changes discard old semantic and layout projections even when the cache key matches"
        );
        assert!(
            current
                .frame_scope
                .as_ref()
                .unwrap()
                .same_document_as(&scope)
        );
    }

    #[test]
    fn parked_document_body_activity_returns_with_its_broker_on_restore() {
        struct Buffered;
        impl crate::network::NetworkBroker for Buffered {
            fn send(
                &self,
                request: crate::network::NetworkRequest,
            ) -> Result<crate::network::NetworkResponse, crate::network::NetworkError> {
                Ok(crate::network::NetworkResponse {
                    response_policy: None,
                    timing: None,
                    request_id: request.request_id,
                    status: 200,
                    headers: Vec::new(),
                    body: vec![1],
                })
            }
        }
        let mut page = PageState::new(
            PageId(903),
            None,
            BrowserConfig::default(),
            ContextOptions::default(),
            Some(SharedNetworkBroker::new(Buffered)),
            #[cfg(unix)]
            None,
        );
        page.bind_direct_fixture_terminal_owner();
        page.load_document(
            "https://semantics.test/first".into(),
            "<p>first</p>",
            None,
            None,
            HistoryUpdate::Push,
            &BTreeMap::new(),
            Vec::new(),
        )
        .unwrap();
        let original = page.broker.clone().unwrap();
        let mut response = original
            .start_stream(crate::network::NetworkRequest {
                request_id: 1,
                method: "GET".into(),
                url: "https://semantics.test/body".into(),
                headers: Vec::new(),
                body: Vec::new(),
                credentials: false,
                security: Default::default(),
                resolved_addrs: Vec::new(),
            })
            .unwrap();
        assert_eq!(original.owned_operation_activity().0, 1);
        let mut rejected = BTreeMap::new();
        rejected.insert(
            "oryn:frame-history".into(),
            "invalid native snapshot".into(),
        );
        assert!(
            page.load_document(
                "https://semantics.test/rejected".into(),
                "<p>rejected</p>",
                None,
                None,
                HistoryUpdate::Push,
                &rejected,
                Vec::new()
            )
            .is_err()
        );
        assert_eq!(
            page.broker.as_ref().unwrap().owned_operation_activity(),
            original.owned_operation_activity(),
            "rollback restores the original request owner"
        );
        page.load_document(
            "https://semantics.test/second".into(),
            "<p>second</p>",
            None,
            None,
            HistoryUpdate::Push,
            &BTreeMap::new(),
            Vec::new(),
        )
        .unwrap();
        page.network_quiet_since = Some(
            Instant::now()
                .checked_sub(NETWORK_IDLE_QUIET_PERIOD)
                .unwrap(),
        );
        let predicate = WaitPredicate::Lifecycle(LifecycleState::NetworkIdle);
        assert_eq!(
            page.broker.as_ref().unwrap().owned_operation_activity().0,
            0
        );
        assert!(
            page.wait_satisfied(&predicate).unwrap(),
            "parked body's ownership must not block the active document"
        );
        assert_eq!(
            original.owned_operation_activity().0,
            1,
            "parking retains transport ownership"
        );
        page.restore_cached_document(0, "https://semantics.test/first".into())
            .unwrap()
            .unwrap();
        assert_eq!(
            page.broker.as_ref().unwrap().owned_operation_activity().0,
            1
        );
        assert!(!page.wait_satisfied(&predicate).unwrap());
        let mut body = Vec::new();
        std::io::Read::read_to_end(&mut response.body, &mut body).unwrap();
        assert_eq!(body, vec![1]);
        assert_eq!(
            page.broker.as_ref().unwrap().owned_operation_activity(),
            original.owned_operation_activity()
        );
        page.wait_for_timeout(
            &predicate,
            Some(NETWORK_IDLE_QUIET_PERIOD + Duration::from_secs(2)),
        )
        .unwrap();
    }

    #[test]
    fn cached_document_restoration_requires_a_fresh_network_quiet_interval() {
        let mut page = page();
        let original_url = page.url.clone();
        let old = Instant::now()
            .checked_sub(NETWORK_IDLE_QUIET_PERIOD)
            .unwrap();
        page.network_quiet_since = Some(old);
        page.lifecycle.push(LifecycleState::NetworkIdle);
        page.executable
            .as_mut()
            .unwrap()
            .execute("globalThis.restoredCount=0;onpageshow=e=>{if(e.persisted)restoredCount++}")
            .unwrap();
        page.load_document(
            "https://semantics.test/next".into(),
            "<p>next</p>",
            None,
            None,
            HistoryUpdate::Push,
            &BTreeMap::new(),
            Vec::new(),
        )
        .unwrap();
        let restoration = Instant::now();
        page.restore_cached_document(0, original_url)
            .unwrap()
            .unwrap();
        assert!(page.network_quiet_since.is_some_and(|at| at >= restoration));
        assert!(
            page.lifecycle.contains(&LifecycleState::NetworkIdle),
            "the cached lifecycle can retain historical events"
        );
        let predicate = WaitPredicate::Lifecycle(LifecycleState::NetworkIdle);
        assert!(
            !page.wait_satisfied(&predicate).unwrap(),
            "historical idle does not satisfy the restored document wait"
        );
        assert_eq!(
            page.executable
                .as_mut()
                .unwrap()
                .evaluate("String(restoredCount)")
                .unwrap(),
            "1"
        );
        page.wait_for_timeout(
            &predicate,
            Some(NETWORK_IDLE_QUIET_PERIOD + Duration::from_secs(2)),
        )
        .unwrap();
    }

    #[test]
    fn standalone_network_idle_tracks_body_completion_without_sibling_activity() {
        struct Buffered;
        impl crate::network::NetworkBroker for Buffered {
            fn send(
                &self,
                request: crate::network::NetworkRequest,
            ) -> Result<crate::network::NetworkResponse, crate::network::NetworkError> {
                Ok(crate::network::NetworkResponse {
                    response_policy: None,
                    timing: None,
                    request_id: request.request_id,
                    status: 200,
                    headers: Vec::new(),
                    body: vec![1],
                })
            }
        }
        let transport = SharedNetworkBroker::new(Buffered);
        let mut first = PageState::new(
            PageId(901),
            None,
            BrowserConfig::default(),
            ContextOptions::default(),
            Some(transport.clone()),
            #[cfg(unix)]
            None,
        );
        let mut sibling = PageState::new(
            PageId(902),
            None,
            BrowserConfig::default(),
            ContextOptions::default(),
            Some(transport),
            #[cfg(unix)]
            None,
        );
        let old = Instant::now()
            .checked_sub(NETWORK_IDLE_QUIET_PERIOD)
            .unwrap();
        first.network_quiet_since = Some(old);
        sibling.network_quiet_since = Some(old);
        let predicate = WaitPredicate::Lifecycle(LifecycleState::NetworkIdle);
        assert!(first.wait_satisfied(&predicate).unwrap());
        let mut response = first
            .broker
            .as_ref()
            .unwrap()
            .start_stream(crate::network::NetworkRequest {
                request_id: 1,
                method: "GET".into(),
                url: "https://example.test/body".into(),
                headers: Vec::new(),
                body: Vec::new(),
                credentials: false,
                security: Default::default(),
                resolved_addrs: Vec::new(),
            })
            .unwrap();
        assert!(!first.wait_satisfied(&predicate).unwrap());
        assert!(
            sibling.wait_satisfied(&predicate).unwrap(),
            "shared transport does not share a page's quiet interval"
        );
        let mut byte = [0];
        assert_eq!(
            std::io::Read::read(&mut response.body, &mut byte).unwrap(),
            1
        );
        let completed = Instant::now();
        assert_eq!(
            std::io::Read::read(&mut response.body, &mut byte).unwrap(),
            0
        );
        let (active, changed) = first.broker.as_ref().unwrap().owned_operation_activity();
        assert_eq!(active, 0);
        assert!(changed.is_some_and(|at| at >= completed));
        assert!(
            !first.wait_satisfied(&predicate).unwrap(),
            "body completion restarts quiet even with no pending host promise"
        );
        assert!(sibling.wait_satisfied(&predicate).unwrap());
        first.network_quiet_since = None;
        first
            .wait_for_timeout(
                &predicate,
                Some(NETWORK_IDLE_QUIET_PERIOD + Duration::from_secs(2)),
            )
            .unwrap();
        assert!(
            first.wait_satisfied(&predicate).unwrap(),
            "native terminal activity recovers a missing response trace timestamp"
        );
    }

    #[test]
    fn async_fetch_quiet_period_tracks_overlap_and_single_checkpoint_activity() {
        let mut page = page();
        let old = Instant::now()
            .checked_sub(NETWORK_IDLE_QUIET_PERIOD)
            .unwrap();
        page.network_quiet_since = Some(old);
        page.reconcile_async_fetch_activity(Some((2, true)), Some((3, true)));
        assert!(
            page.network_quiet_since.is_none(),
            "a remaining request prevents quiet"
        );
        let completed = Instant::now();
        page.reconcile_async_fetch_activity(Some((3, true)), Some((3, false)));
        assert!(
            page.network_quiet_since
                .is_some_and(|since| since >= completed)
        );
        page.network_quiet_since = Some(old);
        let admitted = Instant::now();
        page.reconcile_async_fetch_activity(Some((3, false)), Some((4, false)));
        assert!(
            page.network_quiet_since
                .is_some_and(|since| since >= admitted),
            "short request still restarts quiet"
        );
        let quiet = page.network_quiet_since;
        page.reconcile_async_fetch_activity(Some((4, false)), Some((4, false)));
        assert_eq!(
            page.network_quiet_since, quiet,
            "inactive polling must not restart quiet"
        );
    }

    #[test]
    fn failed_synchronous_resource_restarts_network_quiet_period() {
        let mut page = page();
        let old_quiet = Instant::now()
            .checked_sub(NETWORK_IDLE_QUIET_PERIOD)
            .unwrap();
        page.network_quiet_since = Some(old_quiet);
        page.broker = None;
        assert!(
            page.fetch_external_resource_response(
                Url::parse("https://semantics.test/missing").unwrap(),
                "*/*",
                "image"
            )
            .is_err()
        );
        assert_eq!(
            page.network_quiet_since,
            Some(old_quiet),
            "missing transport never starts a request"
        );
        page.broker = Some(SharedNetworkBroker::new(crate::network::UnavailableBroker));
        let started = Instant::now();
        assert!(
            page.fetch_external_resource_response(
                Url::parse("https://semantics.test/missing").unwrap(),
                "*/*",
                "image"
            )
            .is_err()
        );
        assert!(
            page.network_quiet_since
                .is_some_and(|since| since >= started)
        );
        assert!(
            !page
                .wait_satisfied(&WaitPredicate::Lifecycle(LifecycleState::NetworkIdle))
                .unwrap()
        );
    }

    #[test]
    fn network_idle_wait_drives_timers_and_does_not_reuse_old_idle_flag() {
        let mut page = page();
        let delay = (NETWORK_IDLE_QUIET_PERIOD.as_millis() / 2).max(1);
        page.executable.as_mut().unwrap().evaluate(&format!("setTimeout(()=>document.querySelector('#b').textContent='Idle timer delivered',{delay});'scheduled'")).unwrap();
        page.network_quiet_since = Some(Instant::now());
        page.lifecycle.push(LifecycleState::NetworkIdle);
        assert!(
            !page
                .wait_satisfied(&WaitPredicate::Lifecycle(LifecycleState::NetworkIdle))
                .unwrap()
        );
        page.wait_for_timeout(
            &WaitPredicate::Lifecycle(LifecycleState::NetworkIdle),
            Some(NETWORK_IDLE_QUIET_PERIOD + Duration::from_secs(2)),
        )
        .unwrap();
        assert!(
            page.observation(ProjectionProfile::Full)
                .nodes
                .iter()
                .any(|node| node.name == "Idle timer delivered"),
            "wait must publish timer effects before returning, without a later evaluation checkpoint"
        );
        page.network_quiet_since = None;
        assert!(
            !page
                .wait_satisfied(&WaitPredicate::Lifecycle(LifecycleState::NetworkIdle))
                .unwrap()
        );
        assert!(matches!(
            page.wait_for_timeout(
                &WaitPredicate::Lifecycle(LifecycleState::NetworkIdle),
                Some(Duration::ZERO)
            ),
            Err(RuntimeError::WaitUnsatisfied(_))
        ));
    }

    #[test]
    fn retained_semantic_replacement_keeps_one_action_and_respects_cancellation() {
        let mut page = page();
        page.executable.as_mut().unwrap().evaluate("document.body.insertAdjacentHTML('beforeend','<input id=edit value=old>');globalThis.events=[];const edit=document.getElementById('edit');for(const name of ['beforeinput','input','change'])edit.addEventListener(name,()=>events.push(name));'ready'").unwrap();
        page.sync_executable_semantics().unwrap();
        page.refresh_layout().unwrap();
        let target = page
            .resolve_selector("#edit", SemanticAction::Type)
            .unwrap();
        let before = page.action_ids.last();
        let result = page
            .execute(NativeAction {
                target,
                action: SemanticAction::Type,
                value: Some("new😀".into()),
            })
            .unwrap();
        assert_eq!(result.action_id.0, before + 1);
        assert_eq!(page.action_ids.last(), before + 1);
        assert_eq!(
            page.executable
                .as_mut()
                .unwrap()
                .evaluate("JSON.stringify([document.getElementById('edit').value,events])")
                .unwrap(),
            "[\"new😀\",[\"beforeinput\",\"input\",\"change\"]]"
        );
        page.executable.as_mut().unwrap().evaluate("events.length=0;document.getElementById('edit').addEventListener('beforeinput',e=>e.preventDefault(),{once:true});'ready'").unwrap();
        let target = page
            .resolve_selector("#edit", SemanticAction::Clear)
            .unwrap();
        assert!(
            page.execute(NativeAction {
                target,
                action: SemanticAction::Clear,
                value: None
            })
            .is_err()
        );
        assert_eq!(page.action_ids.last(), before + 2);
        assert_eq!(
            page.executable
                .as_mut()
                .unwrap()
                .evaluate("JSON.stringify([document.getElementById('edit').value,events])")
                .unwrap(),
            "[\"new😀\",[\"beforeinput\"]]"
        );
    }

    #[test]
    fn snapshot_failure_before_dispatch_has_no_action_identity_or_callback() {
        let mut page = page();
        page.executable
            .as_mut()
            .unwrap()
            .evaluate(
                "globalThis.clicks=0;document.querySelector('#b').onclick=()=>clicks++;'ready'",
            )
            .unwrap();
        let target = page.resolve_selector("#b", SemanticAction::Click).unwrap();
        let previous = page.action_ids.last();
        let fault = Fault::at(Stage::Snapshot);
        let error = page
            .execute_in_realm(
                NativeAction {
                    target,
                    action: SemanticAction::Click,
                    value: None,
                },
                false,
            )
            .unwrap_err();
        drop(fault);
        assert_eq!(
            error,
            RuntimeError::Semantic("injected Snapshot failure".into())
        );
        assert_eq!(page.action_ids.last(), previous);
        assert_eq!(
            page.executable
                .as_mut()
                .unwrap()
                .evaluate("String(clicks)")
                .unwrap(),
            "0"
        );
    }

    #[test]
    fn action_failure_after_dispatch_keeps_identity_and_does_not_masquerade_as_stale() {
        let mut page = page();
        page.executable.as_mut().unwrap().evaluate("globalThis.clicks=0;document.querySelector('#b').onclick=()=>{clicks++;document.querySelector('#b').textContent='Changed';};'ready'").unwrap();
        let target = page.resolve_selector("#b", SemanticAction::Click).unwrap();
        let previous = page.action_ids.last();
        // The first snapshot is preflight. Fail the snapshot after dispatch.
        let fault = Fault::after(Stage::Snapshot, 1);
        let error = page
            .execute_in_realm(
                NativeAction {
                    target,
                    action: SemanticAction::Click,
                    value: None,
                },
                false,
            )
            .unwrap_err();
        drop(fault);
        let RuntimeError::ActionExecutionFailed { action_id, .. } = &error else {
            panic!("unexpected action failure: {error:?}")
        };
        assert_eq!(*action_id, ActionId(previous + 1));
        assert_eq!(page.action_ids.last(), previous + 1);
        assert_eq!(
            serde_json::from_str::<RuntimeError>(&serde_json::to_string(&error).unwrap()).unwrap(),
            error
        );
        assert_eq!(
            page.executable
                .as_mut()
                .unwrap()
                .evaluate("String(clicks)")
                .unwrap(),
            "1"
        );
        page.refresh_semantic_observation().unwrap();
        let result = page
            .execute_in_realm(
                NativeAction {
                    target,
                    action: SemanticAction::Click,
                    value: None,
                },
                false,
            )
            .unwrap();
        assert_eq!(result.action_id, ActionId(previous + 2));
        assert_eq!(
            page.executable
                .as_mut()
                .unwrap()
                .evaluate("String(clicks)")
                .unwrap(),
            "2"
        );
        page.action_ids.set_last(u64::MAX);
        assert!(matches!(
            page.execute_in_realm(
                NativeAction {
                    target,
                    action: SemanticAction::Click,
                    value: None
                },
                false
            ),
            Err(RuntimeError::IdentityExhausted { .. })
        ));
        assert_eq!(
            page.executable
                .as_mut()
                .unwrap()
                .evaluate("String(clicks)")
                .unwrap(),
            "2"
        );
    }

    #[test]
    fn snapshot_and_control_failures_retain_mutations_and_publish_no_partial_graph() {
        for stage in [Stage::Snapshot, Stage::Controls] {
            let mut page = page();
            let before = page.observation(ProjectionProfile::Full);
            page.executable.as_mut().unwrap().evaluate("document.querySelector('#b').textContent='After';document.querySelector('#i').value='ready';'changed'").unwrap();
            let batch = page.executable.as_ref().unwrap().semantic_mutations();
            assert!(!batch.mutations.is_empty());
            let failure = Fault::at(stage);
            assert!(matches!(
                page.refresh_semantic_observation(),
                Err(RuntimeError::Semantic(_))
            ));
            assert_eq!(
                page.executable.as_ref().unwrap().semantic_mutations(),
                batch,
                "failed projection does not advance semantic cursor"
            );
            assert_eq!(
                page.observation(ProjectionProfile::Full).nodes,
                before.nodes,
                "staged names/control state are not published"
            );
            assert_eq!(page.revision, before.revision.0);
            drop(failure);
            page.refresh_semantic_observation().unwrap();
            let after = page.observation(ProjectionProfile::Full);
            assert_eq!(after.revision, Revision(before.revision.0 + 1));
            assert!(
                after
                    .nodes
                    .iter()
                    .any(|node| node.role == "button" && node.name == "After")
            );
            assert!(after.nodes.iter().any(|node| {
                node.role == "textbox"
                    && node
                        .validation
                        .as_ref()
                        .is_some_and(|state| state.valid && !state.value_missing)
            }));
            assert!(
                page.executable
                    .as_ref()
                    .unwrap()
                    .semantic_mutations()
                    .mutations
                    .is_empty()
            );
            assert!(!page.semantic_publication_pending);
            assert!(
                page.delta_from(before.revision)
                    .unwrap()
                    .upserted
                    .iter()
                    .any(|node| node.name == "After")
            );
            page.refresh_semantic_observation().unwrap();
            assert_eq!(page.revision, after.revision.0);
        }
    }
    #[test]
    fn failed_lifecycle_publication_retains_emitter_and_projection_batch() {
        use crate::navigation_control::{
            NavigationCommand, NavigationControl, NavigationEmitter, NavigationRequest,
            NavigationStop, PageLoadStrategy,
        };
        for complete in [false, true] {
            let mut page = page();
            page.pending_navigation_response = None;
            assert!(page.executable.as_ref().unwrap().document_interactive());
            assert!(page.executable.as_ref().unwrap().document_load_complete());
            let control = NavigationControl::default();
            let job = control
                .begin(NavigationRequest {
                    command: NavigationCommand::Navigate {
                        url: page.url.clone(),
                    },
                    strategy: PageLoadStrategy::Normal,
                    timeout_ms: None,
                })
                .unwrap();
            job.started().unwrap();
            job.committed(page.document_generation, page.url.clone())
                .unwrap();
            if complete {
                job.interactive(page.document_generation).unwrap();
            }
            job.stop(NavigationStop::Cancelled).unwrap();
            let emitter = NavigationEmitter::Local(job);
            page.active_navigation = Some(emitter.clone());
            page.navigation_committed = true;
            page.lifecycle = if complete {
                vec![LifecycleState::DomContentLoaded]
            } else {
                Vec::new()
            };
            page.executable
                .as_mut()
                .unwrap()
                .evaluate("document.querySelector('#b').textContent='Not published';'changed'")
                .unwrap();
            let batch = page.executable.as_ref().unwrap().semantic_mutations();
            let before = page.observation(ProjectionProfile::Full);
            assert!(matches!(
                page.sync_executable_semantics(),
                Err(RuntimeError::Network(_))
            ));
            assert!(
                page.active_navigation
                    .as_ref()
                    .is_some_and(|active| active.same_job(&emitter))
            );
            assert!(page.navigation_committed);
            assert!(!page.lifecycle.contains(&LifecycleState::Load));
            assert_eq!(
                page.lifecycle.contains(&LifecycleState::DomContentLoaded),
                complete
            );
            assert_eq!(
                page.executable.as_ref().unwrap().semantic_mutations(),
                batch
            );
            assert_eq!(
                page.observation(ProjectionProfile::Full).nodes,
                before.nodes
            );
        }
    }
    #[test]
    fn actor_observation_returns_typed_projection_error_instead_of_stale_success() {
        let mut page = page();
        let owner = Browser::new().new_context();
        let (sender, _receiver) = mpsc::channel(1);
        let mut navigations = Vec::new();
        let mut captures = VecDeque::new();
        for semantic in [false, true] {
            let fault = Fault::at(Stage::Snapshot);
            if semantic {
                let (reply, mut response) = oneshot::channel();
                super::page_actor_turn::dispatch(
                    &mut page,
                    PageCommand::ObserveSemantic {
                        profile: ProjectionProfile::Full,
                        reply,
                    },
                    &owner,
                    &mut navigations,
                    &mut captures,
                    &sender.downgrade(),
                );
                assert!(matches!(
                    response.try_recv().unwrap(),
                    Err(RuntimeError::Semantic(_))
                ));
            } else {
                let (reply, mut response) = oneshot::channel();
                super::page_actor_turn::dispatch(
                    &mut page,
                    PageCommand::Observe {
                        profile: ProjectionProfile::Full,
                        reply,
                    },
                    &owner,
                    &mut navigations,
                    &mut captures,
                    &sender.downgrade(),
                );
                assert!(matches!(
                    response.try_recv().unwrap(),
                    Err(RuntimeError::Semantic(_))
                ));
            }
            drop(fault);
        }
    }
