#[cfg(all(test, unix))]
std::thread_local! {static WEBDRIVER_COOKIE_ADMISSION_FAULT:std::cell::Cell<u8>=const{std::cell::Cell::new(0)};}
#[cfg(all(test, unix))]
fn webdriver_cookie_admission_fault(context: &BrowserContext, page: PageId) {
    match WEBDRIVER_COOKIE_ADMISSION_FAULT.with(|fault| fault.replace(0)) {
        1 => {
            context.inner.group.close(page);
        }
        2 => {
            context
                .commit_page_url(page, "https://cookies.test/second/path".into())
                .unwrap();
        }
        _ => {}
    }
}

#[cfg(test)]
mod extraction_text_source_tests {
    use super::*;
    #[test]
    fn parser_only_actions_share_page_allocator_and_new_pages_restart() {
        fn driver(page_id: PageId, ids: PageActionIds) -> (PageState, SemanticRef) {
            let mut page = PageState::new(
                page_id,
                None,
                BrowserConfig::default(),
                ContextOptions::default(),
                None,
                #[cfg(all(unix, feature = "v8-host"))]
                None,
            );
            page.action_ids = ids;
            let parsed = crate::html::parse("<input value=original>");
            let node = parsed.dom.iter().find_map(|(id, node)| matches!(&node.kind, crate::dom::NodeKind::Element { name } if name.local.as_ref()=="input").then_some(id)).unwrap();
            let target = SemanticRef {
                page_id,
                document_generation: page.document_generation,
                node: (u64::from(node.generation) << 32) | u64::from(node.slot),
            };
            page.document = Some(parsed);
            (page, target)
        }
        let ids = PageActionIds::default();
        let (mut root, root_target) = driver(PageId(708), ids.clone());
        let (mut frame, frame_target) = driver(PageId(708), ids.clone());
        for (expected, selected, target, sensitive) in [
            (1, &mut root, root_target, false),
            (2, &mut frame, frame_target, true),
        ] {
            let result = selected
                .execute_with_interactability(
                    NativeAction {
                        target,
                        action: SemanticAction::Type,
                        value: Some("changed".into()),
                    },
                    false,
                    sensitive,
                )
                .unwrap();
            assert_eq!(result.action_id, ActionId(expected));
        }
        let (mut replacement, target) = driver(PageId(708), ids);
        assert_eq!(
            replacement
                .execute_with_interactability(
                    NativeAction {
                        target,
                        action: SemanticAction::Clear,
                        value: None
                    },
                    false,
                    false
                )
                .unwrap()
                .action_id,
            ActionId(3)
        );
        let (mut independent, target) = driver(PageId(709), PageActionIds::default());
        assert_eq!(
            independent
                .execute_with_interactability(
                    NativeAction {
                        target,
                        action: SemanticAction::Type,
                        value: Some("new".into())
                    },
                    false,
                    false
                )
                .unwrap()
                .action_id,
            ActionId(1)
        );
    }
    #[test]
    fn parser_only_action_counters_exhaust_before_mutation() {
        for action_exhausted in [false, true] {
            let mut page = PageState::new(
                PageId(708),
                None,
                BrowserConfig::default(),
                ContextOptions::default(),
                None,
                #[cfg(all(unix, feature = "v8-host"))]
                None,
            );
            let parsed = crate::html::parse("<input value=original>");
            let node=parsed.dom.iter().find_map(|(id,node)|matches!(&node.kind,crate::dom::NodeKind::Element{name} if name.local.as_ref()=="input").then_some(id)).unwrap();
            let original = parsed.dom.get(node).unwrap().clone();
            page.document = Some(parsed);
            if action_exhausted {
                page.action_ids.set_last(u64::MAX);
            } else {
                page.revision = u64::MAX;
            }
            let before = (page.action_ids.last(), page.revision);
            let target = SemanticRef {
                page_id: page.page_id,
                document_generation: page.document_generation,
                node: (u64::from(node.generation) << 32) | u64::from(node.slot),
            };
            assert!(matches!(
                page.execute_with_interactability(
                    NativeAction {
                        target,
                        action: SemanticAction::Type,
                        value: Some("changed".into())
                    },
                    false,
                    false
                ),
                Err(RuntimeError::IdentityExhausted { .. })
            ));
            assert_eq!((page.action_ids.last(), page.revision), before);
            assert_eq!(
                page.document.as_ref().unwrap().dom.get(node).unwrap(),
                &original
            );
        }
    }

    #[test]
    fn extraction_scope_prunes_internal_edges_and_rejects_corrupt_light_trees() {
        let mut parsed = crate::html::parse(
            "<body><section id=outer><span id=inner>value</span></section><aside id=last>last</aside></body>",
        );
        let find = |id: &str| {
            parsed
                .dom
                .iter()
                .find_map(|(node, record)| {
                    (record.attributes.get_null("id").map(String::as_str) == Some(id))
                        .then_some(node)
                })
                .unwrap()
        };
        let outer = find("outer");
        let inner = find("inner");
        let last = find("last");
        let hosted = parsed.dom.insert(crate::dom::NodeKind::Document);
        let shadow = parsed.dom.insert(crate::dom::NodeKind::ShadowRoot {
            mode: oryn_dom::ShadowMode::Open,
            clonable: false,
        });
        parsed
            .dom
            .get_mut(outer)
            .unwrap()
            .children
            .extend([hosted, shadow]);
        let (roots, scoped) =
            extraction_scope(&parsed, Some(vec![last, inner, outer, hosted, shadow])).unwrap();
        assert_eq!(roots, vec![outer, last]);
        assert!(scoped.contains(&inner));
        assert!(!scoped.contains(&hosted));
        assert!(!scoped.contains(&shadow));
        let mut cyclic = parsed.clone();
        cyclic.dom.get_mut(inner).unwrap().children.push(outer);
        assert!(matches!(
            extraction_scope(&cyclic, None),
            Err(crate::dom::DomError::Cycle)
        ));
        let mut stale = parsed.clone();
        let text = stale.dom.get(inner).unwrap().children[0];
        stale.dom.remove(text).unwrap();
        stale.dom.get_mut(inner).unwrap().children.push(text);
        assert!(extraction_scope(&stale, None).is_err());
        let mut mismatched = parsed.clone();
        mismatched.dom.get_mut(inner).unwrap().parent = Some(last);
        assert!(matches!(
            extraction_scope(&mismatched, None),
            Err(crate::dom::DomError::Cycle)
        ));
    }

    #[test]
    fn extraction_text_preserves_code_units_cdata_and_deep_tree_errors() {
        let mut dom = oryn_dom::DomRuntime::new();
        let root = dom.create_element("div");
        let mut parent = root;
        for _ in 0..2_000 {
            let child = dom.create_element("div");
            dom.arena_mut()
                .get_mut(parent)
                .unwrap()
                .children
                .push(child);
            dom.arena_mut().get_mut(child).unwrap().parent = Some(parent);
            parent = child;
        }
        for data in [
            oryn_dom::dom_string::from_units(&[0xd83d]),
            oryn_dom::dom_string::from_units(&[0xde00]),
        ] {
            let text = dom.create_text(&data);
            dom.arena_mut().get_mut(parent).unwrap().children.push(text);
        }
        let cdata = dom.arena_mut().insert(oryn_dom::NodeKind::CDataSection {
            data: " XML".into(),
        });
        dom.arena_mut()
            .get_mut(parent)
            .unwrap()
            .children
            .push(cdata);
        assert_eq!(visible_text_content(dom.arena(), root).unwrap(), "😀 XML");
        dom.arena_mut().get_mut(parent).unwrap().children.push(root);
        assert_eq!(
            visible_text_content(dom.arena(), root),
            Err(oryn_dom::DomError::Cycle)
        );
    }
}

